window.WMA13_TOPICS = [{"slug":"01_RationalAlgebra","name":"Rational Algebra","primaryCount":5,"count":64,"crossCount":59},{"slug":"02_Functions","name":"Functions, Composition & Inverses","primaryCount":16,"count":46,"crossCount":30},{"slug":"03_GraphTransformations","name":"Graph Transformations","primaryCount":3,"count":38,"crossCount":35},{"slug":"04_Modulus","name":"Modulus","primaryCount":18,"count":22,"crossCount":4},{"slug":"05_TrigFunctions","name":"Trigonometric Functions & Graphs","primaryCount":0,"count":13,"crossCount":13},{"slug":"06_TrigIdentities","name":"Trig Identities & Exact Values","primaryCount":18,"count":57,"crossCount":39},{"slug":"07_TrigEquations","name":"Trig Equations & R-Form","primaryCount":16,"count":43,"crossCount":27},{"slug":"08_ExponentialsLogs","name":"Exponentials & Logarithms","primaryCount":1,"count":60,"crossCount":59},{"slug":"09_LogGraphsModels","name":"Log Graphs & Exponential Models","primaryCount":35,"count":35,"crossCount":0},{"slug":"10_DifferentiationTechniques","name":"Differentiation Techniques","primaryCount":19,"count":77,"crossCount":58},{"slug":"11_ApplicationsOfDifferentiation","name":"Applications of Differentiation","primaryCount":18,"count":63,"crossCount":45},{"slug":"12_Integration","name":"Integration","primaryCount":17,"count":27,"crossCount":10},{"slug":"13_NumericalMethods","name":"Numerical Methods","primaryCount":14,"count":19,"crossCount":5}];
window.WMA13_QUESTIONS = [{"id":"WMA13-01_2021_Jan_Q03","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":3,"marks":8,"topic":"01_RationalAlgebra","topicName":"Rational Algebra","primaryTopic":"01_RationalAlgebra","primaryTopicName":"Rational Algebra","secondaryTopics":["02_Functions"],"secondaryTopicNames":["Functions, Composition & Inverses"],"topics":["01_RationalAlgebra","02_Functions"],"topicNames":["Rational Algebra","Functions, Composition & Inverses"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q03_M08_01_RationalAlgebra.png","downloadName":"WMA13-01_Y2021_Jan_Q03_M08_01_RationalAlgebra.png","finalAnswer":"(a) $f(x)=\\frac{4x+1}{2x-5},\\ x\\gt 4$\n(b) $f^{-1}(x)=\\frac{5x+1}{2x-4}$\n(c) $2\\lt x\\lt \\frac{17}{3}$","steps":[{"title":"Part (a)","body":"Factor $2x^2-3x-5=(2x-5)(x+1)$. Then\n\n\\[3-\\frac{x-2}{x+1}=\\frac{2x+5}{x+1},\\]\n\nso\n\n\\[f(x)=\\frac{(2x+5)(2x-5)+5x+26}{(x+1)(2x-5)} =\\frac{4x^2+5x+1}{(x+1)(2x-5)} =\\frac{(4x+1)(x+1)}{(x+1)(2x-5)}=\\frac{4x+1}{2x-5}.\\]\n\nOn $x\\gt 4$ the cancelled factor is nonzero. One integer choice is $a=4,b=1,c=2,d=-5$.\n\n\\[\\boxed{f(x)=\\frac{4x+1}{2x-5},\\ x\\gt 4}\\]"},{"title":"Part (b)","body":"Let $y=(4x+1)/(2x-5)$. Rearranging gives $2xy-5y=4x+1$, hence $x(2y-4)=5y+1$ and $x=(5y+1)/(2y-4)$. Swap variable names to obtain the inverse rule; its restricted domain is determined in (c).\n\n\\[\\boxed{f^{-1}(x)=\\frac{5x+1}{2x-4}}\\]"},{"title":"Part (c)","body":"Rewrite $f(x)=2+11/(2x-5)$. For $x\\gt 4$, the positive denominator is greater than 3 and grows without bound. Thus $0\\lt 11/(2x-5)\\lt 11/3$, so $2\\lt f(x)\\lt 17/3$. Neither bound is attained: $x=4$ is excluded and $f(x)=2$ is impossible. The range of f is the domain of its inverse.\n\n\\[\\boxed{2\\lt x\\lt \\frac{17}{3}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q01","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":1,"marks":9,"topic":"01_RationalAlgebra","topicName":"Rational Algebra","primaryTopic":"01_RationalAlgebra","primaryTopicName":"Rational Algebra","secondaryTopics":["02_Functions","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Functions, Composition & Inverses","Differentiation Techniques","Applications of Differentiation"],"topics":["01_RationalAlgebra","02_Functions","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Rational Algebra","Functions, Composition & Inverses","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q01_M09_01_RationalAlgebra.png","downloadName":"WMA13-01_Y2021_Oct_Q01_M09_01_RationalAlgebra.png","finalAnswer":"(a) $f(x)=\\frac{5x}{x+3},\\quad x\\gt 0$\n(b) $f^{-1}(x)=\\frac{3x}{5-x},\\quad0\\lt x\\lt 5$\n(c) $f^{\\prime}(x)=\\frac{15}{(x+3)^2};\\quad f\\text{ is increasing}$","steps":[{"title":"Part (a)","body":"Factor $x^2+7x+12=(x+3)(x+4)$. A common denominator gives\n\n\\[f(x)=\\frac{5x+5x(x+3)}{(x+3)(x+4)} =\\frac{5x(x+4)}{(x+3)(x+4)}=\\frac{5x}{x+3}.\\]\n\nThe cancelled factor is nonzero throughout the original domain $x\\gt 0$.\n\n\\[\\boxed{f(x)=\\frac{5x}{x+3},\\quad x\\gt 0}\\]"},{"title":"Part (b)","body":"Let $y=5x/(x+3)$. Then $yx+3y=5x$, so $x=3y/(5-y)$. Exchange variable names. Since $f(x)=5-15/(x+3)$ for $x\\gt 0$, its range is $0\\lt f(x)\\lt 5$. This becomes the inverse domain.\n\n\\[\\boxed{f^{-1}(x)=\\frac{3x}{5-x},\\quad0\\lt x\\lt 5}\\]"},{"title":"Part (c)","body":"(i) By the quotient rule, $f'(x)=[5(x+3)-5x]/(x+3)^2=15/(x+3)^2$. (ii) The numerator and denominator are positive on $x\\gt 0$, so $f'(x)\\gt 0$ throughout its domain. Therefore f is increasing.\n\n\\[\\boxed{f^{\\prime}(x)=\\frac{15}{(x+3)^2};\\quad f\\text{ is increasing}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q04","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":4,"marks":7,"topic":"01_RationalAlgebra","topicName":"Rational Algebra","primaryTopic":"01_RationalAlgebra","primaryTopicName":"Rational Algebra","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["01_RationalAlgebra","12_Integration"],"topicNames":["Rational Algebra","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q04_M07_01_RationalAlgebra.png","downloadName":"WMA13-01_Y2023_Jan_Q04_M07_01_RationalAlgebra.png","finalAnswer":"(a) $A=2,\\quad B=3,\\quad C=-1,\\quad D=5$\n(b) $\\frac23x^3+\\frac32x^2-x-\\frac5{x+3}+K$","steps":[{"title":"Part (a)","body":"Multiply the proposed identity by $(x+3)^2=x^2+6x+9$ and compare coefficients:\n\n\\[A=2,\\quad6A+B=15\\Rightarrow B=3,\\quad 9A+6B+C=35\\Rightarrow C=-1.\\]\n\nThe coefficient of $x$ checks: $9B+6C=27-6=21$. The constant equation is $9C+D=-4$, so $D=5$. Hence $f(x)=2x^2+3x-1+5(x+3)^{-2}$.\n\n\\[\\boxed{A=2,\\quad B=3,\\quad C=-1,\\quad D=5}\\]"},{"title":"Part (b)","body":"Integrate each term in the decomposition:\n\n\\[\\int f(x)\\,dx=\\int[2x^2+3x-1+5(x+3)^{-2}]\\,dx =\\frac23x^3+\\frac32x^2-x-\\frac5{x+3}+K.\\]\n\nHere $K$ is an arbitrary constant; the domain $x\\gt -3$ avoids the denominator zero.\n\n\\[\\boxed{\\frac23x^3+\\frac32x^2-x-\\frac5{x+3}+K}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q04","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":4,"marks":13,"topic":"01_RationalAlgebra","topicName":"Rational Algebra","primaryTopic":"01_RationalAlgebra","primaryTopicName":"Rational Algebra","secondaryTopics":["02_Functions","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Functions, Composition & Inverses","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["01_RationalAlgebra","02_Functions","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Rational Algebra","Functions, Composition & Inverses","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q04_M13_01_RationalAlgebra.png","downloadName":"WMA13-01_Y2024_Jan_Q04_M13_01_RationalAlgebra.png","finalAnswer":"(a) $f(x)=\\frac{2x}{3x-5},\\quad x\\gt 2$\n(b) $f\\text{ is strictly decreasing on }(2,\\infty)$\n(c) $g^{-1}(x)=e^{(x-3)/2},\\quad x\\ge3$\n(d) $a=\\frac{5e}{3e-2}$","steps":[{"title":"Part (a)","body":"Factor the first denominator:\n\n\\[3x^2+7x-20=(3x-5)(x+4),\\qquad2x^2-32=2(x-4)(x+4).\\]\n\nOn the stated domain $x\\gt 2$, both denominators and $x+4$ are nonzero. Hence\n\n\\[f(x)=\\frac{2(x-4)(x+4)}{(3x-5)(x+4)}+\\frac8{3x-5} =\\frac{2x-8+8}{3x-5}.\\]\n\n\\[\\boxed{f(x)=\\frac{2x}{3x-5},\\quad x\\gt 2}\\]"},{"title":"Part (b)","body":"The quotient rule gives\n\n\\[f'(x)=\\frac{2(3x-5)-3(2x)}{(3x-5)^2}=-\\frac{10}{(3x-5)^2}.\\]\n\nFor every $x\\gt 2$, the squared denominator is positive; hence $f'(x)\\lt 0$. Therefore f is strictly decreasing on its whole domain.\n\n\\[\\boxed{f\\text{ is strictly decreasing on }(2,\\infty)}\\]"},{"title":"Part (c)","body":"Set $y=3+2\\ln x$. Then $\\ln x=(y-3)/2$, so $x=e^{(y-3)/2}$. For $x\\ge1$, the original range is $y\\ge3$. Interchanging the input and output symbols gives the inverse with its domain.\n\n\\[\\boxed{g^{-1}(x)=e^{(x-3)/2},\\quad x\\ge3}\\]"},{"title":"Part (d)","body":"The equation $g(f(a))=5$ gives $3+2\\ln(f(a))=5$, so $\\ln(f(a))=1$ and $f(a)=e$. Using the simplified f,\n\n\\[\\frac{2a}{3a-5}=e\\quad\\Longrightarrow\\quad2a=3ea-5e \\quad\\Longrightarrow\\quad(3e-2)a=5e.\\]\n\nThe resulting value is approximately $2.2083\\gt 2$, and the inner output $e\\ge1$ is admissible for g.\n\n\\[\\boxed{a=\\frac{5e}{3e-2}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q04","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":4,"marks":5,"topic":"01_RationalAlgebra","topicName":"Rational Algebra","primaryTopic":"01_RationalAlgebra","primaryTopicName":"Rational Algebra","secondaryTopics":["10_DifferentiationTechniques"],"secondaryTopicNames":["Differentiation Techniques"],"topics":["01_RationalAlgebra","10_DifferentiationTechniques"],"topicNames":["Rational Algebra","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q04_M05_01_RationalAlgebra.png","downloadName":"WMA13-01_Y2025_MayJune_Q04_M05_01_RationalAlgebra.png","finalAnswer":"(a) $\\frac{7x}{x-3}$\n(b) $f'(x)=-\\frac{21}{(x-3)^2}$","steps":[{"title":"Part (a)","body":"Factor $x^2+x-12=(x+4)(x-3)$ and combine the fractions:\n\n\\[f(x)=\\frac{49x+7x(x-3)}{(x+4)(x-3)} =\\frac{7x(x+4)}{(x+4)(x-3)}=\\boxed{\\frac{7x}{x-3}}.\\]\n\nThe cancellation is valid because $x\\gt 3$. In particular, the numerator simplifies as $49x+7x^2-21x=7x^2+28x=7x(x+4)$."},{"title":"Part (b)","body":"Rewrite $f(x)=7+21/(x-3)$. Differentiating gives\n\n\\[\\boxed{f'(x)=-\\frac{21}{(x-3)^2}}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q02","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":2,"marks":8,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["02_Functions","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q02_M08_02_Functions.png","downloadName":"WMA13-01_Y2020_Jan_Q02_M08_02_Functions.png","finalAnswer":"(a) $fg(e^2)=f(5)=\\frac{12}{5+1}=2$\n(b) $f^{-1}(x)=\\frac{12}{x}-1,\\qquad 0\\lt x\\lt 12$\n(c) $x=3$","steps":[{"title":"Part (a)","body":"First evaluate the inner function:\n\n\\[g(e^2)=\\frac{5}{2}\\ln(e^2)=\\frac{5}{2}\\times2=5.\\]\n\nThen apply $f$ to this result:\n\n\\[\\boxed{fg(e^2)=f(5)=\\frac{12}{5+1}=2.}\\]"},{"title":"Part (b)","body":"Put $y=f(x)$ and rearrange to make $x$ the subject:\n\n\\[y=\\frac{12}{x+1} \\quad\\Longrightarrow\\quad y(x+1)=12 \\quad\\Longrightarrow\\quad x=\\frac{12}{y}-1.\\]\n\nFor $x\\gt 0$, the denominator $x+1\\gt 1$, so $0\\lt f(x)\\lt 12$. Conversely, every $y$ with $0\\lt y\\lt 12$ gives $x=12/y-1\\gt 0$. Thus the range of $f$, and hence the domain of its inverse, is $(0,12)$. Interchanging $x$ and $y$ gives\n\n\\[\\boxed{f^{-1}(x)=\\frac{12}{x}-1,\\qquad 0\\lt x\\lt 12.}\\]"},{"title":"Part (c)","body":"Both functions must be defined, so $0\\lt x\\lt 12$. Substitute the formula for the inverse and multiply by the nonzero quantity $x(x+1)$:\n\n\\[\\begin{aligned} \\frac{12}{x}-1&=\\frac{12}{x+1},\\\\ (12-x)(x+1)&=12x,\\\\ 12+11x-x^2&=12x,\\\\ x^2+x-12&=0,\\\\ (x+4)(x-3)&=0. \\end{aligned}\\]\n\nThe algebraic candidates are $x=-4$ and $x=3$. Reject $x=-4$ because it lies outside $0\\lt x\\lt 12$. For $x=3$, $f^{-1}(3)=12/3-1=3=f(3)$, so the only real solution is\n\n\\[\\boxed{x=3.}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q04","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":4,"marks":10,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","03_GraphTransformations"],"secondaryTopicNames":["Rational Algebra","Graph Transformations"],"topics":["02_Functions","01_RationalAlgebra","03_GraphTransformations"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q04_M10_02_Functions.png","downloadName":"WMA13-01_Y2021_MayJune_Q04_M10_02_Functions.png","finalAnswer":"(a) $x=-\\sqrt{13}$\n(b) $f^{-1}(x)=\\frac{5x+6}{x-4},\\quad x\\ne4$\n(c) $g^{-1}(x)=-\\sqrt{(5-x)/2},\\ x\\le5;\\quad\\text{graphs as shown}$","steps":[{"title":"Part (a)","body":"Substitute $g(x)=5-2x^2$ into f:\n\n\\[fg(x)=\\frac{4(5-2x^2)+6}{5-2x^2-5} =\\frac{26-8x^2}{-2x^2}=4-\\frac{13}{x^2}.\\]\n\nThe composite requires $x\\le0$ from g and $g(x)\\ne5$ from f; therefore $x\\lt 0$. Now $4-13/x^2=3$ gives $x^2=13$. Only the negative root belongs to the composite domain.\n\n\\[\\boxed{x=-\\sqrt{13}}\\]"},{"title":"Part (b)","body":"Let $y=(4x+6)/(x-5)$. Then $yx-5y=4x+6$, so $x(y-4)=5y+6$ and $x=(5y+6)/(y-4)$. Exchange the variable names. The original function is $4+26/(x-5)$, whose range excludes 4.\n\n\\[\\boxed{f^{-1}(x)=\\frac{5x+6}{x-4},\\quad x\\ne4}\\]"},{"title":"Part (c)","body":"The graph of g is only the left half of the downward parabola: $y=5-2x^2$, $x\\le0$. Its intercepts are $(0,5)$ and $(-\\sqrt{5/2},0)$. For the inverse, $x=5-2y^2$ and $y\\le0$, hence $g^{-1}(x)=-\\sqrt{(5-x)/2}$, $x\\le5$. Reflect the original branch in $y=x$. The inverse intercepts are $(5,0)$ and $(0,-\\sqrt{5/2})$.\n\n\\[\\boxed{g^{-1}(x)=-\\sqrt{(5-x)/2},\\ x\\le5;\\quad\\text{graphs as shown}}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2021_MayJune_Q04-1.png","alt":"Sketch for part (c)"}]}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q06","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":6,"marks":11,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"topics":["02_Functions","01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q06_M11_02_Functions.png","downloadName":"WMA13-01_Y2022_Jan_Q06_M11_02_Functions.png","finalAnswer":"(a) $f\\text{ is decreasing for }x\\gt 4$\n(b) $f^{-1}(x)=\\frac{4x-3}{x-5},\\qquad x\\gt 5$\n(c) $ff(x)=\\frac{22x-3}{x+13},\\qquad 5\\lt ff(x)\\lt 22$","steps":[{"title":"Part (a)","body":"By the quotient rule,\n\n\\[f'(x)=\\frac{5(x-4)-(5x-3)}{(x-4)^2}=\\frac{-17}{(x-4)^2}.\\]\n\nFor every $x\\gt 4$, the denominator is positive and the numerator is negative. Therefore $f'(x)\\lt 0$ throughout its domain, so f is decreasing.\n\n\\[\\boxed{f\\text{ is decreasing for }x\\gt 4}\\]"},{"title":"Part (b)","body":"Set $y=(5x-3)/(x-4)$. Then $yx-4y=5x-3$, giving $x(y-5)=4y-3$ and $x=(4y-3)/(y-5)$. Exchange the variable names. Since $f(x)=5+17/(x-4)$ on $x\\gt 4$, its range is $(5,\\infty)$, which becomes the inverse's domain.\n\n\\[\\boxed{f^{-1}(x)=\\frac{4x-3}{x-5},\\qquad x\\gt 5}\\]"},{"title":"Part (c)","body":"(i) For $x\\gt 4$, $f(x)\\gt 5\\gt 4$, so the second application is defined.\n\n\\[ff(x)=\\frac{5\\left(\\frac{5x-3}{x-4}\\right)-3} {\\left(\\frac{5x-3}{x-4}\\right)-4} =\\frac{25x-15-3x+12}{5x-3-4x+16} =\\frac{22x-3}{x+13}.\\]\n\nThus $a=22$, $b=-3$, $c=13$. (ii) Rewrite $ff(x)=22-289/(x+13)$ with the original domain $x\\gt 4$. It is strictly increasing, tends to 5 as $x\\to4^+$ and to 22 as $x\\to\\infty$. Neither limiting value is attained.\n\n\\[\\boxed{ff(x)=\\frac{22x-3}{x+13},\\qquad 5\\lt ff(x)\\lt 22}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q02","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":2,"marks":9,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["02_Functions","01_RationalAlgebra"],"topicNames":["Functions, Composition & Inverses","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q02_M09_02_Functions.png","downloadName":"WMA13-01_Y2022_MayJune_Q02_M09_02_Functions.png","finalAnswer":"(a) $fg(5)=\\frac2{11}$\n(b) $f^{-1}(x)=\\frac{5-2x}{3x+1},\\qquad x\\ne-\\frac13$\n(c) $a=\\frac{1+\\sqrt{33}}8\\quad\\text{or}\\quad a=\\frac{1-\\sqrt{33}}8$","steps":[{"title":"Part (a)","body":"$g(5)=2(5)-7=3$, then $fg(5)=f(3)=(5-3)/(9+2)=2/11$.\n\n\\[\\boxed{fg(5)=\\frac2{11}}\\]"},{"title":"Part (b)","body":"Let $y=(5-x)/(3x+2)$. Then $3xy+2y=5-x$, so $x(3y+1)=5-2y$ and $x=(5-2y)/(3y+1)$. Exchange x and y. The inverse cannot have input $-1/3$, since this is not an output of f: $(5-x)/(3x+2)=-1/3$ would imply $15=-2$.\n\n\\[\\boxed{f^{-1}(x)=\\frac{5-2x}{3x+1},\\qquad x\\ne-\\frac13}\\]"},{"title":"Part (c)","body":"Here $a\\ne0$ and $a\\ne-3/2$ are required by the input and denominator. Substitute into both functions:\n\n\\[f(1/a)=\\frac{5a-1}{3+2a},\\qquad g(a+3)=2a-1.\\]\n\nThus $5a-1=(2a-1)(2a+3)=4a^2+4a-3$, giving $4a^2-a-2=0$. By the quadratic formula, $a=(1\\pm\\sqrt{33})/8$. Neither value is excluded.\n\n\\[\\boxed{a=\\frac{1+\\sqrt{33}}8\\quad\\text{or}\\quad a=\\frac{1-\\sqrt{33}}8}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q02","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":2,"marks":7,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","03_GraphTransformations","04_Modulus","05_TrigFunctions"],"secondaryTopicNames":["Rational Algebra","Graph Transformations","Modulus","Trigonometric Functions & Graphs"],"topics":["02_Functions","01_RationalAlgebra","03_GraphTransformations","04_Modulus","05_TrigFunctions"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Graph Transformations","Modulus","Trigonometric Functions & Graphs"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q02_M07_02_Functions.png","downloadName":"WMA13-01_Y2022_Oct_Q02_M07_02_Functions.png","finalAnswer":"(a) $3\\le f(x)\\lt 5$\n(b) $f^{-1}(x)=\\frac{2x-6}{15-3x},\\qquad3\\le x\\lt 5$\n(c) $fg(-\\pi)=\\frac92$","steps":[{"title":"Part (a)","body":"For $x\\ge0$, $0\\lt 4/(3x+2)\\le2$. Thus $f(0)=3$ is attained, while $f(x)$ increases towards 5 without reaching it.\n\n\\[\\boxed{3\\le f(x)\\lt 5}\\]"},{"title":"Part (b)","body":"(i) Put $y=5-4/(3x+2)$. Rearranging gives $(5-y)(3x+2)=4$, hence\n\n\\[x=\\frac{4/(5-y)-2}{3}=\\frac{2y-6}{15-3y}.\\]\n\nExchange variables. (ii) The inverse domain is the range of $f$ found above.\n\n\\[\\boxed{f^{-1}(x)=\\frac{2x-6}{15-3x},\\qquad3\\le x\\lt 5}\\]"},{"title":"Part (c)","body":"The original function has an absolute value and angle $x/3+\\pi/6$:\n\n\\[g(-\\pi)=|4\\sin(-\\pi/3+\\pi/6)|=|4\\sin(-\\pi/6)|=2.\\]\n\nThen $fg(-\\pi)=f(2)=5-4/(3\\cdot2+2)=5-1/2=9/2$.\n\n\\[\\boxed{fg(-\\pi)=\\frac92}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q01","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":1,"marks":6,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["02_Functions","01_RationalAlgebra"],"topicNames":["Functions, Composition & Inverses","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q01_M06_02_Functions.png","downloadName":"WMA13-01_Y2023_Jan_Q01_M06_02_Functions.png","finalAnswer":"(a) $\\operatorname{range}(f)=(-\\infty,9]$\n(b) $fg(1.5)=\\frac{135}{16}$\n(c) $g^{-1}(x)=\\frac{3-x}{2x},\\qquad0\\lt x\\le3$","steps":[{"title":"Part (a)","body":"For $x\\ge0$, $f(x)=9-x^2$ has maximum $f(0)=9$ and decreases without a lower bound.\n\n\\[\\boxed{\\operatorname{range}(f)=(-\\infty,9]}\\]"},{"title":"Part (b)","body":"Apply $g$ before $f$:\n\n\\[g(1.5)=\\frac3{2(1.5)+1}=\\frac34,\\qquad fg(1.5)=f(3/4)=9-\\left(\\frac34\\right)^2=\\frac{135}{16}.\\]\n\nThe intermediate value $3/4$ is in the nonnegative domain of $f$.\n\n\\[\\boxed{fg(1.5)=\\frac{135}{16}}\\]"},{"title":"Part (c)","body":"Let $y=3/(2x+1)$. Then $y(2x+1)=3$, so $2xy=3-y$ and $x=(3-y)/(2y)$. Exchange the variables. Since $g$ decreases from 3 towards 0 on $[0,\\infty)$, its range is $(0,3]$, which is the inverse domain.\n\n\\[\\boxed{g^{-1}(x)=\\frac{3-x}{2x},\\qquad0\\lt x\\le3}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q04","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":4,"marks":6,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["02_Functions","03_GraphTransformations"],"topicNames":["Functions, Composition & Inverses","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q04_M06_02_Functions.png","downloadName":"WMA13-01_Y2023_MayJune_Q04_M06_02_Functions.png","finalAnswer":"(a) $\\operatorname{range}(f)=[-5,\\infty)$\n(b) $f^{-1}(x)=\\sqrt{\\frac{x+5}{2}},\\quad x\\ge-5$\n(c) $x_P=\\frac{1+\\sqrt{41}}4$","steps":[{"title":"Part (a)","body":"Since $x\\ge0$, $2x^2\\ge0$. The minimum is $f(0)=-5$ and there is no upper bound.\n\n\\[\\boxed{\\operatorname{range}(f)=[-5,\\infty)}\\]"},{"title":"Part (b)","body":"Reflect the given curve in $y=x$. Solving $x=2y^2-5$ with $y\\ge0$ gives $y=\\sqrt{(x+5)/2}$, $x\\ge-5$. The inverse starts at $(-5,0)$, passes through $(0,\\sqrt{5/2})$, and is increasing and concave down. The solid inverse curve below is paired with the dashed original curve.\n\n\\[\\boxed{f^{-1}(x)=\\sqrt{\\frac{x+5}{2}},\\quad x\\ge-5}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2023_MayJune_Q04-1.png","alt":"Sketch for part (b)"}]},{"title":"Part (c)","body":"Here $f$ is strictly increasing on $[0,\\infty)$, so an intersection of $f$ and its inverse must be on $y=x$: if $y=f(x)\\gt x$, then $f(y)\\gt f(x)=y$, contradicting $f(y)=x$; the case $y\\lt x$ is similar. Hence\n\n\\[2x^2-5=x\\quad\\Longrightarrow\\quad 2x^2-x-5=0 \\quad\\Longrightarrow\\quad x=\\frac{1\\pm\\sqrt{41}}4.\\]\n\nReject the negative root because the original curve has $x\\ge0$.\n\n\\[\\boxed{x_P=\\frac{1+\\sqrt{41}}4}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q02","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":2,"marks":8,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["02_Functions","01_RationalAlgebra"],"topicNames":["Functions, Composition & Inverses","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q02_M08_02_Functions.png","downloadName":"WMA13-01_Y2023_Oct_Q02_M08_02_Functions.png","finalAnswer":"(a) $ff(6)=15$\n(b) $f^{-1}(x)=\\frac{4x+3}{x-1},\\qquad x\\ne1$\n(c) $a=11+7\\sqrt2$","steps":[{"title":"Part (a)","body":"Apply $f$ twice, in order:\n\n\\[f(6)=\\frac{6+3}{6-4}=\\frac92,\\qquad ff(6)=f\\left(\\frac92\\right)=\\frac{9/2+3}{9/2-4}=15.\\]\n\n\\[\\boxed{ff(6)=15}\\]"},{"title":"Part (b)","body":"Let $y=(x+3)/(x-4)$. Then\n\n\\[yx-4y=x+3\\quad\\Longrightarrow\\quad x(y-1)=4y+3 \\quad\\Longrightarrow\\quad x=\\frac{4y+3}{y-1}.\\]\n\nInterchanging $x$ and $y$ gives the inverse. The value 1 is never an output of $f$, since $(x+3)/(x-4)=1$ would require $3=-4$.\n\n\\[\\boxed{f^{-1}(x)=\\frac{4x+3}{x-1},\\qquad x\\ne1}\\]"},{"title":"Part (c)","body":"Since $g$ is defined for positive inputs, $gf(a)=7$ requires $f(a)\\gt 0$.\n\n\\[(f(a))^2+5=7\\quad\\Longrightarrow\\quad f(a)=\\sqrt2.\\]\n\nThe negative square root is not in the domain of $g$. Hence\n\n\\[\\frac{a+3}{a-4}=\\sqrt2\\quad\\Longrightarrow\\quad a=\\frac{4\\sqrt2+3}{\\sqrt2-1} =\\frac{(4\\sqrt2+3)(\\sqrt2+1)}{2-1}=11+7\\sqrt2.\\]\n\nThis value is not 4 and gives $f(a)=\\sqrt2\\gt 0$, as required.\n\n\\[\\boxed{a=11+7\\sqrt2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q07","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":7,"marks":10,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"topics":["02_Functions","01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q07_M10_02_Functions.png","downloadName":"WMA13-01_Y2023_Oct_Q07_M10_02_Functions.png","finalAnswer":"(a) $0\\le f(x)\\le9$\n(b) $A=7,\\qquad B=2$\n(c) $16e^{-7/2}\\lt k\\lt 9$","steps":[{"title":"Part (a)","body":"The exponential is positive and the squared factor is nonnegative, so $f(x)\\ge0$. The value zero is attained at $x=\\pm\\sqrt{3/2}$. The graph has its highest point at $x=0$, where $f(0)=9$; the outer maxima are lower. Thus both endpoints of the range are included.\n\n\\[\\boxed{0\\le f(x)\\le9}\\]"},{"title":"Part (b)","body":"For $f(x)=e^{-x^2}(2x^2-3)^2$, product and chain rules give\n\n\\[f'(x)=-2xe^{-x^2}(2x^2-3)^2 +e^{-x^2}\\,2(2x^2-3)\\,4x.\\]\n\nFactoring yields\n\n\\[f'(x)=2x(2x^2-3)e^{-x^2}\\bigl(-(2x^2-3)+4\\bigr) =2x(2x^2-3)e^{-x^2}(7-2x^2).\\]\n\n\\[\\boxed{A=7,\\qquad B=2}\\]"},{"title":"Part (c)","body":"The stationary abscissae are $0$, $\\pm\\sqrt{3/2}$ and $\\pm\\sqrt{7/2}$. At the outer local maxima,\n\n\\[f\\left(\\pm\\sqrt{7/2}\\right)=e^{-7/2}(7-3)^2=16e^{-7/2}.\\]\n\nThe central maximum is 9 and the two minima are zero. Also $f(x)\\to0$ as $x\\to\\pm\\infty$. A positive horizontal line above both outer maxima but below 9 meets only the two sides of the central peak. At $k=16e^{-7/2}$ it also touches both outer peaks, giving four distinct intersections; at $k=9$ there is only one. Both bounds must be excluded.\n\n\\[\\boxed{16e^{-7/2}\\lt k\\lt 9}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q05","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":5,"marks":10,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["02_Functions","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q05_M10_02_Functions.png","downloadName":"WMA13-01_Y2024_MayJune_Q05_M10_02_Functions.png","finalAnswer":"(a) $f^{-1}(22)=e^4$\n(b) $g\\text{ is strictly increasing for }x\\gt \\frac13$\n(c) $g^{-1}(x)=\\frac{x+2}{6-2x},\\quad0\\lt x\\lt 3$\n(d) $\\operatorname{Range}(fg)=(-\\infty,\\,2+5\\ln3)$","steps":[{"title":"Part (a)","body":"To find $f^{-1}(22)$, solve $f(u)=22$: $2+5\\ln u=22$, so $\\ln u=4$ and $u=e^4\\gt 0$.\n\n\\[\\boxed{f^{-1}(22)=e^4}\\]"},{"title":"Part (b)","body":"Using the quotient rule,\n\n\\[g'(x)=\\frac{6(2x+1)-2(6x-2)}{(2x+1)^2} =\\frac{10}{(2x+1)^2}.\\]\n\nFor every $x\\gt 1/3$, the denominator is positive, so $g'(x)\\gt 0$. Thus g is strictly increasing on its entire domain.\n\n\\[\\boxed{g\\text{ is strictly increasing for }x\\gt \\frac13}\\]"},{"title":"Part (c)","body":"Set $y=(6x-2)/(2x+1)$. Then\n\n\\[2xy+y=6x-2,\\qquad (6-2y)x=y+2, \\qquad x=\\frac{y+2}{6-2y}.\\]\n\nAs $x\\downarrow1/3$, $g(x)\\to0$; as $x\\to\\infty$, $g(x)\\to3$. Since g is strictly increasing, its range is $(0,3)$; neither limiting value is attained. Interchange the input and output symbols.\n\n\\[\\boxed{g^{-1}(x)=\\frac{x+2}{6-2x},\\quad0\\lt x\\lt 3}\\]"},{"title":"Part (d)","body":"The inner function g takes every value in $(0,3)$. Since $f(u)=2+5\\ln u$ is increasing for $u\\gt 0$, its values on this interval run from $-\\infty$ to, but not including, $2+5\\ln3$.\n\n\\[\\boxed{\\operatorname{Range}(fg)=(-\\infty,\\,2+5\\ln3)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q06","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":6,"marks":8,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["02_Functions","01_RationalAlgebra"],"topicNames":["Functions, Composition & Inverses","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q06_M08_02_Functions.png","downloadName":"WMA13-01_Y2024_Oct_Q06_M08_02_Functions.png","finalAnswer":"(a) $gf(2)=14$\n(b) $f^{-1}(x)=\\frac{3(x+1)}{2(6-x)},\\quad -1\\le x\\lt 6$\n(c) $x=\\pm\\sqrt6$","steps":[{"title":"Part (a)","body":"First apply $f$: $f(2)=6-21/(2\\cdot2+3)=3$. Then apply $g$: $gf(2)=g(3)=3^2+5$.\n\n\\[\\boxed{gf(2)=14}\\]"},{"title":"Part (b)","body":"Let $y=6-21/(2x+3)$. Then\n\n\\[(6-y)(2x+3)=21,\\qquad x=\\frac12\\left(\\frac{21}{6-y}-3\\right)=\\frac{3(y+1)}{2(6-y)}.\\]\n\nInterchange $x,y$. On the original domain $x\\ge0$, $f$ increases from $f(0)=-1$ towards 6, never attaining 6. Thus the inverse domain is $-1\\le x\\lt 6$.\n\n\\[\\boxed{f^{-1}(x)=\\frac{3(x+1)}{2(6-x)},\\quad -1\\le x\\lt 6}\\]"},{"title":"Part (c)","body":"\\[gg(x)=(x^2+5)^2+5=126 \\quad\\Longrightarrow\\quad(x^2+5)^2=121.\\]\n\nSince $x^2+5\\gt 0$, take $x^2+5=11$, not $-11$. Therefore $x^2=6$.\n\n\\[\\boxed{x=\\pm\\sqrt6}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q06","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":6,"marks":8,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","03_GraphTransformations"],"secondaryTopicNames":["Rational Algebra","Graph Transformations"],"topics":["02_Functions","01_RationalAlgebra","03_GraphTransformations"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q06_M08_02_Functions.png","downloadName":"WMA13-01_Y2025_Jan_Q06_M08_02_Functions.png","finalAnswer":"(a) $f^{-1}(x)=\\frac{2x+3}{x-4},\\quad x\\ne4$\n(b) $ff(x)=\\frac{19x+6}{2x+7},\\quad(a,b,c,d)=(19,6,2,7)$\n(c) $(1,38)$","steps":[{"title":"Part (a)","body":"Let $y=(4x+3)/(x-2)$. Then $yx-2y=4x+3$, so\n\n\\[x(y-4)=2y+3\\quad\\Longrightarrow\\quad x=\\frac{2y+3}{y-4}.\\]\n\nSwap the input and output names. Since $f(x)=4+11/(x-2)$ can never equal 4, the inverse domain excludes 4.\n\n\\[\\boxed{f^{-1}(x)=\\frac{2x+3}{x-4},\\quad x\\ne4}\\]"},{"title":"Part (b)","body":"Substitute $f(x)$ into both occurrences of the argument:\n\n\\[ff(x)=\\frac{4\\left(\\frac{4x+3}{x-2}\\right)+3}{\\left(\\frac{4x+3}{x-2}\\right)-2} =\\frac{4(4x+3)+3(x-2)}{4x+3-2(x-2)}=\\frac{19x+6}{2x+7}.\\]\n\nThus $a=19$, $b=6$, $c=2$, $d=7$. The composite retains $x\\ne2$ from the inner function and also requires $f(x)\\ne2$, that is $x\\ne-7/2$.\n\n\\[\\boxed{ff(x)=\\frac{19x+6}{2x+7},\\quad(a,b,c,d)=(19,6,2,7)}\\]"},{"title":"Part (c)","body":"For $y=2f(3x)+8$, the point mapping is $(x,y)\\mapsto(x/3,2y+8)$. Hence $(3,15)\\mapsto(3/3,2(15)+8)=(1,38)$.\n\n\\[\\boxed{(1,38)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q01","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":1,"marks":8,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Applications of Differentiation"],"topics":["02_Functions","01_RationalAlgebra","11_ApplicationsOfDifferentiation"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q01_M08_02_Functions.png","downloadName":"WMA13-01_Y2025_MayJune_Q01_M08_02_Functions.png","finalAnswer":"(a) $\\frac{15}{4}$\n(b) $0\\leq f(x)\\lt \\frac23$\n(c) $f^{-1}(x)=\\frac{x}{2-3x}$\n(d) $x=0\\quad\\text{or}\\quad x=\\frac13$","steps":[{"title":"Part (a)","body":"First apply $f$, then $g$:\n\n\\[f(1)=\\frac{2}{3+1}=\\frac12,\\qquad gf(1)=4-\\left(\\frac12\\right)^2=\\boxed{\\frac{15}{4}}.\\]"},{"title":"Part (b)","body":"For $x\\geq0$,\n\n\\[f(x)=\\frac23-\\frac{2}{3(3x+1)}.\\]\n\nThus $f(0)=0$ and $f(x)\\lt 2/3$. Also $f'(x)=2/(3x+1)^2\\gt 0$, so the range is\n\n\\[\\boxed{0\\leq f(x)\\lt \\frac23}.\\]"},{"title":"Part (c)","body":"\\[y=\\frac{2x}{3x+1}\\ \\Longrightarrow\\ 3xy+y=2x\\ \\Longrightarrow\\ x=\\frac{y}{2-3y}.\\]\n\nTherefore\n\n\\[\\boxed{f^{-1}(x)=\\frac{x}{2-3x}},\\qquad 0\\leq x\\lt \\frac23.\\]"},{"title":"Part (d)","body":"On the common domain $0\\leq x\\lt 2/3$, both denominators below are nonzero:\n\n\\[\\frac{x}{2-3x}=\\frac{2x}{3x+1} \\ \\Longrightarrow\\ x(3x+1)=2x(2-3x) \\ \\Longrightarrow\\ 3x(3x-1)=0.\\]\n\nBoth candidates lie in the common domain, giving\n\n\\[\\boxed{x=0\\quad\\text{or}\\quad x=\\frac13}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q01","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":1,"marks":9,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["02_Functions","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q01_M09_02_Functions.png","downloadName":"WMA13-01_Y2025_Oct_Q01_M09_02_Functions.png","finalAnswer":"(a) $[ln(3),infinity)$\n(b) $(3-2*x)/(x-5)$; $(-infinity,5)$\n(c) $ln(21/4)$\n(d) $ln(5)/2$","steps":[{"title":"Part (a)","body":"Since $x^2+3\\ge3$, with equality at $x=0$, and the logarithm is increasing, the range of $f$ is $[\\ln3,\\infty)$."},{"title":"Part (b)","body":"Let $y=(3+5x)/(x+2)$. Then\n\n\\[yx+2y=3+5x,\\qquad x(y-5)=3-2y,\\qquad x=\\frac{3-2y}{y-5}.\\]\n\nMoreover, $g(x)=5-7/(x+2)$ with $x\\gt -2$ has range $(-\\infty,5)$. Thus\n\n\\[g^{-1}(x)=\\frac{3-2x}{x-5},\\qquad x\\lt 5.\\]"},{"title":"Part (c)","body":"\\[g(0)=\\frac32,\\qquad fg(0)=\\ln\\left(\\frac94+3\\right)=\\ln\\frac{21}{4}.\\]"},{"title":"Part (d)","body":"\\[f\\left(\\sqrt{e^4-3}\\right)=\\ln(e^4-3+3)=4.\\]\n\nTherefore\n\n\\[\\frac{3+5e^{2a}}{e^{2a}+2}=4 \\Longrightarrow 3+5e^{2a}=4e^{2a}+8 \\Longrightarrow e^{2a}=5.\\]\n\nTaking natural logarithms gives $a=\\frac12\\ln5$. The input $e^{2a}=5$ satisfies the domain of $g$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q05","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":5,"marks":8,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["02_Functions","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Functions, Composition & Inverses","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q05_M08_02_Functions.png","downloadName":"WMA13-01_Y2026_Jan_Q05_M08_02_Functions.png","finalAnswer":"(a) $\\frac{10x-16}{16-x},\\quad x\\ne4,16$\n(b) $f^{-1}(12)=\\frac{32}{5}$\n(c) $a=e^8\\text{ or }e^{-2}$","steps":[{"title":"Part (a)","body":"Substitute $f(x)$ into $f$ and multiply numerator and denominator by $x-4$:\n\n\\[ff(x)=\\frac{2\\left(\\frac{2x+16}{x-4}\\right)+16}{\\frac{2x+16}{x-4}-4} =\\frac{4x+32+16x-64}{2x+16-4x+16} =\\frac{10x-16}{16-x}.\\]\n\nThe composition requires $x\\ne4$ and $f(x)\\ne4$, hence also $x\\ne16$."},{"title":"Part (b)","body":"To find $f^{-1}(12)$, solve $f(x)=12$:\n\n\\[2x+16=12(x-4)\\quad\\Longrightarrow\\quad 10x=64.\\]\n\nThus $f^{-1}(12)=\\frac{32}{5}$."},{"title":"Part (c)","body":"Put $u=\\ln a$. Then $fg(a)=g(a)$ means $f(u)=u$, where $u\\ne4$:\n\n\\[\\frac{2u+16}{u-4}=u \\quad\\Longrightarrow\\quad u^2-6u-16=0 \\quad\\Longrightarrow\\quad (u-8)(u+2)=0.\\]\n\nTherefore $a=e^8$ or $a=e^{-2}$. Both are positive and neither is $e^4$, so both satisfy the domain restrictions."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q02","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":2,"marks":9,"topic":"02_Functions","topicName":"Functions, Composition & Inverses","primaryTopic":"02_Functions","primaryTopicName":"Functions, Composition & Inverses","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["02_Functions","08_ExponentialsLogs"],"topicNames":["Functions, Composition & Inverses","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q02_M09_02_Functions.png","downloadName":"WMA13-01_Y2026_MayJune_Q02_M09_02_Functions.png","finalAnswer":"(a) $(3,\\infty)$\n(b) $g^{-1}(x)=x^2-5,\\qquad x\\gt 0$\n(d) $\\ln\\frac{\\sqrt5}{2}$\n(c) $6$","steps":[{"title":"Part (a)","body":"Since $e^{2x}\\gt 0$ for every real $x$, the range is $\\boxed{(3,\\infty)}$."},{"title":"Part (b)","body":"Put $y=\\sqrt{x+5}$. The original domain is $x\\gt -5$, so $y\\gt 0$. Squaring gives $y^2=x+5$, hence $x=y^2-5$. Interchanging the input and output,\n\n\\[\\boxed{g^{-1}(x)=x^2-5,\\qquad x\\gt 0}.\\]"},{"title":"Part (c)","body":"Evaluate the inside function first:\n\n\\[f(\\ln\\sqrt7)=3+4e^{2\\ln\\sqrt7}=3+4(7)=31, \\qquad gf(\\ln\\sqrt7)=g(31)=\\sqrt{36}=\\boxed6.\\]"},{"title":"Part (d)","body":"Because $a\\gt 0$, $g(a^2-5)=\\sqrt{a^2}=a$, while $g(59)=8$. Thus\n\n\\[3+4e^{2a}=8\\quad\\Longrightarrow\\quad e^{2a}=\\frac54 \\quad\\Longrightarrow\\quad a=\\frac12\\ln\\frac54=\\boxed{\\ln\\frac{\\sqrt5}{2}}.\\]\n\nHere $p=\\sqrt5/2$ is irrational and greater than 1, so the answer satisfies $a\\gt 0$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q02","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":2,"marks":6,"topic":"03_GraphTransformations","topicName":"Graph Transformations","primaryTopic":"03_GraphTransformations","primaryTopicName":"Graph Transformations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_GraphTransformations"],"topicNames":["Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q02_M06_03_GraphTransformations.png","downloadName":"WMA13-01_Y2021_Jan_Q02_M06_03_GraphTransformations.png","finalAnswer":"(i) $(0,0);\\quad\\max(1/2,6);\\quad\\min(3/2,0)$\n(ii) $(0,-1);\\quad\\max(-1,1);\\quad\\min(-3,-1)$","steps":[{"title":"Part (i)","body":"For $y=3f(2x)$, a source point $(u,v)$ maps to $(u/2,3v)$. Thus the y-intercept stays $(0,0)$, the maximum becomes $(1/2,6)$ and the minimum becomes $(3/2,0)$. The horizontal compression and positive vertical stretch preserve the turning-point types. The sketch below records the given shape and mapped features; it does not assume an additional formula for f.\n\n\\[\\boxed{(0,0);\\quad\\max(1/2,6);\\quad\\min(3/2,0)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2021_Jan_Q02-1.png","alt":"Sketch for part (i)"}]},{"title":"Part (ii)","body":"For $y=f(-x)-1$, map $(u,v)$ to $(-u,v-1)$: reflect in the y-axis, then shift down 1. The y-intercept is $(0,-1)$, the maximum is $(-1,1)$ and the minimum is $(-3,-1)$. The left end now rises and the right end falls.\n\n\\[\\boxed{(0,-1);\\quad\\max(-1,1);\\quad\\min(-3,-1)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2021_Jan_Q02-2.png","alt":"Sketch for part (ii)"}]}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q01","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":1,"marks":4,"topic":"03_GraphTransformations","topicName":"Graph Transformations","primaryTopic":"03_GraphTransformations","primaryTopicName":"Graph Transformations","secondaryTopics":["04_Modulus"],"secondaryTopicNames":["Modulus"],"topics":["03_GraphTransformations","04_Modulus"],"topicNames":["Graph Transformations","Modulus"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q01_M04_03_GraphTransformations.png","downloadName":"WMA13-01_Y2024_Jan_Q01_M04_03_GraphTransformations.png","finalAnswer":"(a) $(-2,-3)$\n(b) $(-3,-9)$\n(c) $(-4,3)$","steps":[{"title":"Part (a)","body":"For $y=f(2x)$ the horizontal coordinate is divided by 2 while the vertical coordinate is unchanged: $(-4,-3)\\mapsto(-4/2,-3)$.\n\n\\[\\boxed{(-2,-3)}\\]"},{"title":"Part (b)","body":"The inside shift moves the point right by 1; the outside factor multiplies its ordinate by 3. Thus $(-4,-3)\\mapsto(-4+1,3(-3))$.\n\n\\[\\boxed{(-3,-9)}\\]"},{"title":"Part (c)","body":"Output modulus retains the input and replaces the output by its absolute value: $(-4,-3)\\mapsto(-4,|-3|)$.\n\n\\[\\boxed{(-4,3)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q07","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":7,"marks":10,"topic":"03_GraphTransformations","topicName":"Graph Transformations","primaryTopic":"03_GraphTransformations","primaryTopicName":"Graph Transformations","secondaryTopics":["01_RationalAlgebra","02_Functions","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Functions, Composition & Inverses","Differentiation Techniques","Applications of Differentiation"],"topics":["03_GraphTransformations","01_RationalAlgebra","02_Functions","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Graph Transformations","Rational Algebra","Functions, Composition & Inverses","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q07_M10_03_GraphTransformations.png","downloadName":"WMA13-01_Y2024_Oct_Q07_M10_03_GraphTransformations.png","finalAnswer":"(a) $k=7$\n(b) $P=\\left(-\\frac32,-\\frac{27}{8}\\right)$\n(c) $g(x)\\le\\frac{27}{2}$\n(d) $Q\\mapsto(2,7)$","steps":[{"title":"Part (a)","body":"For $x\\gt -7/4$, apply the product and chain rules:\n\n\\[f'(x)=3x^2\\sqrt{4x+7}+x^3\\frac{2}{\\sqrt{4x+7}} =\\frac{3x^2(4x+7)+2x^3}{\\sqrt{4x+7}} =\\frac{7x^2(2x+3)}{\\sqrt{4x+7}}.\\]\n\n\\[\\boxed{k=7}\\]"},{"title":"Part (b)","body":"The interior stationary values satisfy $x^2(2x+3)=0$, so $x=0$ or $x=-3/2$. Near $x=-3/2$, the derivative changes from negative to positive; near $x=0$ it stays positive on both sides. Thus the minimum turning point is at $x=-3/2$.\n\n\\[f(-3/2)=(-3/2)^3\\sqrt{-6+7}=-27/8.\\]\n\n\\[\\boxed{P=\\left(-\\frac32,-\\frac{27}{8}\\right)}\\]"},{"title":"Part (c)","body":"The endpoint has $f(-7/4)=0$, the global minimum is $-27/8$ and $f(x)$ tends to infinity as $x$ increases. Hence the range of $f$ is $[-27/8,\\infty)$. Multiplication by $-4$ reverses the inequality and makes the upper endpoint $27/2$.\n\n\\[\\boxed{g(x)\\le\\frac{27}{2}}\\]"},{"title":"Part (d)","body":"The transformation is a shift right by $3/2$, vertical stretch by 40, then shift down by 8:\n\n\\[(x,y)\\mapsto(x+3/2,40y-8).\\]\n\nTherefore $Q=(1/2,3/8)$ maps to $(1/2+3/2,\\;40\\cdot3/8-8)$.\n\n\\[\\boxed{Q\\mapsto(2,7)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q06","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":6,"marks":9,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["01_RationalAlgebra","03_GraphTransformations"],"secondaryTopicNames":["Rational Algebra","Graph Transformations"],"topics":["04_Modulus","01_RationalAlgebra","03_GraphTransformations"],"topicNames":["Modulus","Rational Algebra","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q06_M09_04_Modulus.png","downloadName":"WMA13-01_Y2020_Jan_Q06_M09_04_Modulus.png","finalAnswer":"(a) $P=\\left(\\frac52,3\\right)$\n(b) $x=\\frac{15}{7}\\ \\text{or}\\ x=5$\n(c) $\\frac25\\lt k\\lt 4$","steps":[{"title":"Part (a)","body":"At the vertex, the expression inside the modulus is zero:\n\n\\[2x-5=0\\quad\\Longrightarrow\\quad x=\\frac52,\\qquad f\\!\\left(\\frac52\\right)=3.\\]\n\nHence \\(\\boxed{P=\\left(\\frac52,3\\right)}\\)."},{"title":"Part (b)","body":"Write the function in its two branches:\n\n\\[f(x)=\\begin{cases} 13-4x,&0\\leq x\\leq\\frac52,\\\\ 4x-7,&x\\geq\\frac52. \\end{cases}\\]\n\nOn the left branch,\n\n\\[13-4x=3x-2\\quad\\Longrightarrow\\quad 7x=15 \\quad\\Longrightarrow\\quad x=\\frac{15}{7}.\\]\n\nThis lies in \\(0\\leq x\\leq\\frac52\\), so it is valid. On the right branch,\n\n\\[4x-7=3x-2\\quad\\Longrightarrow\\quad x=5.\\]\n\nThis satisfies \\(x\\geq\\frac52\\), so it is also valid. Thus\n\n\\[\\boxed{x=\\frac{15}{7}\\ \\text{or}\\ x=5}.\\]"},{"title":"Part (c)","body":"Each straight branch can have at most one intersection with \\(y=kx+2\\). Two distinct roots therefore require one intersection strictly to each side of the vertex.\n\nFor the left branch,\n\n\\[13-4x=kx+2\\quad\\Longrightarrow\\quad x_L=\\frac{11}{k+4}.\\]\n\nThe condition \\(0\\leq x_L\\lt \\frac52\\) first requires \\(k+4\\gt 0\\), then gives\n\n\\[\\frac{11}{k+4}\\lt \\frac52 \\quad\\Longrightarrow\\quad 22\\lt 5(k+4) \\quad\\Longrightarrow\\quad k\\gt \\frac25.\\]\n\nFor the right branch,\n\n\\[4x-7=kx+2\\quad\\Longrightarrow\\quad x_R=\\frac{9}{4-k}.\\]\n\nThe condition \\(x_R\\gt \\frac52\\) requires \\(k\\lt 4\\), and then\n\n\\[\\frac{9}{4-k}\\gt \\frac52 \\quad\\Longrightarrow\\quad 18\\gt 5(4-k) \\quad\\Longrightarrow\\quad k\\gt \\frac25.\\]\n\nAt \\(k=\\frac25\\), both intersections coincide at the vertex, giving only one root. At \\(k=4\\), the line is parallel to the right branch and has no intersection with that branch, again leaving only one root. Hence\n\n\\[\\boxed{\\frac25\\lt k\\lt 4}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q04","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":4,"marks":8,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions","03_GraphTransformations"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations"],"topics":["04_Modulus","02_Functions","03_GraphTransformations"],"topicNames":["Modulus","Functions, Composition & Inverses","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q04_M08_04_Modulus.png","downloadName":"WMA13-01_Y2020_Oct_Q04_M08_04_Modulus.png","finalAnswer":"(a) $ff(6)=-1$\n(b) $x=\\frac{25}{7}$\n(c) $17\\le k\\lt 21$\n(d) $a=\\frac17,\\qquad b=4$","steps":[{"title":"Part (a)","body":"Apply f twice, in order: $f(6)=21-2|2-6|=13$. Then $ff(6)=f(13)=21-2|2-13|=21-22=-1$. The intermediate input 13 lies in the domain $x\\ge0$.\n\n\\[\\boxed{ff(6)=-1}\\]"},{"title":"Part (b)","body":"For $0\\le x\\le2$, $f(x)=17+2x$, so $17+2x=5x$ gives $x=17/3$, outside that branch; reject it. For $x\\ge2$, $f(x)=25-2x$. Then $25-2x=5x$, giving $x=25/7$. This belongs to the second branch and satisfies the original modulus equation.\n\n\\[\\boxed{x=\\frac{25}{7}}\\]"},{"title":"Part (c)","body":"On the left branch $0\\le x\\le2$, f rises from $f(0)=17$ to $f(2)=21$. The right branch decreases from 21 without lower bound. A horizontal line therefore meets both branches at distinct points exactly when $17\\le k\\lt 21$. At $k=17$, one root is the permitted endpoint $x=0$; at $k=21$, the two intersections merge at the vertex, so 21 is excluded.\n\n\\[\\boxed{17\\le k\\lt 21}\\]"},{"title":"Part (d)","body":"The original vertex is $(2,21)$. Under $y=af(x-b)$ it maps to $(2+b,21a)$. Comparing with $(6,3)$ gives $2+b=6$ and $21a=3$.\n\n\\[\\boxed{a=\\frac17,\\qquad b=4}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q04","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":4,"marks":9,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["04_Modulus","03_GraphTransformations"],"topicNames":["Modulus","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q04_M09_04_Modulus.png","downloadName":"WMA13-01_Y2021_Jan_Q04_M09_04_Modulus.png","finalAnswer":"(a) $P=(-a/3,a)$\n(b) $(-5a,0),\\quad(0,5a)$\n(c) $\\left(-\\frac{5a}{4},\\frac{15a}{4}\\right),\\quad\\left(\\frac{3a}{2},\\frac{13a}{2}\\right)$","steps":[{"title":"Part (a)","body":"At the vertex the inner expression vanishes: $3x+a=0$, giving $x=-a/3$ and $f(x)=a$.\n\n\\[\\boxed{P=(-a/3,a)}\\]"},{"title":"Part (b)","body":"$g(x)=|x+5a|$ is a V translated left by $5a$, with vertex $(-5a,0)$ and y-intercept $(0,5a)$. Since $a\\gt 0$, the vertex lies strictly left of the y-axis. Coordinates in the drawing are normalized by a; labels give the actual intercepts.\n\n\\[\\boxed{(-5a,0),\\quad(0,5a)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2021_Jan_Q04-1.png","alt":"Sketch for part (b)"}]},{"title":"Part (c)","body":"Solve $|x+5a|=|3x+a|+a$ using breakpoints $-5a\\lt -a/3$. For $x\\lt -5a$: $-x-5a=-3x$, giving $x=5a/2$, outside this branch, so reject it. For $-5a\\le x\\lt -a/3$: $x+5a=-3x$, giving $x=-5a/4$ and $y=15a/4$. For $x\\ge-a/3$: $x+5a=3x+2a$, giving $x=3a/2$ and $y=13a/2$. The last two values belong to their respective intervals and satisfy both original functions.\n\n\\[\\boxed{\\left(-\\frac{5a}{4},\\frac{15a}{4}\\right),\\quad\\left(\\frac{3a}{2},\\frac{13a}{2}\\right)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q06","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":6,"marks":8,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["04_Modulus","03_GraphTransformations"],"topicNames":["Modulus","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q06_M08_04_Modulus.png","downloadName":"WMA13-01_Y2021_MayJune_Q06_M08_04_Modulus.png","finalAnswer":"(a) $\\text{(i) }(0,k),(\\pm k/2,0);\\quad\\text{(ii) }(0,k/3),(k/6,0)$\n(b) $x=-\\frac{k}{6},\\qquad x=\\frac{k}{3}$","steps":[{"title":"Part (a)","body":"(i) $y=k-2|x|$ is an inverted V with vertex $(0,k)$ and roots $x=\\pm k/2$. (ii) $y=|2x-k/3|$ is an upright V with vertex $(k/6,0)$ and y-intercept $(0,k/3)$. Because $k\\gt 0$, both sketches have the ordering shown. Axes below use coordinates normalized by k, while labels give the original coordinates.\n\n\\qquad\n\n\\[\\boxed{\\text{(i) }(0,k),(\\pm k/2,0);\\quad\\text{(ii) }(0,k/3),(k/6,0)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2021_MayJune_Q06-1.png","alt":"Sketch for part (a)"},{"src":"assets/solution-diagrams/wma13/WMA13-01_2021_MayJune_Q06-2.png","alt":"Sketch for part (a)"}]},{"title":"Part (b)","body":"Consider the breakpoints $0$ and $k/6$. For $x\\lt 0$, the equation is $k/3-2x=k+2x$, giving $x=-k/6$, valid in this branch. For $0\\le x\\lt k/6$, it is $k/3-2x=k-2x$, impossible because $k\\gt 0$. For $x\\ge k/6$, it is $2x-k/3=k-2x$, giving $x=k/3$, valid in this branch. Both have nonnegative right side and satisfy the original equation.\n\n\\[\\boxed{x=-\\frac{k}{6},\\qquad x=\\frac{k}{3}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q02","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":2,"marks":10,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions","03_GraphTransformations"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations"],"topics":["04_Modulus","02_Functions","03_GraphTransformations"],"topicNames":["Modulus","Functions, Composition & Inverses","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q02_M10_04_Modulus.png","downloadName":"WMA13-01_Y2021_Oct_Q02_M10_04_Modulus.png","finalAnswer":"(a) $P=(13/3,5)$\n(b) $\\text{Range }[5,\\infty);\\qquad ff(4)=10$\n(c) $2\\lt x\\lt \\frac{24}{5}$\n(d) $a=4,\\qquad b=\\frac13$","steps":[{"title":"Part (a)","body":"The modulus vanishes at $3x-13=0$, giving $x=13/3$ and $y=5$.\n\n\\[\\boxed{P=(13/3,5)}\\]"},{"title":"Part (b)","body":"(i) The modulus is nonnegative and attains zero, so the range is $[5,\\infty)$. (ii) $f(4)=|12-13|+5=6$, then $ff(4)=f(6)=|18-13|+5=10$.\n\n\\[\\boxed{\\text{Range }[5,\\infty);\\qquad ff(4)=10}\\]"},{"title":"Part (c)","body":"For $x\\lt 13/3$, $|3x-13|+5=18-3x$. Thus $16-2x\\gt 18-3x$ gives $x\\gt 2$, so this branch contributes $2\\lt x\\lt 13/3$. For $x\\ge13/3$, the right side is $3x-8$. Then $16-2x\\gt 3x-8$ gives $x\\lt 24/5$, so this branch contributes $13/3\\le x\\lt 24/5$. Combine the adjacent intervals.\n\n\\[\\boxed{2\\lt x\\lt \\frac{24}{5}}\\]"},{"title":"Part (d)","body":"The new vertex is at $(13/3-b,5a)$. Therefore $5a=20$ and $13/3-b=4$, giving $a=4$ and $b=1/3$.\n\n\\[\\boxed{a=4,\\qquad b=\\frac13}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q07","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":7,"marks":10,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["04_Modulus","03_GraphTransformations"],"topicNames":["Modulus","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q07_M10_04_Modulus.png","downloadName":"WMA13-01_Y2022_Jan_Q07_M10_04_Modulus.png","finalAnswer":"(a) $V=(-7/2,-10)$\n(b) $x\\le-\\frac{87}{8}\\quad\\text{or}\\quad x\\ge\\frac{45}{4}$\n(c) $\\text{Maximum }(-7/2,10);\\quad\\text{minima }(-27/2,0),(13/2,0)$","steps":[{"title":"Part (a)","body":"At the vertex $2x+7=0$, hence $x=-7/2$ and $f(x)=-10$.\n\n\\[\\boxed{V=(-7/2,-10)}\\]"},{"title":"Part (b)","body":"For $x\\ge-7/2$, $f(x)=x-13/2$. The inequality becomes $x-13/2\\ge x/3+1$, giving $x\\ge45/4$, which satisfies this branch. For $x\\lt -7/2$, $f(x)=-x-27/2$. Then $-x-27/2\\ge x/3+1$, giving $x\\le-87/8$, which satisfies that branch. Join the two permitted outer intervals, including the equality endpoints.\n\n\\[\\boxed{x\\le-\\frac{87}{8}\\quad\\text{or}\\quad x\\ge\\frac{45}{4}}\\]"},{"title":"Part (c)","body":"The zeros of f satisfy $|2x+7|=20$, giving $x=-27/2$ and $x=13/2$. Reflect the part below the x-axis upward, leaving the positive branches unchanged. This creates minima at $(-27/2,0)$ and $(13/2,0)$ and a local maximum at $(-7/2,10)$.\n\n\\[\\boxed{\\text{Maximum }(-7/2,10);\\quad\\text{minima }(-27/2,0),(13/2,0)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2022_Jan_Q07-1.png","alt":"Sketch for part (c)"}]}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q05","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":5,"marks":8,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions"],"secondaryTopicNames":["Functions, Composition & Inverses"],"topics":["04_Modulus","02_Functions"],"topicNames":["Modulus","Functions, Composition & Inverses"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q05_M08_04_Modulus.png","downloadName":"WMA13-01_Y2022_MayJune_Q05_M08_04_Modulus.png","finalAnswer":"(a) $y_A=7,\\qquad x_B=\\frac9k$\n(b) $\\frac7k\\lt x\\lt \\frac{11}k$\n(c) $k\\gt \\frac{18}{5}$","steps":[{"title":"Part (a)","body":"(i) At $x=0$, $f(0)=|-9|-2=7$, so the y coordinate of A is 7. (ii) The minimum occurs when the modulus vanishes: $kx-9=0$, hence $x_B=9/k$.\n\n\\[\\boxed{y_A=7,\\qquad x_B=\\frac9k}\\]"},{"title":"Part (b)","body":"$|kx-9|-2\\lt 0$ means $|kx-9|\\lt 2$, or $-2\\lt kx-9\\lt 2$. Add 9 and divide by the positive k, preserving both strict inequality signs.\n\n\\[\\boxed{\\frac7k\\lt x\\lt \\frac{11}k}\\]"},{"title":"Part (c)","body":"For $x\\le9/k$, the graph is $y=7-kx$; for $x\\ge9/k$, it is $y=kx-11$. The intersection of the right branch with $3-2x$ has $x=14/(k+2)$. For it to lie strictly to the right of the vertex,\n\n\\[\\frac{14}{k+2}\\gt \\frac9k\\ \\Longleftrightarrow\\ 14k\\gt 9k+18 \\ \\Longleftrightarrow\\ k\\gt 18/5.\\]\n\nFor these k, the left-branch intersection has $x=4/(k-2)\\lt 9/k$, so both intersections exist and differ. At $k=18/5$ the two points coincide at the vertex. Each straight branch can supply at most one intersection; when the right branch is inadmissible, two distinct points cannot occur (k=2 gives parallel, unequal left lines).\n\n\\[\\boxed{k\\gt \\frac{18}{5}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q07","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":7,"marks":12,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions","03_GraphTransformations"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations"],"topics":["04_Modulus","02_Functions","03_GraphTransformations"],"topicNames":["Modulus","Functions, Composition & Inverses","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q07_M12_04_Modulus.png","downloadName":"WMA13-01_Y2022_Oct_Q07_M12_04_Modulus.png","finalAnswer":"(a) $(i)\\ (22/3,5),\\qquad(ii)\\ (0,-17)$\n(b) $x=\\frac{17}{3},\\quad9$\n(c) $(-9,0),\\quad(9,0),\\quad(0,-9)$\n(d) $(3,-8),\\qquad(9,0)$","steps":[{"title":"Part (a)","body":"(i) The modulus is zero at $3x-22=0$, giving the vertex $(22/3,5)$. (ii) At $x=0$, $y=5-22=-17$, so the y-axis intersection is $(0,-17)$.\n\n\\[\\boxed{(i)\\ (22/3,5),\\qquad(ii)\\ (0,-17)}\\]"},{"title":"Part (b)","body":"Set $y=0$: $|3x-22|=5$. Thus $3x-22=5$ or $-5$, giving $x=9$ or $17/3$.\n\n\\[\\boxed{x=\\frac{17}{3},\\quad9}\\]"},{"title":"Part (c)","body":"The curve $C_2:y=x^2/9-9$ is an upward-opening parabola, symmetric about the y-axis. Its vertex and y-intercept are $(0,-9)$; setting y=0 gives $x^2=81$, hence x-intercepts $(-9,0)$ and $(9,0)$. The sketch below includes $C_1$ for context and labels all three axis intersections of $C_2$.\n\n\\[\\boxed{(-9,0),\\quad(9,0),\\quad(0,-9)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2022_Oct_Q07-1.png","alt":"Sketch for part (c)"}]},{"title":"Part (d)","body":"For $x\\le22/3$, $C_1$ is $y=3x-17$. Equating to $C_2$ gives\n\n\\[x^2/9-9=3x-17\\ \\Longrightarrow\\ x^2-27x+72=(x-3)(x-24)=0.\\]\n\nOnly $x=3$ belongs to this branch; $y=-8$. For $x\\ge22/3$, $C_1$ is $y=27-3x$. Then\n\n\\[x^2/9-9=27-3x\\ \\Longrightarrow\\ x^2+27x-324=(x-9)(x+36)=0.\\]\n\nOnly $x=9$ belongs to this branch; $y=0$. The rejected candidates 24 and $-36$ lie outside their assumed branch regions.\n\n\\[\\boxed{(3,-8),\\qquad(9,0)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q06","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":6,"marks":8,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["04_Modulus","03_GraphTransformations"],"topicNames":["Modulus","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q06_M08_04_Modulus.png","downloadName":"WMA13-01_Y2023_Jan_Q06_M08_04_Modulus.png","finalAnswer":"(a) $P=(0,3a),\\quad Q=(a,0),\\quad R=(7a/3,0),\\quad S=(5a/3,-2a)$\n(b) $x=\\frac a2,\\qquad x=\\frac{5a}2$","steps":[{"title":"Part (a)","body":"For $y=|3x-5a|-2a$ with $a\\gt 0$: (i) At $x=0$, $y=5a-2a=3a$, so $P=(0,3a)$. (ii) At $y=0$, $|3x-5a|=2a$ gives $3x-5a=\\pm2a$. Thus $x=a$ or $7a/3$; since $a\\lt 7a/3$, $Q=(a,0)$ and $R=(7a/3,0)$. (iii) The modulus vanishes at $x=5a/3$, giving the minimum $S=(5a/3,-2a)$.\n\n\\[\\boxed{P=(0,3a),\\quad Q=(a,0),\\quad R=(7a/3,0),\\quad S=(5a/3,-2a)}\\]"},{"title":"Part (b)","body":"Split $|3x-5a|-2a=|x-2a|$ at $x=5a/3$ and $x=2a$; their order uses $a\\gt 0$. For $x\\lt 5a/3$: $3a-3x=2a-x$, so $x=a/2$, which is in this region. For $5a/3\\le x\\lt 2a$: $3x-7a=2a-x$, so $x=9a/4$; this is outside the assumed region and is rejected. For $x\\ge2a$: $3x-7a=x-2a$, so $x=5a/2$, which is valid. These three regions cover the whole real line, so there are exactly two solutions.\n\n\\[\\boxed{x=\\frac a2,\\qquad x=\\frac{5a}2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q06","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":6,"marks":9,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions","03_GraphTransformations"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations"],"topics":["04_Modulus","02_Functions","03_GraphTransformations"],"topicNames":["Modulus","Functions, Composition & Inverses","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q06_M09_04_Modulus.png","downloadName":"WMA13-01_Y2023_MayJune_Q06_M09_04_Modulus.png","finalAnswer":"(a) $P=(2,-10)$\n(b) $ff(0)=8$\n(c) $x\\gt -\\frac74$\n(d) $x=-\\frac{16}3,\\quad\\frac{16}3$","steps":[{"title":"Part (a)","body":"The modulus is smallest when $x-2=0$, giving $x=2$ and $f(2)=-10$. The two straight-line branches meet there, so this is the vertex of the V-shaped graph.\n\n\\[\\boxed{P=(2,-10)}\\]"},{"title":"Part (b)","body":"First $f(0)=3|0-2|-10=-4$. Then $ff(0)=f(-4)=3|-4-2|-10=18-10=8$. In particular $ff(0)$ means $f(f(0))$, not the square of $f(0)$.\n\n\\[\\boxed{ff(0)=8}\\]"},{"title":"Part (c)","body":"For $x\\lt 2$, the inequality becomes $3(2-x)-10\\lt 5x+10$, so $-4-3x\\lt 5x+10$, giving $x\\gt -7/4$. This yields $-7/4\\lt x\\lt 2$. For $x\\ge2$, it becomes $3x-16\\lt 5x+10$, giving $x\\gt -13$; every $x\\ge2$ satisfies this. The union is $x\\gt -7/4$.\n\n\\[\\boxed{x\\gt -\\frac74}\\]"},{"title":"Part (d)","body":"Let $u=|x|\\ge0$. Then $f(|x|)=0$ gives\n\n\\[3|u-2|-10=0\\quad\\Longrightarrow\\quad u-2=\\pm\\frac{10}3.\\]\n\nThus $u=16/3$ or $u=-4/3$. Reject $u=-4/3$ because $u\\ge0$; $|x|=16/3$ has the two solutions below.\n\n\\[\\boxed{x=-\\frac{16}3,\\quad\\frac{16}3}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q08","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":8,"marks":11,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions","03_GraphTransformations"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations"],"topics":["04_Modulus","02_Functions","03_GraphTransformations"],"topicNames":["Modulus","Functions, Composition & Inverses","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q08_M11_04_Modulus.png","downloadName":"WMA13-01_Y2024_Jan_Q08_M11_04_Modulus.png","finalAnswer":"(a) $\\left(\\frac b2,a\\right);\\quad(0,a-b);\\quad\\left(\\frac{b-a}{2},0\\right),\\ \\left(\\frac{b+a}{2},0\\right)$\n(b) $\\text{Vertex }(0,-1);\\quad\\text{zeros }x=\\pm1$\n(c) $a=11,\\quad b=3$","steps":[{"title":"Part (a)","body":"(i) Since $|2x-b|\\ge0$, the maximum occurs at $2x-b=0$: $x=b/2$ and $y=a$. (ii) At $x=0$, $y=a-|-b|=a-b$ because $b\\gt 0$. (iii) At an x-axis crossing, $|2x-b|=a$, hence $2x-b=\\pm a$. Since $a\\gt b\\gt 0$, $(b-a)/2\\lt 0$ and $(b+a)/2\\gt 0$, matching the sketch.\n\n\\[\\boxed{\\left(\\frac b2,a\\right);\\quad(0,a-b);\\quad\\left(\\frac{b-a}{2},0\\right),\\ \\left(\\frac{b+a}{2},0\\right)}\\]"},{"title":"Part (b)","body":"The graph $y=|x|-1$ is a V with vertex $(0,-1)$ and intercepts $(-1,0)$ and $(1,0)$. Its left branch is $y=-x-1$ for $x\\lt 0$ and its right branch is $y=x-1$ for $x\\ge0$. Add this V to the supplied axes; the original inverted V remains unchanged.\n\nThe grey original curve is schematic; the three labelled points belong to the added graph.\n\n\\[\\boxed{\\text{Vertex }(0,-1);\\quad\\text{zeros }x=\\pm1}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2024_Jan_Q08-1.png","alt":"Sketch for part (b)"}]},{"title":"Part (c)","body":"At $x=-3$, the common ordinate is $|-3|-1=2$. Since $b\\gt 0$, $|-6-b|=6+b$, so $a-(6+b)=2$, giving $a=b+8$. At $x=5$, the common ordinate is $|5|-1=4$, so $a-|10-b|=4$. Substitute $a=b+8$ to obtain $|10-b|=b+4$. If $b\\le10$, then $10-b=b+4$, giving $b=3$, $a=11$. If $b\\gt 10$, then $b-10=b+4$, impossible. Both accepted values satisfy $a\\gt b\\gt 0$.\n\n\\[\\boxed{a=11,\\quad b=3}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q01","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":1,"marks":6,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["04_Modulus","03_GraphTransformations"],"topicNames":["Modulus","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q01_M06_04_Modulus.png","downloadName":"WMA13-01_Y2024_MayJune_Q01_M06_04_Modulus.png","finalAnswer":"(a) $P=(5,10)$\n(b) $x\\lt \\frac52$\n(c) $(7,30)$","steps":[{"title":"Part (a)","body":"The modulus is smallest when $x-5=0$. At $x=5$, $f(5)=10$.\n\n\\[\\boxed{P=(5,10)}\\]"},{"title":"Part (b)","body":"For $x\\lt 5$, $|x-5|=5-x$, so\n\n\\[20-2x\\gt 6x\\quad\\Longrightarrow\\quad x\\lt \\frac52.\\]\n\nThis is consistent with $x\\lt 5$. For $x\\ge5$, $|x-5|=x-5$, so $2x\\gt 6x$, which requires $x\\lt 0$ and is inconsistent with this branch. The equality point $x=5/2$ is excluded because the inequality is strict.\n\n\\[\\boxed{x\\lt \\frac52}\\]"},{"title":"Part (c)","body":"The transformation $y=3f(x-2)$ moves a point $(x,y)$ to $(x+2,3y)$. Thus $P=(5,10)$ moves to $(5+2,3\\cdot10)$.\n\n\\[\\boxed{(7,30)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q03","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":3,"marks":7,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["04_Modulus","03_GraphTransformations"],"topicNames":["Modulus","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q03_M07_04_Modulus.png","downloadName":"WMA13-01_Y2024_Oct_Q03_M07_04_Modulus.png","finalAnswer":"(a) $x=-8\\ \\text{or}\\ x=8$\n(b) $x\\le\\frac{15}{4}\\ \\text{or}\\ x\\ge\\frac{25}{4}$","steps":[{"title":"Part (a)","body":"Set $u=|x|\\ge0$. Then\n\n\\[2u^2-10u=48\\quad\\Longrightarrow\\quad u^2-5u-24=(u-8)(u+3)=0.\\]\n\nReject $u=-3$ since $u\\ge0$. Therefore $|x|=8$.\n\n\\[\\boxed{x=-8\\ \\text{or}\\ x=8}\\]"},{"title":"Part (b)","body":"For $x\\le0$, the right side $\\frac52x\\le0$ and the left side is nonnegative, so every such $x$ satisfies the inequality. For $0\\lt x\\lt 5$, $f(x)\\lt 0$ and\n\n\\[10x-2x^2\\ge\\frac52x \\quad\\Longleftrightarrow\\quad x\\left(\\frac{15}{2}-2x\\right)\\ge0 \\quad\\Longrightarrow\\quad 0\\lt x\\le\\frac{15}{4}.\\]\n\nFor $x\\ge5$, $f(x)\\ge0$ and\n\n\\[2x^2-10x\\ge\\frac52x \\quad\\Longleftrightarrow\\quad x\\left(2x-\\frac{25}{2}\\right)\\ge0 \\quad\\Longrightarrow\\quad x\\ge\\frac{25}{4}.\\]\n\nCombining the cases retains equality at both boundary points.\n\n\\[\\boxed{x\\le\\frac{15}{4}\\ \\text{or}\\ x\\ge\\frac{25}{4}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q07","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":7,"marks":8,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["03_GraphTransformations"],"secondaryTopicNames":["Graph Transformations"],"topics":["04_Modulus","03_GraphTransformations"],"topicNames":["Modulus","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q07_M08_04_Modulus.png","downloadName":"WMA13-01_Y2025_Jan_Q07_M08_04_Modulus.png","finalAnswer":"(a)(i) $\\text{minimum }(a/3,0),\\quad y\\text{-intercept }(0,a)$\n(a)(ii) $\\text{minimum }(a/3,-b),\\quad y\\text{-intercept }(0,a-b)$\n(b) $x=\\frac{a-b}{8}$","steps":[{"title":"Part (a)(i)","body":"For $x\\le a/3$, $y=a-3x$; for $x\\ge a/3$, $y=3x-a$. These two straight branches form a V with minimum $(a/3,0)$ and $y$-intercept $(0,a)$.\n\n\\[\\boxed{\\text{minimum }(a/3,0),\\quad y\\text{-intercept }(0,a)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2025_Jan_Q07-1.png","alt":"Sketch for part (a)(i)"}]},{"title":"Part (a)(ii)","body":"Subtracting $b$ translates the previous graph vertically down by $b$. The minimum becomes $(a/3,-b)$ and the $y$-intercept becomes $(0,a-b)$, which is above the $x$-axis because $a\\gt b\\gt 0$.\n\n\\[\\boxed{\\text{minimum }(a/3,-b),\\quad y\\text{-intercept }(0,a-b)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2025_Jan_Q07-2.png","alt":"Sketch for part (a)(ii)"}]},{"title":"Part (b)","body":"For $x\\le a/3$, the equation becomes $a-3x-b=5x$, giving $x=(a-b)/8$. This is positive and less than $a/8\\lt a/3$, so it satisfies this branch condition. For $x\\ge a/3$, the equation becomes $3x-a-b=5x$, giving $x=-(a+b)/2\\lt 0$. This contradicts $x\\ge a/3\\gt 0$ and must be rejected. Therefore only one solution remains.\n\n\\[\\boxed{x=\\frac{a-b}{8}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q10","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":10,"marks":10,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions"],"secondaryTopicNames":["Functions, Composition & Inverses"],"topics":["04_Modulus","02_Functions"],"topicNames":["Modulus","Functions, Composition & Inverses"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q10_M10_04_Modulus.png","downloadName":"WMA13-01_Y2025_MayJune_Q10_M10_04_Modulus.png","finalAnswer":"(i) $y_A=10+k$\n(ii) $P=\\left(\\frac{10}{k},k\\right)$\n(b) $x\\leq\\frac{10}{k}-1\\quad\\text{or}\\quad x\\geq\\frac{10}{k}+1$\n(c) $3\\lt k\\lt 6$\n(a)(i) $y_A=10+k$\n(a)(ii) $P=\\left(\\frac{10}{k},k\\right)$","steps":[{"title":"Part (i)","body":"At $x=0$, $f(0)=|-10|+k$, so $\\boxed{y_A=10+k}$."},{"title":"Part (ii)","body":"At the vertex the expression inside the modulus vanishes:\n\n\\[kx-10=0\\quad\\Longrightarrow\\quad\\boxed{P=\\left(\\frac{10}{k},k\\right)}.\\]"},{"title":"Part (b)","body":"\\[|kx-10|+k\\geq2k\\quad\\Longleftrightarrow\\quad|kx-10|\\geq k.\\]\n\nSince $k\\gt 0$, the two branches give\n\n\\[kx-10\\leq-k\\quad\\text{or}\\quad kx-10\\geq k,\\]\n\n\\[\\boxed{x\\leq\\frac{10}{k}-1\\quad\\text{or}\\quad x\\geq\\frac{10}{k}+1}.\\]"},{"title":"Part (c)","body":"Consider the vertical difference $d(x)=f(x)-(3x+1)$:\n\n\\[d(x)=\\begin{cases}9+k-(k+3)x,&x\\leq10/k,\\\\ (k-3)x+k-11,&x\\geq10/k. \\end{cases}\\]\n\nThe left branch is strictly decreasing. If $0\\lt k\\lt 3$, the right branch also decreases, so there cannot be two roots. If $k=3$, the right branch is the nonzero constant $-8$, again giving no second root. For $k\\gt 3$ the right branch increases and both outer ends tend to $+\\infty$. There are two distinct roots precisely when the vertex lies below zero:\n\n\\[d(10/k)=k-1-\\frac{30}{k}\\lt 0.\\]\n\nMultiplying by $k\\gt 0$ gives\n\n\\[k^2-k-30=(k-6)(k+5)\\lt 0\\quad\\Longrightarrow\\quad0\\lt k\\lt 6.\\]\n\nCombining with $k\\gt 3$ yields $\\boxed{3\\lt k\\lt 6}$. At $k=6$ the two roots merge at the vertex, so the endpoint is excluded."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q08","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":8,"marks":13,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["01_RationalAlgebra","02_Functions"],"secondaryTopicNames":["Rational Algebra","Functions, Composition & Inverses"],"topics":["04_Modulus","01_RationalAlgebra","02_Functions"],"topicNames":["Modulus","Rational Algebra","Functions, Composition & Inverses"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q08_M13_04_Modulus.png","downloadName":"WMA13-01_Y2025_Oct_Q08_M13_04_Modulus.png","finalAnswer":"(a) Shown, as required.\n(b) $7$; $-8$\n(c) $(8/5,7)$\n(d) $(3/2,15/2)$","steps":[{"title":"Part (a)","body":"Point $P$ lies on the descending branch of $C_2$, where $5x+b\\lt 0$. At $P=(-2,25)$,\n\n\\[25=a-(-10+b)=a+10-b,\\]\n\nhence $a=15+b$."},{"title":"Part (b)","body":"Point $R=(2,9)$ lies on the ascending branch, so\n\n\\[9=a+(10+b)\\Longrightarrow a+b=-1.\\]\n\nCombining with $a-b=15$ gives $2a=14$, hence $a=7$ and $b=-8$."},{"title":"Part (c)","body":"The vertex occurs at $5x-8=0$, giving $(x,y)=(8/5,7)$."},{"title":"Part (d)","body":"The diagram places $Q$ on the descending branch $y=7-(5x-8)=15-5x$, with $x\\lt 8/5$. Equate this with the cubic:\n\n\\[-2x^3+5x^2+4x-3=15-5x \\Longrightarrow 2x^3-5x^2-9x+18=0.\\]\n\nSince $x=-2$ is the known intersection $P$, divide by $x+2$:\n\n\\[2x^3-5x^2-9x+18=(x+2)(2x^2-9x+9) =(x+2)(2x-3)(x-3).\\]\n\nThe candidates are $-2,3/2,3$. Reject $x=3$ because it is outside the descending branch, and $x=-2$ is $P$, not $Q$. Thus $x_Q=3/2$ and $y_Q=15-5(3/2)=15/2$, giving $Q=(3/2,15/2)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q07","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":7,"marks":10,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions","03_GraphTransformations"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations"],"topics":["04_Modulus","02_Functions","03_GraphTransformations"],"topicNames":["Modulus","Functions, Composition & Inverses","Graph Transformations"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q07_M10_04_Modulus.png","downloadName":"WMA13-01_Y2026_Jan_Q07_M10_04_Modulus.png","finalAnswer":"(a) $P=(\\frac{11}{3},-4)$\n(b) $x=\\frac{23}{3}\\text{ or }-\\frac13$\n(c) $m\\lt -3\\quad\\text{or}\\quad m=-\\frac{12}{11}\\quad\\text{or}\\quad m\\ge3$\n(d) $b=5-\\frac{11}{3}=\\frac43,\\qquad a=\\frac{16}{-4}=-4$","steps":[{"title":"Part (a)","body":"At the vertex, $3x-11=0$, so $P=(\\frac{11}{3},-4)$."},{"title":"Part (b)","body":"\\[|3x-11|-4=8\\quad\\Longrightarrow\\quad |3x-11|=12.\\]\n\nThus $3x-11=12$ or $3x-11=-12$, giving $x=\\frac{23}{3}$ or $x=-\\frac13$."},{"title":"Part (c)","body":"Write the two branches explicitly:\n\n\\[f(x)=\\begin{cases}7-3x,&x\\le\\frac{11}{3},\\\\3x-15,&x\\ge\\frac{11}{3}.\\end{cases}\\]\n\nOn the left branch, $mx=7-3x$ gives $x=7/(m+3)$ for $m\\ne-3$. This lies on the left branch precisely when $m\\lt -3$ or $m\\ge-12/11$. On the right branch, $mx=3x-15$ gives $x=15/(3-m)$ for $m\\ne3$. This lies on the right branch precisely when $-12/11\\le m\\lt 3$. At $m=-12/11$, the two branch intersections coincide at the vertex, so there is only one distinct point. For $m\\lt -3$ or $m\\ge3$, only the left intersection exists. At $m=-3$ there is no intersection; at $m=3$ there is one. Consequently the complete answer is\n\n\\[m\\lt -3\\quad\\text{or}\\quad m=-\\frac{12}{11}\\quad\\text{or}\\quad m\\ge3.\\]"},{"title":"Part (d)","body":"Under $y=af(x-b)$, the vertex becomes $(\\frac{11}{3}+b,-4a)$. Equating this with $(5,16)$ gives\n\n\\[b=5-\\frac{11}{3}=\\frac43,\\qquad a=\\frac{16}{-4}=-4.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q09","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":9,"marks":11,"topic":"04_Modulus","topicName":"Modulus","primaryTopic":"04_Modulus","primaryTopicName":"Modulus","secondaryTopics":["02_Functions","12_Integration"],"secondaryTopicNames":["Functions, Composition & Inverses","Integration"],"topics":["04_Modulus","02_Functions","12_Integration"],"topicNames":["Modulus","Functions, Composition & Inverses","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q09_M11_04_Modulus.png","downloadName":"WMA13-01_Y2026_MayJune_Q09_M11_04_Modulus.png","finalAnswer":"(a) $\\frac{11}{2}\\ln|2x+5|+4e^{x-3}+C$\n(b) $(1/b,a)$\n(c) $a=10$, $b=2$\n(d) $A=14.4\\text{ square units}$","steps":[{"title":"Part (a)","body":"\\[\\int\\left(\\frac{11}{2x+5}+4e^{x-3}\\right)\\,dx =\\boxed{\\frac{11}{2}\\ln|2x+5|+4e^{x-3}+C}.\\]\n\nThe absolute value allows both intervals on which the integrand is defined."},{"title":"Part (b)","body":"The largest value of $a-|bx-1|$ occurs when $bx-1=0$. The maximum point is therefore $\\boxed{(1/b,a)}$."},{"title":"Part (c)","body":"At $x=0$, $9=a-1$, so $\\boxed{a=10}$. At the intersection $x=3$, the first curve has height $11/11+4=5$. Thus $10-|3b-1|=5$, giving $3b-1=5$ or $-5$. These give $b=2$ or $-4/3$; only the positive integer is allowed, so $\\boxed{b=2}$."},{"title":"Part (d)","body":"For $x\\geq3$, the required branch of $C_2$ is $y=10-(2x-1)=11-2x$. Its $x$-intercept is $x=11/2$. The shaded area is the area under $C_1$ from 0 to 3 plus the triangle from 3 to $11/2$:\n\n\\[\\begin{aligned} A&=\\int_0^3\\left(\\frac{11}{2x+5}+4e^{x-3}\\right)\\,dx +\\frac12\\left(\\frac{11}{2}-3\\right)5\\\\ &=\\left[\\frac{11}{2}\\ln(2x+5)+4e^{x-3}\\right]_0^3+\\frac{25}{4}\\\\ &=\\frac{11}{2}\\ln\\frac{11}{5}+4(1-e^{-3})+\\frac{25}{4} =14.3873672\\ldots. \\end{aligned}\\]\n\nHence $\\boxed{A=14.4\\text{ square units}}$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q05","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":5,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["01_RationalAlgebra","07_TrigEquations"],"secondaryTopicNames":["Rational Algebra","Trig Equations & R-Form"],"topics":["06_TrigIdentities","01_RationalAlgebra","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Rational Algebra","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q05_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2020_Jan_Q05_M08_06_TrigIdentities.png","finalAnswer":"(a) $5t^4-24t^2-5=0$\n(b) $x=65.9^\\circ,\\quad114.1^\\circ,\\quad245.9^\\circ,\\quad294.1^\\circ$","steps":[{"title":"Part (a)","body":"Let $t=\\tan x$. For the original equation to be defined, $\\sin x\\ne0$, $\\cos x\\ne0$ and $\\cos 2x\\ne0$; hence $t\\ne0$ and $t^2\\ne1$. Using the double-angle and reciprocal identities,\n\n\\[\\tan 2x=\\frac{2\\tan x}{1-\\tan^2x}=\\frac{2t}{1-t^2}, \\qquad \\cot x=\\frac1t, \\qquad \\sec^2x=1+t^2.\\]\n\nSubstituting into the equation gives\n\n\\[\\frac{24t}{1-t^2}+\\frac{5(1+t^2)}{t}=0.\\]\n\nMultiply by the nonzero quantity $t(1-t^2)$ and expand:\n\n\\[\\begin{aligned} 24t^2+5(1+t^2)(1-t^2)&=0,\\\\ 24t^2+5-5t^4&=0. \\end{aligned}\\]\n\nTherefore\n\n\\[\\boxed{5t^4-24t^2-5=0.}\\]"},{"title":"Part (b)","body":"Factor the quadratic in $t^2$:\n\n\\[(5t^2+1)(t^2-5)=0 \\quad\\Longrightarrow\\quad t^2=-\\frac15\\quad\\hbox{or}\\quad t^2=5.\\]\n\nSince $t$ is real, $t^2\\ge0$, so discard $t^2=-1/5$. Thus\n\n\\[\\tan x=t=\\pm\\sqrt5.\\]\n\nIn degrees, let\n\n\\[\\alpha=\\tan^{-1}(\\sqrt5)=65.905157\\ldots{}^\\circ.\\]\n\nTangent is positive in quadrants I and III and negative in quadrants II and IV. The four solutions in $0\\le x\\lt 360^\\circ$ are therefore\n\n\\[x=\\alpha,\\quad180^\\circ-\\alpha,\\quad180^\\circ+\\alpha,\\quad360^\\circ-\\alpha.\\]\n\nThese have finite, nonzero tangent with $t^2=5\\ne1$, so every transformation in part (a) is reversible and all four satisfy the original equation. To one decimal place,\n\n\\[\\boxed{x=65.9^\\circ,\\quad114.1^\\circ,\\quad245.9^\\circ,\\quad294.1^\\circ.}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q05","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":5,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["06_TrigIdentities","12_Integration"],"topicNames":["Trig Identities & Exact Values","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q05_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2020_Oct_Q05_M08_06_TrigIdentities.png","finalAnswer":"(a) $\\sin3x\\equiv3\\sin x-4\\sin^3x$\n(b) $\\frac5{24}$","steps":[{"title":"Part (a)","body":"Start with the angle-addition identity:\n\n\\[\\sin3x=\\sin(2x+x)=\\sin2x\\cos x+\\cos2x\\sin x.\\]\n\nUsing $\\sin2x=2\\sin x\\cos x$ and $\\cos2x=1-2\\sin^2x$,\n\n\\[\\sin3x=2\\sin x\\cos^2x+(1-2\\sin^2x)\\sin x =2\\sin x(1-\\sin^2x)+\\sin x-2\\sin^3x =3\\sin x-4\\sin^3x.\\]\n\n\\[\\boxed{\\sin3x\\equiv3\\sin x-4\\sin^3x}\\]"},{"title":"Part (b)","body":"From (a), $\\sin^3x=(3\\sin x-\\sin3x)/4$. Therefore, using algebraic integration,\n\n\\[\\int_0^{\\pi/3}\\sin^3x\\,dx =\\left[-\\frac34\\cos x+\\frac1{12}\\cos3x\\right]_0^{\\pi/3} =\\left(-\\frac38-\\frac1{12}\\right)-\\left(-\\frac34+\\frac1{12}\\right) =\\frac5{24}.\\]\n\n\\[\\boxed{\\frac5{24}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q07","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":7,"marks":9,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q07_M09_06_TrigIdentities.png","downloadName":"WMA13-01_Y2021_Jan_Q07_M09_06_TrigIdentities.png","finalAnswer":"(a) $\\frac{\\sin2x}{\\cos x}+\\frac{\\cos2x}{\\sin x}=\\csc x$\n(b) $\\theta=\\frac\\pi{12},\\ \\frac{5\\pi}{12},\\ -0.322,\\ -1.25$","steps":[{"title":"Part (a)","body":"Apply the double-angle identities to the left side:\n\n\\[\\frac{2\\sin x\\cos x}{\\cos x}+\\frac{1-2\\sin^2x}{\\sin x} =2\\sin x+\\frac1{\\sin x}-2\\sin x=\\csc x.\\]\n\nAll divisions and cancellations are valid under the given exclusion $x\\ne n\\pi/2$.\n\n\\[\\boxed{\\frac{\\sin2x}{\\cos x}+\\frac{\\cos2x}{\\sin x}=\\csc x}\\]"},{"title":"Part (b)","body":"Using (a) with $x=2\\theta$ gives $7+\\csc2\\theta=3\\cot^22\\theta$. Set $u=\\csc2\\theta$ and use $\\cot^22\\theta=u^2-1$: $3u^2-u-10=(3u+5)(u-2)=0$. Thus $\\sin2\\theta=1/2$ or $\\sin2\\theta=-3/5$. As $-\\pi\\lt 2\\theta\\lt \\pi$, the first gives $2\\theta=\\pi/6,5\\pi/6$. Write $\\gamma=\\arcsin(3/5)$; the second gives $2\\theta=-\\gamma,-\\pi+\\gamma$. Therefore the four values are $\\pi/12,5\\pi/12,-0.3217505544\\ldots,-1.249045772\\ldots$. None makes an original sine or cosine denominator zero.\n\n\\[\\boxed{\\theta=\\frac\\pi{12},\\ \\frac{5\\pi}{12},\\ -0.322,\\ -1.25}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q02","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":2,"marks":9,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q02_M09_06_TrigIdentities.png","downloadName":"WMA13-01_Y2021_MayJune_Q02_M09_06_TrigIdentities.png","finalAnswer":"(a) $k=\\frac12$\n(b) $\\theta=31.4^\\circ,\\quad58.6^\\circ$","steps":[{"title":"Part (a)","body":"Use $1-\\cos2x=2\\sin^2x$ and $\\sin2x=2\\sin x\\cos x$:\n\n\\[\\frac{1-\\cos2x}{2\\sin2x} =\\frac{2\\sin^2x}{4\\sin x\\cos x}=\\frac12\\tan x.\\]\n\nThe source excludes multiples of $90^\\circ$, so the cancelled sine and denominator cosine are nonzero.\n\n\\[\\boxed{k=\\frac12}\\]"},{"title":"Part (b)","body":"Part (a) reduces the equation to $(9/2)\\tan\\theta=2\\sec^2\\theta$. Set $u=\\tan\\theta$ and use $\\sec^2\\theta=1+\\tan^2\\theta$:\n\n\\[4u^2-9u+4=0,\\qquad u=\\frac{9\\pm\\sqrt{17}}8.\\]\n\nBoth roots are positive. On $0\\lt \\theta\\lt 90^\\circ$, tangent is one-to-one, so each gives exactly one angle: $31.36697777\\ldots{}^\\circ$ and $58.63302223\\ldots{}^\\circ$.\n\n\\[\\boxed{\\theta=31.4^\\circ,\\quad58.6^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q04","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":4,"marks":7,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q04_M07_06_TrigIdentities.png","downloadName":"WMA13-01_Y2021_Oct_Q04_M07_06_TrigIdentities.png","finalAnswer":"(a) $\\tan\\theta=2\\sqrt3$\n(b) $x=53.9^{\\circ},\\quad233.9^{\\circ}$","steps":[{"title":"Part (a)","body":"Expand the compound angle using exact values:\n\n\\[2(\\sin\\theta\\cos30^{\\circ}-\\cos\\theta\\sin30^{\\circ})=5\\cos\\theta \\Longrightarrow\\sqrt3\\sin\\theta-\\cos\\theta=5\\cos\\theta.\\]\n\nThus $\\sqrt3\\sin\\theta=6\\cos\\theta$. If $\\cos\\theta=0$, this equation is impossible, so divide by $\\sqrt3\\cos\\theta$: $\\tan\\theta=6/\\sqrt3=2\\sqrt3$.\n\n\\[\\boxed{\\tan\\theta=2\\sqrt3}\\]"},{"title":"Part (b)","body":"Put $\\theta=x+20^{\\circ}$, so $x-10^{\\circ}=\\theta-30^{\\circ}$. Part (a) gives $\\tan(x+20^{\\circ})=2\\sqrt3$. Since $20^{\\circ}\\le\\theta\\le380^{\\circ}$, the two permitted values are $\\theta=73.89788625\\ldots{}^{\\circ}$ and $253.89788625\\ldots{}^{\\circ}$. Subtract $20^{\\circ}$ from both and round last.\n\n\\[\\boxed{x=53.9^{\\circ},\\quad233.9^{\\circ}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q02","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":2,"marks":5,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q02_M05_06_TrigIdentities.png","downloadName":"WMA13-01_Y2022_Jan_Q02_M05_06_TrigIdentities.png","finalAnswer":"(a) $\\sin2\\theta=\\frac34,\\qquad k=\\frac34$\n(b) $\\theta=24.3^{\\circ}$","steps":[{"title":"Part (a)","body":"The original equation requires $\\sin\\theta\\ne0$. Using $\\csc\\theta=1/\\sin\\theta$, multiply by $\\sin\\theta$ to obtain $8\\sin\\theta\\cos\\theta=3$. Since $2\\sin\\theta\\cos\\theta=\\sin2\\theta$, this becomes $4\\sin2\\theta=3$.\n\n\\[\\boxed{\\sin2\\theta=\\frac34,\\qquad k=\\frac34}\\]"},{"title":"Part (b)","body":"For the smallest positive solution take the first positive sine branch: $2\\theta=\\arcsin(3/4)=48.59037789\\ldots{}^{\\circ}$. Divide by two to obtain $\\theta=24.29518895\\ldots{}^{\\circ}$. The supplementary branch gives a larger positive angle.\n\n\\[\\boxed{\\theta=24.3^{\\circ}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q09","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":9,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q09_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2022_Jan_Q09_M08_06_TrigIdentities.png","finalAnswer":"(i) $x=0.983\\ \\text{radians},\\quad\\pi$\n(ii) $\\frac{\\sin3\\theta}{\\sin\\theta}-\\frac{\\cos3\\theta}{\\cos\\theta}=2$","steps":[{"title":"Part (i)","body":"Using $\\sec^2x=1+\\tan^2x$, the equation becomes $2\\tan^2x-3\\tan x=0$, or $\\tan x(2\\tan x-3)=0$. If $\\tan x=0$, the given interval $0\\lt x\\le\\pi$ contains only $x=\\pi$. If $\\tan x=3/2$, the sole root in this interval is $x=\\arctan(3/2)=0.982793723\\ldots$ radians. The excluded pole $x=\\pi/2$ supplies no solution.\n\n\\[\\boxed{x=0.983\\ \\text{radians},\\quad\\pi}\\]"},{"title":"Part (ii)","body":"Use angle addition to expand:\n\n\\[\\sin3\\theta=\\sin2\\theta\\cos\\theta+\\cos2\\theta\\sin\\theta =2\\sin\\theta\\cos^2\\theta+(1-2\\sin^2\\theta)\\sin\\theta =3\\sin\\theta-4\\sin^3\\theta,\\]\n\n\\[\\cos3\\theta=\\cos2\\theta\\cos\\theta-\\sin2\\theta\\sin\\theta =(2\\cos^2\\theta-1)\\cos\\theta-2\\sin^2\\theta\\cos\\theta =4\\cos^3\\theta-3\\cos\\theta.\\]\n\nWhere $\\sin\\theta\\cos\\theta\\ne0$, divide by the stated denominators:\n\n\\[\\frac{\\sin3\\theta}{\\sin\\theta}-\\frac{\\cos3\\theta}{\\cos\\theta} =3-4\\sin^2\\theta-(4\\cos^2\\theta-3) =6-4(\\sin^2\\theta+\\cos^2\\theta)=2.\\]\n\n\\[\\boxed{\\frac{\\sin3\\theta}{\\sin\\theta}-\\frac{\\cos3\\theta}{\\cos\\theta}=2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q07","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":7,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q07_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2022_MayJune_Q07_M08_06_TrigIdentities.png","finalAnswer":"(a) $3\\csc^22\\theta-13\\csc2\\theta-10=0$\n(b) $\\theta=0.101,\\quad1.47\\ \\text{radians}$","steps":[{"title":"Part (a)","body":"On the domain of the original equation, multiply by $\\cos\\theta$:\n\n\\[2\\sin\\theta\\cos\\theta(3\\cot^22\\theta-7)=13 \\ \\Longrightarrow\\ \\sin2\\theta(3\\cot^22\\theta-7)=13.\\]\n\nDivide by the nonzero $\\sin2\\theta$ and use $\\cot^2u=\\csc^2u-1$:\n\n\\[3(\\csc^22\\theta-1)-7=13\\csc2\\theta.\\]\n\nCollect the terms to obtain the displayed equation.\n\n\\[\\boxed{3\\csc^22\\theta-13\\csc2\\theta-10=0}\\]"},{"title":"Part (b)","body":"Put $u=\\csc2\\theta$. Then $(3u+2)(u-5)=0$, so $u=5$ or $-2/3$. The second would give $\\sin2\\theta=-3/2$, which is impossible. For $0\\lt \\theta\\lt \\pi/2$, we have $0\\lt 2\\theta\\lt \\pi$. Thus\n\n\\[2\\theta=\\arcsin(1/5)\\quad\\text{or}\\quad\\pi-\\arcsin(1/5).\\]\n\nHence $\\theta=0.1006789604\\ldots$ or $1.4701173664\\ldots$ radians. Both satisfy the original denominator restrictions.\n\n\\[\\boxed{\\theta=0.101,\\quad1.47\\ \\text{radians}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q09","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":9,"marks":10,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations","12_Integration"],"secondaryTopicNames":["Trig Equations & R-Form","Integration"],"topics":["06_TrigIdentities","07_TrigEquations","12_Integration"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q09_M10_06_TrigIdentities.png","downloadName":"WMA13-01_Y2023_MayJune_Q09_M10_06_TrigIdentities.png","finalAnswer":"(a) $\\frac{\\cos2x}{\\sin x}+\\frac{\\sin2x}{\\cos x}=\\csc x$\n(b) $\\theta=\\frac\\pi4,\\quad0.197\\ \\text{radians}$\n(c) $2-\\sqrt2$","steps":[{"title":"Part (a)","body":"Using a common denominator,\n\n\\[\\frac{\\cos2x}{\\sin x}+\\frac{\\sin2x}{\\cos x} =\\frac{\\cos2x\\cos x+\\sin2x\\sin x}{\\sin x\\cos x} =\\frac{\\cos(2x-x)}{\\sin x\\cos x} =\\frac1{\\sin x}=\\csc x.\\]\n\nThe stated exclusion $x\\ne n\\pi/2$ ensures both denominators are nonzero.\n\n\\[\\boxed{\\frac{\\cos2x}{\\sin x}+\\frac{\\sin2x}{\\cos x}=\\csc x}\\]"},{"title":"Part (b)","body":"By part (a), the squared bracket is $\\csc^2\\theta$. Using $\\csc^2\\theta=1+\\cot^2\\theta$ and setting $u=\\cot\\theta$ gives\n\n\\[1+u^2=6u-4\\quad\\Longrightarrow\\quad u^2-6u+5=(u-1)(u-5)=0.\\]\n\nOn $0\\lt \\theta\\lt \\pi/2$, both positive cotangents are permitted: $u=1$ gives $\\theta=\\pi/4$, while $u=5$ gives $\\tan\\theta=1/5$, $\\theta=0.1973955598\\ldots$ radians.\n\n\\[\\boxed{\\theta=\\frac\\pi4,\\quad0.197\\ \\text{radians}}\\]"},{"title":"Part (c)","body":"The bracket in part (a) equals $\\csc x$. Therefore\n\n\\[\\int_{\\pi/6}^{\\pi/4}\\csc x\\cot x\\,dx =[-\\csc x]_{\\pi/6}^{\\pi/4}=-\\sqrt2-(-2)=2-\\sqrt2.\\]\n\n\\[\\boxed{2-\\sqrt2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q03","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":3,"marks":6,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["06_TrigIdentities","12_Integration"],"topicNames":["Trig Identities & Exact Values","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q03_M06_06_TrigIdentities.png","downloadName":"WMA13-01_Y2023_Oct_Q03_M06_06_TrigIdentities.png","finalAnswer":"(a) $\\cos2A=2\\cos^2 A-1$\n(b) $\\frac\\pi8+\\frac13-\\frac{\\sqrt2}{6}$","steps":[{"title":"Part (a)","body":"Apply the cosine addition formula:\n\n\\[\\cos2A=\\cos(A+A)=\\cos A\\cos A-\\sin A\\sin A =\\cos^2 A-\\sin^2 A.\\]\n\nUsing $\\sin^2 A=1-\\cos^2 A$ gives the required identity.\n\n\\[\\boxed{\\cos2A=2\\cos^2 A-1}\\]"},{"title":"Part (b)","body":"From part (a), $\\cos^2 3x=(1+\\cos6x)/2$. Therefore\n\n\\[\\int_{\\pi/12}^{\\pi/8}(5-4\\cos^2 3x)\\,dx =\\int_{\\pi/12}^{\\pi/8}(3-2\\cos6x)\\,dx =\\left[3x-\\frac13\\sin6x\\right]_{\\pi/12}^{\\pi/8}.\\]\n\nSince $\\sin(3\\pi/4)=\\sqrt2/2$ and $\\sin(\\pi/2)=1$, the result is\n\n\\[\\frac{3\\pi}{8}-\\frac{\\sqrt2}{6}-\\left(\\frac\\pi4-\\frac13\\right).\\]\n\n\\[\\boxed{\\frac\\pi8+\\frac13-\\frac{\\sqrt2}{6}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q08","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":8,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q08_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2023_Oct_Q08_M08_06_TrigIdentities.png","finalAnswer":"(a) $2\\csc^2 2\\theta(1-\\cos2\\theta)=1+\\tan^2\\theta$\n(b) $x=75.5^\\circ,\\qquad284.5^\\circ$","steps":[{"title":"Part (a)","body":"Starting from the left side and using double-angle identities,\n\n\\[2\\csc^2 2\\theta(1-\\cos2\\theta) =\\frac{2(2\\sin^2\\theta)}{(2\\sin\\theta\\cos\\theta)^2} =\\frac1{\\cos^2\\theta}=\\sec^2\\theta=1+\\tan^2\\theta.\\]\n\nThese steps hold wherever the original expression is defined, so $\\sin2\\theta\\ne0$; no claim is made at the excluded angles.\n\n\\[\\boxed{2\\csc^2 2\\theta(1-\\cos2\\theta)=1+\\tan^2\\theta}\\]"},{"title":"Part (b)","body":"By part (a), the equation becomes\n\n\\[\\sec^2x=4+3\\sec x\\quad\\Longrightarrow\\quad (\\sec x-4)(\\sec x+1)=0.\\]\n\nThe branch $\\sec x=4$ gives $\\cos x=1/4$ and hence $x=75.5225\\ldots^\\circ$ or $284.4775\\ldots^\\circ$. The other branch gives $\\cos x=-1$, hence $x=180^\\circ$ in the stated interval. Reject $180^\\circ$: it is a multiple of $90^\\circ$ and the original $\\csc2x$ is undefined there. The two remaining angles satisfy the exclusions.\n\n\\[\\boxed{x=75.5^\\circ,\\qquad284.5^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q04","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":4,"marks":9,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["03_GraphTransformations","05_TrigFunctions","07_TrigEquations"],"secondaryTopicNames":["Graph Transformations","Trigonometric Functions & Graphs","Trig Equations & R-Form"],"topics":["06_TrigIdentities","03_GraphTransformations","05_TrigFunctions","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Graph Transformations","Trigonometric Functions & Graphs","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q04_M09_06_TrigIdentities.png","downloadName":"WMA13-01_Y2024_MayJune_Q04_M09_06_TrigIdentities.png","finalAnswer":"(a) $a=4,\\quad b=2,\\quad c=-1$\n(b) $R=2\\sqrt5,\\quad\\alpha=0.464\\ \\text{radians},\\quad c=-1$\n(c) $\\max f=2\\sqrt5-1,\\quad x=3.70\\ \\text{radians}$","steps":[{"title":"Part (a)","body":"Use $\\sin2x=2\\sin x\\cos x$ and $2\\cos^2x=1+\\cos2x$:\n\n\\[f(x)=4\\sin2x+2(1+\\cos2x)-3=4\\sin2x+2\\cos2x-1.\\]\n\n\\[\\boxed{a=4,\\quad b=2,\\quad c=-1}\\]"},{"title":"Part (b)","body":"Expanding $R\\sin(2x+\\alpha)$ and matching coefficients gives\n\n\\[R\\cos\\alpha=4,\\qquad R\\sin\\alpha=2.\\]\n\nSquaring and adding, $R^2=20$, so $R=2\\sqrt5$ since $R\\gt 0$. Also $\\tan\\alpha=1/2$, and $0\\lt \\alpha\\lt \\pi/2$ selects $\\alpha=\\arctan(1/2)=0.463647609\\ldots$ radians. Thus $f(x)=2\\sqrt5\\sin(2x+\\arctan(1/2))-1$. With the phase displayed to 3 significant figures, $f(x)\\approx2\\sqrt5\\sin(2x+0.464)-1$.\n\n\\[\\boxed{R=2\\sqrt5,\\quad\\alpha=0.464\\ \\text{radians},\\quad c=-1}\\]"},{"title":"Part (c)","body":"(i) The sine term has maximum 1, hence the maximum of $f$ is $2\\sqrt5-1$. (ii) Maxima occur when\n\n\\[2x+\\alpha=\\frac\\pi2+2k\\pi, \\qquad x=\\frac\\pi4-\\frac\\alpha2+k\\pi.\\]\n\nThe value for $k=0$ is $0.553574\\ldots\\gt 0$, while $k=-1$ is negative. The second positive value therefore has $k=1$:\n\n\\[x=\\frac{5\\pi}{4}-\\frac12\\arctan(1/2)=3.695167\\ldots.\\]\n\n\\[\\boxed{\\max f=2\\sqrt5-1,\\quad x=3.70\\ \\text{radians}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q07","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":7,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["01_RationalAlgebra","07_TrigEquations"],"secondaryTopicNames":["Rational Algebra","Trig Equations & R-Form"],"topics":["06_TrigIdentities","01_RationalAlgebra","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Rational Algebra","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q07_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2024_MayJune_Q07_M08_06_TrigIdentities.png","finalAnswer":"(a) $\\tan x=-2-\\sqrt3$\n(b) $\\theta=75^\\circ,\\ 165^\\circ$","steps":[{"title":"Part (a)","body":"Expand both compound angles:\n\n\\[\\sin x+\\cos x=\\frac12\\cos x+\\frac{\\sqrt3}{2}\\sin x.\\]\n\nThus $(2-\\sqrt3)\\sin x=-\\cos x$. Here $\\cos x\\ne0$: otherwise this equation would require $\\sin x=0$ as well, which is impossible. Dividing by $(2-\\sqrt3)\\cos x$ gives\n\n\\[\\tan x=-\\frac1{2-\\sqrt3} =-\\frac{2+\\sqrt3}{(2-\\sqrt3)(2+\\sqrt3)}.\\]\n\n\\[\\boxed{\\tan x=-2-\\sqrt3}\\]"},{"title":"Part (b)","body":"Set $x=2\\theta-45^\\circ$. Then $x+45^\\circ=2\\theta$ and $x-60^\\circ=2\\theta-105^\\circ$, so part (a) gives $\\tan(2\\theta-45^\\circ)=-2-\\sqrt3$. Since $\\tan75^\\circ=2+\\sqrt3$,\n\n\\[2\\theta-45^\\circ=-75^\\circ+180^\\circ k, \\qquad\\theta=-15^\\circ+90^\\circ k.\\]\n\nIn $0\\le\\theta\\lt 180^\\circ$, only $k=1,2$ are allowed. Substitution in the original equation confirms both values.\n\n\\[\\boxed{\\theta=75^\\circ,\\ 165^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q05","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":5,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q05_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2024_Oct_Q05_M08_06_TrigIdentities.png","finalAnswer":"(a) $P=3,\\quad Q=-4$\n(b) $\\theta=100.1^\\circ,\\ 180^\\circ,\\ 259.9^\\circ,\\ 360^\\circ$","steps":[{"title":"Part (a)","body":"Expand $\\sin(2x+x)$ using the addition formula:\n\n\\[\\sin3x=\\sin2x\\cos x+\\cos2x\\sin x =2\\sin x\\cos^2x+(1-2\\sin^2x)\\sin x.\\]\n\nNow use $\\cos^2x=1-\\sin^2x$:\n\n\\[\\sin3x=2\\sin x(1-\\sin^2x)+\\sin x-2\\sin^3x =3\\sin x-4\\sin^3x.\\]\n\n\\[\\boxed{P=3,\\quad Q=-4}\\]"},{"title":"Part (b)","body":"Substitute the identity and $\\sin2\\theta=2\\sin\\theta\\cos\\theta$:\n\n\\[6\\sin\\theta-8\\sin^3\\theta=10\\sin\\theta\\cos\\theta.\\]\n\nFactor without dividing by $\\sin\\theta$:\n\n\\[2\\sin\\theta(4\\cos^2\\theta-5\\cos\\theta-1)=0.\\]\n\nIf $\\sin\\theta=0$, the permitted solutions are $180^\\circ$ and $360^\\circ$ (not $0^\\circ$). Otherwise $\\cos\\theta=(5\\pm\\sqrt{41})/8$. The plus value exceeds 1 and is rejected. The minus value gives $\\theta=100.1013\\ldots^\\circ$ or $259.8986\\ldots^\\circ$.\n\n\\[\\boxed{\\theta=100.1^\\circ,\\ 180^\\circ,\\ 259.9^\\circ,\\ 360^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q08","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":8,"marks":8,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q08_M08_06_TrigIdentities.png","downloadName":"WMA13-01_Y2025_MayJune_Q08_M08_06_TrigIdentities.png","finalAnswer":"(a) $\\frac{3\\tan x-\\tan^3x}{1-3\\tan^2x}$\n(b) $\\theta=0.37,\\ 0.72,\\ 1.42\\text{ radians}$","steps":[{"title":"Part (a)","body":"Put $s=\\sin x$ and $c=\\cos x$. Using the addition and double-angle formulae,\n\n\\[\\sin3x=\\sin2x\\cos x+\\cos2x\\sin x=3sc^2-s^3,\\]\n\n\\[\\cos3x=\\cos2x\\cos x-\\sin2x\\sin x=c^3-3s^2c.\\]\n\nWhere the stated expressions are defined, $c\\ne0$ and $\\cos3x\\ne0$. Dividing numerator and denominator by $c^3$ gives\n\n\\[\\tan3x=\\frac{3sc^2-s^3}{c^3-3s^2c} =\\boxed{\\frac{3\\tan x-\\tan^3x}{1-3\\tan^2x}}.\\]"},{"title":"Part (b)","body":"By part (a), the equation is $\\tan3\\theta=2\\sec^2 3\\theta-8$. Set $u=\\tan3\\theta$ and use $\\sec^2 3\\theta=1+u^2$:\n\n\\[u=2(1+u^2)-8\\ \\Longrightarrow\\ 2u^2-u-6=0 \\ \\Longrightarrow\\ (2u+3)(u-2)=0.\\]\n\nThus $\\tan3\\theta=2$ or $\\tan3\\theta=-3/2$. The transformed interval is $0\\lt 3\\theta\\lt 3\\pi/2$. Its three allowed angles are\n\n\\[3\\theta=\\arctan2,\\quad \\pi-\\arctan\\frac32,\\quad \\pi+\\arctan2.\\]\n\nConsequently\n\n\\[\\theta=0.36904957\\ldots,\\quad0.71959964\\ldots,\\quad1.41624712\\ldots,\\]\n\n\\[\\boxed{\\theta=0.37,\\ 0.72,\\ 1.42\\text{ radians}}.\\]\n\nNone lies at an excluded pole of either side."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q09","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":9,"marks":9,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["06_TrigIdentities","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q09_M09_06_TrigIdentities.png","downloadName":"WMA13-01_Y2025_Oct_Q09_M09_06_TrigIdentities.png","finalAnswer":"(a) $3*(1-cos(2*theta))*cos(2*theta)/sin(2*theta)+2*sin(2*theta)$\n(b) Shown, as required.\n(c) $5.8 degrees$; $84.2 degrees$","steps":[{"title":"Part (a)","body":"Use $2\\sin^2\\theta=1-\\cos2\\theta$, $\\cot2\\theta=\\cos2\\theta/\\sin2\\theta$, and $2\\sin\\theta\\cos\\theta=\\sin2\\theta$:\n\n\\[6\\sin^2\\theta\\cot2\\theta+4\\sin\\theta\\cos\\theta =\\frac{3(1-\\cos2\\theta)\\cos2\\theta}{\\sin2\\theta}+2\\sin2\\theta.\\]\n\nThis is in terms of $\\sin2\\theta$ and $\\cos2\\theta$ only, on the original domain $\\sin2\\theta\\ne0$."},{"title":"Part (b)","body":"Substitute the preceding expression and multiply by $\\sin2\\theta$:\n\n\\[3\\cos2\\theta-14\\sin2\\theta =3\\cos2\\theta-3\\cos^22\\theta+2\\sin^22\\theta.\\]\n\nCancel $3\\cos2\\theta$ and use $\\cos^22\\theta=1-\\sin^22\\theta$:\n\n\\[-14\\sin2\\theta=-3+5\\sin^22\\theta.\\]\n\nHence $5\\sin^22\\theta+14\\sin2\\theta-3=0$."},{"title":"Part (c)","body":"Let $s=\\sin2x$. Then $(5s-1)(s+3)=0$, so $s=1/5$ or $s=-3$. The latter is impossible. As $0\\lt 2x\\lt 180^\\circ$,\n\n\\[2x=\\arcsin(1/5)=11.53695903\\ldots^\\circ \\quad\\hbox{or}\\quad 180^\\circ-11.53695903\\ldots^\\circ.\\]\n\nTherefore $x=5.8^\\circ$ or $84.2^\\circ$ to one decimal place. Both have nonzero $\\sin2x$, so the original cotangent is defined."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q06","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":6,"marks":7,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["01_RationalAlgebra","07_TrigEquations"],"secondaryTopicNames":["Rational Algebra","Trig Equations & R-Form"],"topics":["06_TrigIdentities","01_RationalAlgebra","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Rational Algebra","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q06_M07_06_TrigIdentities.png","downloadName":"WMA13-01_Y2026_Jan_Q06_M07_06_TrigIdentities.png","finalAnswer":"(a) $\\frac{3+\\sqrt3}{6}$\n(b) $x=24.1^\\circ\\text{ or }114.1^\\circ$","steps":[{"title":"Part (a)","body":"Expanding the compound angle,\n\n\\[2\\bigl(\\cos\\theta\\cos60^\\circ+\\sin\\theta\\sin60^\\circ\\bigr)=3\\sin\\theta,\\]\n\nso $\\cos\\theta+\\sqrt3\\sin\\theta=3\\sin\\theta$ and $\\cos\\theta=(3-\\sqrt3)\\sin\\theta$. If $\\cos\\theta=0$, this equation would require $\\sin\\theta=0$, which is impossible. We may therefore divide by $\\cos\\theta$:\n\n\\[\\tan\\theta=\\frac1{3-\\sqrt3} =\\frac{3+\\sqrt3}{9-3}=\\frac{3+\\sqrt3}{6}.\\]"},{"title":"Part (b)","body":"Set $\\theta=2x-10^\\circ$, so $2x-70^\\circ=\\theta-60^\\circ$ and $-10^\\circ\\le\\theta\\lt 350^\\circ$.\n\n\\[\\theta=\\arctan\\!\\left(\\frac{3+\\sqrt3}{6}\\right)+180^\\circ n =38.2619662\\ldots^\\circ+180^\\circ n.\\]\n\nThe admissible values are $38.2619662\\ldots^\\circ$ and $218.2619662\\ldots^\\circ$. Hence $x=(\\theta+10^\\circ)/2$, giving $x=24.1^\\circ$ or $114.1^\\circ$ (1 decimal place)."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q08","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":8,"marks":9,"topic":"06_TrigIdentities","topicName":"Trig Identities & Exact Values","primaryTopic":"06_TrigIdentities","primaryTopicName":"Trig Identities & Exact Values","secondaryTopics":["01_RationalAlgebra","07_TrigEquations"],"secondaryTopicNames":["Rational Algebra","Trig Equations & R-Form"],"topics":["06_TrigIdentities","01_RationalAlgebra","07_TrigEquations"],"topicNames":["Trig Identities & Exact Values","Rational Algebra","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q08_M09_06_TrigIdentities.png","downloadName":"WMA13-01_Y2026_MayJune_Q08_M09_06_TrigIdentities.png","finalAnswer":"(a) $\\cos2\\theta$\n(b) $5\\cos^2 2\\theta-13\\cos2\\theta-6=0$\n(c) $x=56.8^\\circ\\text{ or }123.2^\\circ$","steps":[{"title":"Part (a)","body":"For angles where the original expression is defined,\n\n\\[\\frac{\\sec\\theta\\,\\operatorname{cosec}\\theta}{4\\operatorname{cosec}4\\theta} =\\frac{\\sin4\\theta}{4\\sin\\theta\\cos\\theta} =\\frac{2\\sin2\\theta\\cos2\\theta}{2\\sin2\\theta} =\\boxed{\\cos2\\theta}.\\]"},{"title":"Part (b)","body":"Divide the given equation by $4\\operatorname{cosec}4\\theta$ and use (a):\n\n\\[5\\cos^2\\theta-9=3(1+\\tan^2 2\\theta)\\cos2\\theta =\\frac3{\\cos2\\theta}.\\]\n\nUse $\\cos^2\\theta=(1+\\cos2\\theta)/2$ and multiply by $2\\cos2\\theta$:\n\n\\[(5\\cos2\\theta-13)\\cos2\\theta=6.\\]\n\nTherefore\n\n\\[\\boxed{5\\cos^2 2\\theta-13\\cos2\\theta-6=0}, \\qquad a=5,\\ b=-13,\\ c=-6.\\]\n\nThe divisions are valid on the domain of the original equation."},{"title":"Part (c)","body":"Set $u=\\cos2x$:\n\n\\[5u^2-13u-6=(5u+2)(u-3)=0.\\]\n\nReject $u=3$ because cosine lies between $-1$ and $1$. Thus $\\cos2x=-2/5$. Since $0\\lt 2x\\lt 360^\\circ$,\n\n\\[2x=113.5781785\\ldots^\\circ\\quad\\hbox{or}\\quad246.4218215\\ldots^\\circ.\\]\n\nHence $\\boxed{x=56.8^\\circ\\text{ or }123.2^\\circ}$ to one decimal place. Neither is an excluded multiple of $45^\\circ$; these are all the solutions in the interval."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q09","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":9,"marks":7,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q09_M07_07_TrigEquations.png","downloadName":"WMA13-01_Y2020_Jan_Q09_M07_07_TrigEquations.png","finalAnswer":"(a) $R=\\sqrt{41}$, $\\alpha=0.675\\text{ radians (3 d.p.)}$, $f(\\theta)=\\sqrt{41}\\cos\\!\\left(\\theta+\\arctan\\!\\frac45\\right)$\n(b)(i) $\\sqrt{41}$\n(b)(ii) $\\begin{pmatrix}-\\alpha\\\\0\\end{pmatrix}$\n(c) $2\\leq g(\\theta)\\leq\\frac{45}{2}$","steps":[{"title":"Part (a)","body":"Expanding the required form gives\n\n\\[R\\cos(\\theta+\\alpha) =R\\cos\\alpha\\cos\\theta-R\\sin\\alpha\\sin\\theta.\\]\n\nComparing coefficients with \\(5\\cos\\theta-4\\sin\\theta\\),\n\n\\[R\\cos\\alpha=5,\\qquad R\\sin\\alpha=4.\\]\n\nSquaring and adding, using \\(R\\gt 0\\), gives\n\n\\[R^2=5^2+4^2=41\\quad\\Longrightarrow\\quad\\boxed{R=\\sqrt{41}}.\\]\n\nAlso, since \\(0\\lt \\alpha\\lt \\frac\\pi2\\),\n\n\\[\\tan\\alpha=\\frac45,\\qquad \\alpha=\\arctan\\!\\left(\\frac45\\right)=0.6747409\\ldots \\quad\\Longrightarrow\\quad\\boxed{\\alpha=0.675\\text{ radians (3 d.p.)}}.\\]\n\nThus the exact form is\n\n\\[\\boxed{f(\\theta)=\\sqrt{41}\\cos\\!\\left(\\theta+\\arctan\\!\\frac45\\right)}.\\]"},{"title":"Part (b)(i)","body":"A stretch parallel to the \\(y\\)-axis with scale factor \\(\\boxed{\\sqrt{41}}\\), taking \\(y=\\cos\\theta\\) to \\(y=\\sqrt{41}\\cos\\theta\\)."},{"title":"Part (b)(ii)","body":"A translation by the vector\n\n\\[\\boxed{\\begin{pmatrix}-\\alpha\\\\0\\end{pmatrix}} =\\begin{pmatrix}-\\arctan(4/5)\\\\0\\end{pmatrix} \\approx\\begin{pmatrix}-0.675\\\\0\\end{pmatrix}.\\]\n\nThis moves the curve \\(\\alpha\\) units to the left, giving \\(y=\\sqrt{41}\\cos(\\theta+\\alpha)\\)."},{"title":"Part (c)","body":"Since \\(\\theta\\) can be any real number,\n\n\\[-\\sqrt{41}\\leq f(\\theta)\\leq\\sqrt{41} \\quad\\Longrightarrow\\quad 0\\leq(f(\\theta))^2\\leq41.\\]\n\nHence \\(4\\leq4+(f(\\theta))^2\\leq45\\). Taking reciprocals of these positive bounds and multiplying by \\(90\\) gives\n\n\\[\\boxed{2\\leq g(\\theta)\\leq\\frac{45}{2}}.\\]\n\nBoth endpoints are attained: the minimum occurs when \\(f(\\theta)=\\pm\\sqrt{41}\\), and the maximum when \\(f(\\theta)=0\\)."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q01","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":1,"marks":5,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["07_TrigEquations","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q01_M05_07_TrigEquations.png","downloadName":"WMA13-01_Y2020_Oct_Q01_M05_07_TrigEquations.png","finalAnswer":"(main) $x=104.5^\\circ,\\quad255.5^\\circ$","steps":[{"title":"Part (main)","body":"Use $\\cos2x=2\\cos^2x-1$ and put $u=\\cos x$:\n\n\\[2(2u^2-1)=7u\\quad\\Longrightarrow\\quad4u^2-7u-2=(4u+1)(u-2)=0.\\]\n\nThe value $u=2$ is impossible since $-1\\le\\cos x\\le1$. Thus $\\cos x=-1/4$. In $0\\le x\\lt 360^\\circ$, the solutions lie in quadrants II and III:\n\n\\[x=\\arccos(-1/4)=104.477512\\ldots^\\circ,\\qquad x=360^\\circ-104.477512\\ldots^\\circ=255.522487\\ldots^\\circ.\\]\n\n\\[\\boxed{x=104.5^\\circ,\\quad255.5^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q07","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":7,"marks":9,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["01_RationalAlgebra","02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Rational Algebra","Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","01_RationalAlgebra","02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Rational Algebra","Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q07_M09_07_TrigEquations.png","downloadName":"WMA13-01_Y2020_Oct_Q07_M09_07_TrigEquations.png","finalAnswer":"(a) $R=\\sqrt{17},\\qquad\\alpha=1.326\\text{ radians}$\n(b) $H_{\\min}=3.37\\ \\mathrm m$\n(c) $t=6.09\\ \\mathrm s$","steps":[{"title":"Part (a)","body":"Expand $R\\cos(x-\\alpha)=R\\cos\\alpha\\cos x+R\\sin\\alpha\\sin x$. Matching coefficients gives $R\\cos\\alpha=1$, $R\\sin\\alpha=4$. Thus $R=\\sqrt{1^2+4^2}=\\sqrt{17}$ and $\\tan\\alpha=4$. Since $0\\lt \\alpha\\lt \\pi/2$, $\\alpha=\\arctan4=1.32581766\\ldots$ radians.\n\n\\[\\boxed{R=\\sqrt{17},\\qquad\\alpha=1.326\\text{ radians}}\\]"},{"title":"Part (b)","body":"The model becomes $H=24/[3+\\sqrt{17}\\cos(t/2-\\alpha)]$. For $0\\le t\\le6.5$, the phase lies between $-\\alpha$ and $3.25-\\alpha$; throughout this interval the denominator remains positive. Its maximum $3+\\sqrt{17}$ is attained at $t=2\\alpha=2.651635\\ldots$, inside the time interval. The height is then smallest:\n\n\\[H_{\\min}=\\frac{24}{3+\\sqrt{17}}=3.369316876\\ldots\\ \\mathrm m.\\]\n\nTo the nearest centimetre this is $3.37\\ \\mathrm m$ (337 cm).\n\n\\[\\boxed{H_{\\min}=3.37\\ \\mathrm m}\\]"},{"title":"Part (c)","body":"For $H=10$, $3+\\sqrt{17}\\cos(t/2-\\alpha)=24/10$, so\n\n\\[\\cos(t/2-\\alpha)=-\\frac{3}{5\\sqrt{17}}.\\]\n\nLet $\\gamma=\\arccos[-3/(5\\sqrt{17})]$. In the permitted phase interval $[-\\alpha,3.25-\\alpha]$, only $+\\gamma$ occurs: $-\\gamma\\lt -\\alpha$, and shifts by $2\\pi$ are outside it. Using the unrounded $\\alpha=\\arctan4$,\n\n\\[t=2(\\alpha+\\gamma)=6.085307854\\ldots\\ \\mathrm s.\\]\n\n\\[\\boxed{t=6.09\\ \\mathrm s}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q09","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":9,"marks":8,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q09_M08_07_TrigEquations.png","downloadName":"WMA13-01_Y2021_MayJune_Q09_M08_07_TrigEquations.png","finalAnswer":"(a) $13\\sin(x-0.395)\\quad(R=13,\\ \\alpha=0.395\\text{ rad})$\n(b) $\\min g=-3;\\qquad\\theta_{\\min}=\\frac{5\\pi}{6}+\\frac12\\arctan(5/12)$\n(c) $-159\\le h(\\beta)\\le10$","steps":[{"title":"Part (a)","body":"Expand $R\\sin(x-\\alpha)=R\\cos\\alpha\\sin x-R\\sin\\alpha\\cos x$. Therefore $R\\cos\\alpha=12$, $R\\sin\\alpha=5$. Thus $R=\\sqrt{12^2+5^2}=13$ and $\\alpha=\\arctan(5/12)=0.3947911197\\ldots$ radians, in the required first quadrant.\n\n\\[\\boxed{13\\sin(x-0.395)\\quad(R=13,\\ \\alpha=0.395\\text{ rad})}\\]"},{"title":"Part (b)","body":"Write $g(\\theta)=10+13\\sin(2\\theta-\\pi/6-\\alpha)$. (i) The minimum is $10-13=-3$. (ii) For sine to equal $-1$, $2\\theta-\\pi/6-\\alpha=-\\pi/2+2\\pi n$. Hence $\\theta=-\\pi/6+\\alpha/2+\\pi n$. For $n=0$ this is negative, so the smallest permitted value uses $n=1$:\n\n\\[\\theta=\\frac{5\\pi}{6}+\\frac12\\arctan(5/12)=2.815389438\\ldots\\text{ radians}.\\]\n\nUse the unrounded phase angle for the calculation.\n\n\\[\\boxed{\\min g=-3;\\qquad\\theta_{\\min}=\\frac{5\\pi}{6}+\\frac12\\arctan(5/12)}\\]"},{"title":"Part (c)","body":"As $\\beta$ varies over the reals, $12\\sin\\beta-5\\cos\\beta$ covers $[-13,13]$. Its square therefore covers $[0,169]$, not $[169,169]$. Subtracting from 10 reverses the bounds, giving $[-159,10]$; both endpoints are attained.\n\n\\[\\boxed{-159\\le h(\\beta)\\le10}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q09","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":9,"marks":9,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["06_TrigIdentities","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Differentiation Techniques","Applications of Differentiation"],"topics":["07_TrigEquations","06_TrigIdentities","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Trig Equations & R-Form","Trig Identities & Exact Values","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q09_M09_07_TrigEquations.png","downloadName":"WMA13-01_Y2022_MayJune_Q09_M09_07_TrigEquations.png","finalAnswer":"(a) $2\\sin x+\\cos x=-2$\n(b) $x_M=3.79$","steps":[{"title":"Part (a)","body":"Differentiate by the quotient rule:\n\n\\[y'=\\frac{-2\\sin x(1+\\sin x)-(1+2\\cos x)\\cos x}{(1+\\sin x)^2} =\\frac{-2\\sin x-\\cos x-2(\\sin^2x+\\cos^2x)}{(1+\\sin x)^2} =\\frac{-2\\sin x-\\cos x-2}{(1+\\sin x)^2}.\\]\n\nInside the stated interval, $1+\\sin x\\gt 0$. At the interior minimum M, $y'=0$, so its numerator is zero, giving the required equation.\n\n\\[\\boxed{2\\sin x+\\cos x=-2}\\]"},{"title":"Part (b)","body":"Write $2\\sin x+\\cos x=\\sqrt5\\sin(x+\\beta)$, where $\\cos\\beta=2/\\sqrt5$, $\\sin\\beta=1/\\sqrt5$ and $\\beta=\\arctan(1/2)$. The equation becomes $\\sin(x+\\beta)=-2/\\sqrt5$. Let $\\gamma=\\arcsin(2/\\sqrt5)$, so $\\gamma+\\beta=\\pi/2$. The solutions in the closed boundary range include $x=-\\pi/2$, $3\\pi/2$, and\n\n\\[x=\\pi+\\gamma-\\beta=3.7850937624\\ldots.\\]\n\nBoth boundary values are outside the original open domain (and make its denominator zero). The sole interior stationary point is M; the derivative changes from negative to positive there.\n\n\\[\\boxed{x_M=3.79}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q08","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":8,"marks":9,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q08_M09_07_TrigEquations.png","downloadName":"WMA13-01_Y2022_Oct_Q08_M09_07_TrigEquations.png","finalAnswer":"(a) $R=17,\\qquad\\alpha=1.081\\ \\text{radians}$\n(b) $f_{\\min}=\\frac15,\\qquad x=2.65$\n(c) $y=-\\frac{23}{5}$\n(d) $x=1.33$","steps":[{"title":"Part (a)","body":"Expand $R\\sin(x-\\alpha)=R\\cos\\alpha\\sin x-R\\sin\\alpha\\cos x$. Thus $R\\cos\\alpha=8$, $R\\sin\\alpha=15$, so $R=\\sqrt{64+225}=17$ and $\\alpha=\\arctan(15/8)=1.0808390005\\ldots$ radians, in the required quadrant.\n\n\\[\\boxed{R=17,\\qquad\\alpha=1.081\\ \\text{radians}}\\]"},{"title":"Part (b)","body":"Using the exact phase from (a),\n\n\\[f(x)=\\frac{15}{41+34\\sin(x-\\alpha)}.\\]\n\nThe denominator lies between 7 and 75, so it is always positive. (i) The smallest fraction occurs at its largest denominator: $f_{\\min}=15/75=1/5$. (ii) This occurs when $x-\\alpha=\\pi/2+2n\\pi$. The smallest positive value is $x=\\alpha+\\pi/2=2.6516353273\\ldots$, or 2.65 to three significant figures.\n\n\\[\\boxed{f_{\\min}=\\frac15,\\qquad x=2.65}\\]"},{"title":"Part (c)","body":"The transformation $2f(x)-5$ preserves the locations of minima and maps their y coordinate to $2(1/5)-5=-23/5$.\n\n\\[\\boxed{y=-\\frac{23}{5}}\\]"},{"title":"Part (d)","body":"Reflection in the x-axis changes minima of f into maxima of $-f$. The argument $2x$ halves their x coordinates, so the first positive maximum is at\n\n\\[x=\\frac{\\alpha+\\pi/2}{2}=1.3258176637\\ldots\\approx1.33.\\]\n\n\\[\\boxed{x=1.33}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q09","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":9,"marks":9,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["01_RationalAlgebra","06_TrigIdentities"],"secondaryTopicNames":["Rational Algebra","Trig Identities & Exact Values"],"topics":["07_TrigEquations","01_RationalAlgebra","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Rational Algebra","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q09_M09_07_TrigEquations.png","downloadName":"WMA13-01_Y2022_Oct_Q09_M09_07_TrigEquations.png","finalAnswer":"(a) $\\frac{\\cos^2\\theta}{\\cos2\\theta-\\sin3\\theta}=\\frac{1+\\sin\\theta}{1-2\\sin\\theta-4\\sin^2\\theta}$\n(b) $\\theta=15.6^\\circ,\\ 164.4^\\circ,\\ 235.6^\\circ,\\ 304.4^\\circ$","steps":[{"title":"Part (a)","body":"Write $s=\\sin\\theta$. The compound-angle formula gives\n\n\\[\\sin3\\theta=\\sin(2\\theta+\\theta) =2\\sin\\theta\\cos^2\\theta+(1-2\\sin^2\\theta)\\sin\\theta=3s-4s^3.\\]\n\nHence\n\n\\[\\cos2\\theta-\\sin3\\theta=1-2s^2-3s+4s^3 =(1-s)(1-2s-4s^2),\\quad\\cos^2\\theta=(1-s)(1+s).\\]\n\nThe given nonzero denominator ensures that $1-s\\ne0$ and the other factor is nonzero. Cancel the common factor to obtain the required identity.\n\n\\[\\boxed{\\frac{\\cos^2\\theta}{\\cos2\\theta-\\sin3\\theta}=\\frac{1+\\sin\\theta}{1-2\\sin\\theta-4\\sin^2\\theta}}\\]"},{"title":"Part (b)","body":"Use (a) and $\\csc\\theta=1/\\sin\\theta$. With $s=\\sin\\theta\\ne0$,\n\n\\[\\frac{1+s}{1-2s-4s^2}=\\frac2s \\ \\Longrightarrow\\ s+s^2=2-4s-8s^2 \\ \\Longrightarrow\\ 9s^2+5s-2=0.\\]\n\nThus $s=(-5\\pm\\sqrt{97})/18$, approximately $0.269380989$ and $-0.824936545$. Both lie in $[-1,1]$, are nonzero, and satisfy the original nonzero-denominator condition. The positive value gives $15.6274\\ldots^\\circ$ and $164.3726\\ldots^\\circ$; the negative value gives $235.5821\\ldots^\\circ$ and $304.4179\\ldots^\\circ$. All four angles lie in $0\\lt \\theta\\le360^\\circ$.\n\n\\[\\boxed{\\theta=15.6^\\circ,\\ 164.4^\\circ,\\ 235.6^\\circ,\\ 304.4^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q02","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":2,"marks":6,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q02_M06_07_TrigEquations.png","downloadName":"WMA13-01_Y2023_Jan_Q02_M06_07_TrigEquations.png","finalAnswer":"(a) $R=\\sqrt5,\\qquad\\alpha=1.107\\ \\text{radians}$\n(b) $\\max g=3+7\\sqrt5,\\qquad x=2.12$","steps":[{"title":"Part (a)","body":"Expand $R\\cos(x-\\alpha)=R\\cos\\alpha\\cos x+R\\sin\\alpha\\sin x$. Comparing coefficients gives $R\\cos\\alpha=1$ and $R\\sin\\alpha=2$. Thus $R^2=1^2+2^2=5$ and $\\tan\\alpha=2$. The specified first-quadrant phase is $\\alpha=\\arctan2=1.1071487\\ldots$ radians.\n\n\\[\\boxed{R=\\sqrt5,\\qquad\\alpha=1.107\\ \\text{radians}}\\]"},{"title":"Part (b)","body":"Using the exact phase $\\alpha=\\arctan2$, write $g(x)=3-7\\sqrt5\\cos(2x-\\alpha)$. (i) The negative cosine coefficient means the maximum occurs when the cosine is $-1$; the maximum is $3+7\\sqrt5$. (ii) $2x-\\alpha=\\pi+2n\\pi$, so $x=(\\pi+\\alpha)/2+n\\pi$. The $n=-1$ value is negative; $n=0$ is the smallest positive one, $x=2.1243706857\\ldots$, or 2.12 to two decimal places.\n\n\\[\\boxed{\\max g=3+7\\sqrt5,\\qquad x=2.12}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q05","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":5,"marks":9,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["01_RationalAlgebra","06_TrigIdentities"],"secondaryTopicNames":["Rational Algebra","Trig Identities & Exact Values"],"topics":["07_TrigEquations","01_RationalAlgebra","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Rational Algebra","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q05_M09_07_TrigEquations.png","downloadName":"WMA13-01_Y2023_Jan_Q05_M09_07_TrigEquations.png","finalAnswer":"(a) $\\cot^2x-\\tan^2x=4\\cot2x\\csc2x$\n(b) $\\theta=-0.65,\\quad0.65\\ \\text{radians}$","steps":[{"title":"Part (a)","body":"For $x\\ne n\\pi/2$, both sine and cosine are nonzero. Then\n\n\\[\\cot^2x-\\tan^2x=\\frac{\\cos^4x-\\sin^4x}{\\sin^2x\\cos^2x} =\\frac{(\\cos^2x-\\sin^2x)(\\cos^2x+\\sin^2x)}{\\sin^2x\\cos^2x} =\\frac{\\cos2x}{\\tfrac14\\sin^22x} =4\\frac{\\cos2x}{\\sin2x}\\frac1{\\sin2x} =4\\cot2x\\csc2x.\\]\n\n\\[\\boxed{\\cot^2x-\\tan^2x=4\\cot2x\\csc2x}\\]"},{"title":"Part (b)","body":"By part (a), the equation is $\\cot^2\\theta-\\tan^2\\theta=2\\tan^2\\theta$, so $\\cot^2\\theta=3\\tan^2\\theta$. The original expression excludes $\\theta=0$ in the stated interval, so $\\tan\\theta\\ne0$ and multiplication by $\\tan^2\\theta$ gives\n\n\\[1=3\\tan^4\\theta\\quad\\Longrightarrow\\quad \\tan\\theta=\\pm3^{-1/4}.\\]\n\nTangent is one-to-one on $(-\\pi/2,\\pi/2)$; the two angles are $\\pm\\arctan(3^{-1/4})=\\pm0.6497662865\\ldots$ radians. Both are valid and nonzero. To two decimal places:\n\n\\[\\boxed{\\theta=-0.65,\\quad0.65\\ \\text{radians}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q05","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":5,"marks":7,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["07_TrigEquations","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q05_M07_07_TrigEquations.png","downloadName":"WMA13-01_Y2023_MayJune_Q05_M07_07_TrigEquations.png","finalAnswer":"(i) $x=2,\\quad x=\\frac{5\\pi}{6}$\n(ii) $\\theta=15.0^\\circ,\\quad165^\\circ$","steps":[{"title":"Part (i)","body":"The zero-product rule gives $x-2=0$ or $\\sqrt3\\sec x+2=0$. The first gives $x=2$, which lies in $(0,\\pi)$ and has $\\cos x\\ne0$. The second gives $\\cos x=-\\sqrt3/2$; the only angle in the interval is $5\\pi/6$.\n\n\\[\\boxed{x=2,\\quad x=\\frac{5\\pi}{6}}\\]"},{"title":"Part (ii)","body":"Use $\\cos2\\theta=1-2\\sin^2\\theta$ and set $s=\\sin\\theta$:\n\n\\[10s=3-6s^2\\quad\\Longrightarrow\\quad6s^2+10s-3=0 \\quad\\Longrightarrow\\quad s=\\frac{-5\\pm\\sqrt{43}}6.\\]\n\nThe negative root is less than $-1$, so reject it. The positive root is $0.2595730874\\ldots$. Its principal angle is $15.04473218\\ldots^\\circ$; the other solution is $180^\\circ-15.04473218\\ldots^\\circ$. Both are in the given interval. To three significant figures:\n\n\\[\\boxed{\\theta=15.0^\\circ,\\quad165^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q09","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":9,"marks":8,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["01_RationalAlgebra","06_TrigIdentities"],"secondaryTopicNames":["Rational Algebra","Trig Identities & Exact Values"],"topics":["07_TrigEquations","01_RationalAlgebra","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Rational Algebra","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q09_M08_07_TrigEquations.png","downloadName":"WMA13-01_Y2024_Jan_Q09_M08_07_TrigEquations.png","finalAnswer":"(a) $3\\sin2\\theta-4\\cos2\\theta=2$\n(b) $x=3.81$","steps":[{"title":"Part (a)","body":"The original equation is defined only when $\\cos\\theta+\\sin\\theta\\ne0$ and $\\cos2\\theta\\ne0$. Multiplying by $\\cos\\theta+\\sin\\theta$ gives\n\n\\[3\\sin\\theta\\cos\\theta=(2+\\sec2\\theta)(\\cos^2\\theta-\\sin^2\\theta) =(2+\\sec2\\theta)\\cos2\\theta=2\\cos2\\theta+1.\\]\n\nUsing $2\\sin\\theta\\cos\\theta=\\sin2\\theta$, multiply through by 2: $3\\sin2\\theta=4\\cos2\\theta+2$.\n\n\\[\\boxed{3\\sin2\\theta-4\\cos2\\theta=2}\\]"},{"title":"Part (b)","body":"Write $3\\sin2x-4\\cos2x=5\\sin(2x-\\phi)$, where $\\cos\\phi=3/5$, $\\sin\\phi=4/5$ and $\\phi=\\arctan(4/3)$. Then $\\sin(2x-\\phi)=2/5$. Because $\\pi\\lt x\\lt 3\\pi/2$, $2\\pi-\\phi\\lt 2x-\\phi\\lt 3\\pi-\\phi$, approximately $(5.356,8.497)$. With $\\gamma=\\arcsin(2/5)$, the only angle in this interval is $2\\pi+\\gamma$; $3\\pi-\\gamma\\approx9.013$ is outside it. Thus\n\n\\[x=\\frac{2\\pi+\\arcsin(2/5)+\\arctan(4/3)}2=3.810998686\\ldots.\\]\n\nAt this value $\\cos x+\\sin x\\ne0$ and $\\cos2x\\ne0$; direct substitution satisfies the original equation.\n\n\\[\\boxed{x=3.81}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q01","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":1,"marks":5,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["07_TrigEquations","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q01_M05_07_TrigEquations.png","downloadName":"WMA13-01_Y2024_Oct_Q01_M05_07_TrigEquations.png","finalAnswer":"(main) $\\theta=109.5^\\circ,\\ 250.5^\\circ$","steps":[{"title":"Part (main)","body":"Using $\\tan^2\\theta=\\sec^2\\theta-1$ gives\n\n\\[3\\sec^2\\theta+7\\sec\\theta-6=0 \\quad\\Longrightarrow\\quad(3\\sec\\theta-2)(\\sec\\theta+3)=0.\\]\n\nThe value $\\sec\\theta=2/3$ would give $\\cos\\theta=3/2$, impossible for a real angle. Thus $\\cos\\theta=-1/3$. In $0\\lt \\theta\\le360^\\circ$, the two angles are $\\arccos(-1/3)=109.4712\\ldots^\\circ$ and $360^\\circ-109.4712\\ldots^\\circ$.\n\n\\[\\boxed{\\theta=109.5^\\circ,\\ 250.5^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q08","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":8,"marks":9,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["07_TrigEquations","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q08_M09_07_TrigEquations.png","downloadName":"WMA13-01_Y2025_Jan_Q08_M09_07_TrigEquations.png","finalAnswer":"(i) $\\theta=0.424,\\ 1.15\\text{ radians}$\n(ii) $x=24.7^\\circ,\\ 114.7^\\circ$","steps":[{"title":"Part (i)","body":"Use $\\csc\\theta=1/\\sin\\theta$. Since $0\\lt \\theta\\lt \\pi$, $\\sin\\theta\\ne0$ and\n\n\\[\\frac3{\\sin\\theta}=8\\cos\\theta\\quad\\Longrightarrow\\quad 3=8\\sin\\theta\\cos\\theta=4\\sin2\\theta.\\]\n\nThus $\\sin2\\theta=3/4$. Since $0\\lt 2\\theta\\lt 2\\pi$, the two possibilities are\n\n\\[2\\theta=\\arcsin(3/4)\\quad\\text{or}\\quad2\\theta=\\pi-\\arcsin(3/4).\\]\n\nThey give $\\theta=0.4240310395\\ldots$ and $1.1467652873\\ldots$ radians.\n\n\\[\\boxed{\\theta=0.424,\\ 1.15\\text{ radians}}\\]"},{"title":"Part (ii)","body":"Apply the tangent subtraction identity:\n\n\\[\\frac{\\tan2x-\\tan70^\\circ}{1+\\tan2x\\tan70^\\circ} =\\tan(2x-70^\\circ)=-\\frac38.\\]\n\nSet $u=2x-70^\\circ$. The interval becomes $-70^\\circ\\lt u\\lt 290^\\circ$. With $\\arctan(-3/8)=-20.5560452196\\ldots^\\circ$, the permitted values are $u=-20.5560452196\\ldots^\\circ$ and $159.4439547804\\ldots^\\circ$. Adding $70^\\circ$ and halving gives $x=24.7219773902\\ldots^\\circ$ and $114.7219773902\\ldots^\\circ$. Both keep the original tangents and denominator defined.\n\n\\[\\boxed{x=24.7^\\circ,\\ 114.7^\\circ}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q02","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":2,"marks":7,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["02_Functions","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Functions, Composition & Inverses","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","02_Functions","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Functions, Composition & Inverses","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q02_M07_07_TrigEquations.png","downloadName":"WMA13-01_Y2025_MayJune_Q02_M07_07_TrigEquations.png","finalAnswer":"(a) $25$, $1.287\\text{ radians}$\n(i) $g_{\\min}=\\frac5{165}=\\frac1{33}$\n(ii) $0.927$\n(b)(i) $g_{\\min}=\\frac5{165}=\\frac1{33}$\n(b)(ii) $\\boxed{0.927}$","steps":[{"title":"Part (a)","body":"Expand $R\\cos(x+\\alpha)=R\\cos\\alpha\\cos x-R\\sin\\alpha\\sin x$. Comparing coefficients gives\n\n\\[R\\cos\\alpha=7,\\qquad R\\sin\\alpha=24.\\]\n\nHence\n\n\\[R=\\sqrt{7^2+24^2}=\\boxed{25},\\qquad \\alpha=\\arctan\\frac{24}{7}=1.287002\\ldots=\\boxed{1.287\\text{ radians}}.\\]\n\nThus $f(x)=25\\cos(x+\\alpha)$, using the unrounded $\\alpha$ in subsequent calculations."},{"title":"Part (i)","body":"Since $-25\\leq f(2x)\\leq25$, the positive denominator $90-3f(2x)$ lies between $15$ and $165$. The smallest reciprocal occurs at the largest denominator:\n\n\\[\\boxed{g_{\\min}=\\frac5{165}=\\frac1{33}}.\\]"},{"title":"Part (ii)","body":"The minimum requires $f(2x)=-25$, so\n\n\\[\\cos(2x+\\alpha)=-1,\\qquad 2x+\\alpha=\\pi+2n\\pi.\\]\n\nSince $0\\lt \\alpha\\lt \\pi/2$, the first positive solution uses $n=0$:\n\n\\[x=\\frac{\\pi-\\arctan(24/7)}2=0.927295\\ldots=\\boxed{0.927}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q04","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":4,"marks":6,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["02_Functions","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Functions, Composition & Inverses","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","02_Functions","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Functions, Composition & Inverses","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q04_M06_07_TrigEquations.png","downloadName":"WMA13-01_Y2025_Oct_Q04_M06_07_TrigEquations.png","finalAnswer":"(a) $2*sqrt(3)*sin(2*x-pi/3)$\n(b)(i) $sqrt(3)$\n(b)(ii) $5*pi/36$","steps":[{"title":"Part (a)","body":"Expand $R\\sin(2x-\\alpha)=R\\cos\\alpha\\sin2x-R\\sin\\alpha\\cos2x$. Comparison gives $R\\cos\\alpha=\\sqrt3$ and $R\\sin\\alpha=3$. Thus $R=\\sqrt{3+9}=2\\sqrt3$ and $\\tan\\alpha=\\sqrt3$. As $0\\lt \\alpha\\lt \\pi/2$, $\\alpha=\\pi/3$ and\n\n\\[f(x)=2\\sqrt3\\sin(2x-\\pi/3).\\]"},{"title":"Part (b)(i)","body":"\\[g(x)=\\frac{18}{2\\sqrt3\\sin(6x-\\pi/3)+4\\sqrt3}.\\]\n\nThe denominator is always positive, between $2\\sqrt3$ and $6\\sqrt3$. The fraction is smallest when the denominator is largest:\n\n\\[\\min g=\\frac{18}{6\\sqrt3}=\\sqrt3.\\]"},{"title":"Part (b)(ii)","body":"The maximum denominator occurs when $\\sin(6x-\\pi/3)=1$:\n\n\\[6x-\\frac{\\pi}{3}=\\frac{\\pi}{2}+2\\pi n \\Longrightarrow x=\\frac{5\\pi}{36}+\\frac{\\pi n}{3}.\\]\n\nThe smallest positive value is $x=5\\pi/36$, since $n=-1$ gives a negative value."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q09","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":9,"marks":9,"topic":"07_TrigEquations","topicName":"Trig Equations & R-Form","primaryTopic":"07_TrigEquations","primaryTopicName":"Trig Equations & R-Form","secondaryTopics":["03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"secondaryTopicNames":["Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"topics":["07_TrigEquations","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities"],"topicNames":["Trig Equations & R-Form","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q09_M09_07_TrigEquations.png","downloadName":"WMA13-01_Y2026_Jan_Q09_M09_07_TrigEquations.png","finalAnswer":"(a) $P=5,\\ R=\\frac{3\\sqrt5}{2},\\ \\alpha=\\arctan2$\n(b) $\\left[5-\\frac{3\\sqrt5}{2},\\ 5+\\frac{3\\sqrt5}{2}\\right]$\n(c) $x_M=4.94$","steps":[{"title":"Part (a)","body":"Use $2\\sin x\\cos x=\\sin2x$ and $2\\sin^2x=1-\\cos2x$:\n\n\\[h(x)=8+3\\sin x\\cos x-6\\sin^2x =5+\\frac32\\sin2x+3\\cos2x.\\]\n\nExpanding $R\\sin(2x+\\alpha)$ and comparing coefficients gives\n\n\\[R\\cos\\alpha=\\frac32,\\qquad R\\sin\\alpha=3.\\]\n\nTherefore\n\n\\[P=5,\\qquad R=\\sqrt{\\frac94+9}=\\frac{3\\sqrt5}{2}, \\qquad\\alpha=\\arctan(2)=1.107\\ \\text{radians (3 d.p.)}.\\]\n\nThus $h(x)=5+\\frac{3\\sqrt5}{2}\\sin(2x+\\alpha)$ with the exact angle $\\alpha=\\arctan(2)$."},{"title":"Part (b)","body":"The given interval includes two complete periods. The range is\n\n\\[\\left[5-\\frac{3\\sqrt5}{2},\\ 5+\\frac{3\\sqrt5}{2}\\right].\\]"},{"title":"Part (c)","body":"At a minimum, $\\sin(2x+\\alpha)=-1$, so\n\n\\[2x+\\alpha=\\frac{3\\pi}{2}+2\\pi n, \\qquad x=\\frac{3\\pi}{4}-\\frac\\alpha2+\\pi n.\\]\n\nOn $0\\le x\\le2\\pi$, $n=0$ and $n=1$ give the two minima. The larger coordinate is\n\n\\[x_M=\\frac{7\\pi}{4}-\\frac12\\arctan(2)=4.944212785\\ldots.\\]\n\n\\[x_M=4.94\\quad\\text{(3 significant figures)}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q09","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":9,"marks":9,"topic":"08_ExponentialsLogs","topicName":"Exponentials & Logarithms","primaryTopic":"08_ExponentialsLogs","primaryTopicName":"Exponentials & Logarithms","secondaryTopics":["02_Functions","03_GraphTransformations","04_Modulus"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations","Modulus"],"topics":["08_ExponentialsLogs","02_Functions","03_GraphTransformations","04_Modulus"],"topicNames":["Exponentials & Logarithms","Functions, Composition & Inverses","Graph Transformations","Modulus"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q09_M09_08_ExponentialsLogs.png","downloadName":"WMA13-01_Y2023_Oct_Q09_M09_08_ExponentialsLogs.png","finalAnswer":"(a) $k=-1$\n(b) $y_A=2,\\qquad x_B=e^{1/2}-1$\n(c) $-1\\lt x\\lt e^{-1/4}-1\\quad\\text{or}\\quad x\\gt e^{5/4}-1$","steps":[{"title":"Part (a)","body":"The logarithm requires $x+1\\gt 0$, so the domain is $x\\gt -1$. As $x\\to-1^+$, $\\ln(x+1)\\to-\\infty$ and the ordinate tends to infinity.\n\n\\[\\boxed{k=-1}\\]"},{"title":"Part (b)","body":"(i) At the $y$-axis, $x=0$, giving $y=|2-4\\ln1|=2$.\n\n(ii) At the $x$-axis, $|2-4\\ln(x+1)|=0$, so\n\n\\[\\ln(x+1)=\\frac12\\quad\\Longrightarrow\\quad x=e^{1/2}-1.\\]\n\nThus $A=(0,2)$ and $B=(e^{1/2}-1,0)$.\n\n\\[\\boxed{y_A=2,\\qquad x_B=e^{1/2}-1}\\]"},{"title":"Part (c)","body":"On $x\\gt -1$, split the absolute-value inequality into two alternatives:\n\n\\[2-4\\ln(x+1)\\gt 3\\quad\\text{or}\\quad 2-4\\ln(x+1)\\lt -3.\\]\n\nDividing by $-4$ reverses the inequality in each branch:\n\n\\[\\ln(x+1)\\lt -\\frac14\\quad\\text{or}\\quad \\ln(x+1)\\gt \\frac54.\\]\n\nSince the exponential is increasing, this becomes $x+1\\lt e^{-1/4}$ or $x+1\\gt e^{5/4}$. Intersect with the logarithmic domain; neither boundary is included because the source inequality is strict.\n\n\\[\\boxed{-1\\lt x\\lt e^{-1/4}-1\\quad\\text{or}\\quad x\\gt e^{5/4}-1}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q01","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":1,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["09_LogGraphsModels","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q01_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2020_Jan_Q01_M06_09_LogGraphsModels.png","finalAnswer":"(a) $300$\n(b) $t=16.22\\text{ years}$\n(c) $N \\lt  450 \\lt  500, so the population can never reach 500$","steps":[{"title":"Part (a)","body":"At the start of the study, $t=0$, so\n\n\\[N(0)=\\frac{900e^0}{2e^0+1}=\\frac{900}{3}=\\boxed{300}.\\]\n\nThere are initially $300$ toads."},{"title":"Part (b)","body":"Set $N=420$ and clear the denominator:\n\n\\[\\begin{aligned} 420&=\\frac{900e^{0.12t}}{2e^{0.12t}+1},\\\\ 420(2e^{0.12t}+1)&=900e^{0.12t},\\\\ 420&=60e^{0.12t},\\\\ e^{0.12t}&=7. \\end{aligned}\\]\n\nTaking natural logarithms gives\n\n\\[0.12t=\\ln 7 \\quad\\Longrightarrow\\quad t=\\frac{\\ln 7}{0.12}=16.2159179\\ldots.\\]\n\nThus $\\boxed{t=16.22\\text{ years}}$ to 2 decimal places."},{"title":"Part (c)","body":"Divide the numerator and denominator by $e^{0.12t}$:\n\n\\[N=\\frac{900}{2+e^{-0.12t}}.\\]\n\nSince $e^{-0.12t}\\gt 0$ for every finite $t\\geq0$, the denominator is greater than $2$. Hence\n\n\\[N\\lt \\frac{900}{2}=450\\lt 500.\\]\n\nThe population approaches $450$ as $t$ increases without bound, so it can never reach $500$ according to this model."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q03","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":3,"marks":5,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q03_M05_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2020_Jan_Q03_M05_09_LogGraphsModels.png","finalAnswer":"(a) $\\log_{10}y=4-\\frac{2}{3}\\log_{10}x$\n(b) $y=10000x^{-2/3}$, $p=10000,\\quad q=-\\frac{2}{3}$","steps":[{"title":"Part (a)","body":"The horizontal coordinate is $\\log_{10}x$ and the vertical coordinate is $\\log_{10}y$. The gradient of the line is\n\n\\[m=\\frac{0-4}{6-0}=-\\frac{2}{3}.\\]\n\nThe vertical intercept is $4$, so the required equation is\n\n\\[\\boxed{\\log_{10}y=4-\\frac{2}{3}\\log_{10}x}.\\]"},{"title":"Part (b)","body":"Taking powers of $10$ on both sides gives\n\n\\[\\begin{aligned} y&=10^{4-\\frac{2}{3}\\log_{10}x}\\\\ &=10^4\\left(10^{\\log_{10}x}\\right)^{-2/3}\\\\ &=10000x^{-2/3}. \\end{aligned}\\]\n\nHere $x\\gt 0$, as required for $\\log_{10}x$ to exist. Therefore\n\n\\[\\boxed{y=10000x^{-2/3}},\\qquad \\boxed{p=10000,\\quad q=-\\frac{2}{3}}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q02","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":2,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q02_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2020_Oct_Q02_M06_09_LogGraphsModels.png","finalAnswer":"(a) $a=30,\\qquad b=1.16$\n(b) $2.6\\times10^3\\ \\mathrm{mm}^2$","steps":[{"title":"Part (a)","body":"Exponentiate in base ten and use index laws:\n\n\\[N=10^{0.0646t+1.478}=10^{1.478}\\left(10^{0.0646}\\right)^t=ab^t.\\]\n\nTherefore $a=10^{1.478}=30.060763\\ldots$, which rounds to 30 to the nearest integer, and $b=10^{0.0646}=1.16037937\\ldots$, which rounds to 1.16 to three significant figures.\n\n\\[\\boxed{a=30,\\qquad b=1.16}\\]"},{"title":"Part (b)","body":"At $t=30$, use the original model to retain precision:\n\n\\[N=10^{0.0646(30)+1.478}=10^{3.416}=2606.15355\\ldots\\ \\mathrm{mm}^2.\\]\n\nTo two significant figures the covered area is $2.6\\times10^3\\ \\mathrm{mm}^2$. Using the rounded model $30(1.16)^{30}$ gives the same two-significant-figure answer.\n\n\\[\\boxed{2.6\\times10^3\\ \\mathrm{mm}^2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q05","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":5,"marks":11,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["03_GraphTransformations","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Graph Transformations","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","03_GraphTransformations","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Graph Transformations","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q05_M11_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2021_Jan_Q05_M11_09_LogGraphsModels.png","finalAnswer":"(a) $A=198$\n(b) $k=\\frac15\\ln\\frac53;\\quad p=\\frac15,\\ q=\\frac53$\n(c) $126^\\circ\\mathrm C$\n(d) $7.33^\\circ\\mathrm C\\,\\mathrm{min}^{-1}$","steps":[{"title":"Part (a)","body":"At $t=0$, $18=A-180e^0=A-180$. Hence $A=198$.\n\n\\[\\boxed{A=198}\\]"},{"title":"Part (b)","body":"At $t=5$, $90=198-180e^{-5k}$, so $180e^{-5k}=108$ and $e^{-5k}=3/5$. Taking logarithms gives $-5k=\\ln(3/5)$, hence $k=(1/5)\\ln(5/3)$. Thus one suitable rational pair is $p=1/5$, $q=5/3$.\n\n\\[\\boxed{k=\\frac15\\ln\\frac53;\\quad p=\\frac15,\\ q=\\frac53}\\]"},{"title":"Part (c)","body":"Use the unrounded k:\n\n\\[\\theta(9)=198-180e^{-(9/5)\\ln(5/3)}=126.22970096\\ldots{}^\\circ\\mathrm C.\\]\n\nRound the temperature to three significant figures.\n\n\\[\\boxed{126^\\circ\\mathrm C}\\]"},{"title":"Part (d)","body":"Differentiate with respect to time: $d\\theta/dt=180ke^{-kt}$. At $t=9$ this is $180[\\ln(5/3)/5]e^{-(9/5)\\ln(5/3)}=7.332421555\\ldots$. The sign is positive because the oven is warming.\n\n\\[\\boxed{7.33^\\circ\\mathrm C\\,\\mathrm{min}^{-1}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q08","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":8,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q08_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2021_Jan_Q08_M07_09_LogGraphsModels.png","finalAnswer":"(a) $a=4.79,\\qquad b=1.23$\n(b) $\\text{Initial percentage with internet access at the start of 2005}$\n(c) $38.0\\%$","steps":[{"title":"Part (a)","body":"Taking logarithms gives $\\log_{10}P=\\log_{10}a+t\\log_{10}b$. Match the intercept and gradient: $\\log_{10}a=0.68$, $\\log_{10}b=0.09$. Thus $a=10^{0.68}=4.786300923\\ldots$ and $b=10^{0.09}=1.230268771\\ldots$.\n\n\\[\\boxed{a=4.79,\\qquad b=1.23}\\]"},{"title":"Part (b)","body":"At $t=0$, $P=a$. Thus a is the percentage of the country's population with internet access at the start of 2005, approximately $4.79\\%$.\n\n\\[\\boxed{\\text{Initial percentage with internet access at the start of 2005}}\\]"},{"title":"Part (c)","body":"The start of 2015 is $t=10$ years after the start of 2005. Using the model parameters, $P=4.79(1.23)^{10}=37.9652818\\ldots\\%$, giving $38.0\\%$ to three significant figures. Using unrounded parameters gives $10^{0.68+0.09(10)}=38.0189396\\ldots\\%$, the same rounded answer.\n\n\\[\\boxed{38.0\\%}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q05","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":5,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q05_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2021_MayJune_Q05_M07_09_LogGraphsModels.png","finalAnswer":"(a) $p=2.089,\\qquad q=1.072$\n(b) $0.22\\ \\mathrm{m^2/day}$","steps":[{"title":"Part (a)","body":"Taking base-ten logarithms gives $\\log_{10}A=\\log_{10}p+t\\log_{10}q$. The intercept is 0.32 and the gradient is $(0.56-0.32)/8=0.03$. Thus $p=10^{0.32}=2.08929613\\ldots$ and $q=10^{0.03}=1.071519305\\ldots$.\n\n\\[\\boxed{p=2.089,\\qquad q=1.072}\\]"},{"title":"Part (b)","body":"Using the parameter values requested in (a), $A=2.089(1.072)^t$. For an arbitrary positive base, $d(q^t)/dt=q^t\\ln q$, so\n\n\\[A'(6)=2.089(1.072)^6\\ln(1.072)=0.2204219233\\ldots.\\]\n\nThis is a positive area increase per day. Retaining unrounded parameters also gives 0.22 to two decimal places.\n\n\\[\\boxed{0.22\\ \\mathrm{m^2/day}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q08","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":8,"marks":13,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q08_M13_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2021_MayJune_Q08_M13_09_LogGraphsModels.png","finalAnswer":"(a) $200\\text{ fish}$\n(b) $600\\text{ fish}$\n(c) $7\\text{ years }8\\text{ months}$\n(d) $A=360$\n(e) $T=12.4\\text{ years}$","steps":[{"title":"Part (a)","body":"At the start, $t=0$ and $e^{0.3t}=1$. Thus $N(0)=600/(2+1)=200$.\n\n\\[\\boxed{200\\text{ fish}}\\]"},{"title":"Part (b)","body":"Divide numerator and denominator by $e^{0.3t}$ to write $N=600/(1+2e^{-0.3t})$. As $t\\to\\infty$, the denominator tends to 1, so the upper limit is 600 fish.\n\n\\[\\boxed{600\\text{ fish}}\\]"},{"title":"Part (c)","body":"Set $N=500$ and multiply through: $1000+500e^{0.3t}=600e^{0.3t}$, so $e^{0.3t}=10$. Hence $t=\\ln10/0.3=7.675283643\\ldots$ years. The fractional year is $12(0.675283643\\ldots)=8.10340372\\ldots$ months. Round only the months to the nearest whole month.\n\n\\[\\boxed{7\\text{ years }8\\text{ months}}\\]"},{"title":"Part (d)","body":"The quotient rule gives\n\n\\[\\frac{dN}{dt}=\\frac{180e^{0.3t}(2+e^{0.3t})-600e^{0.3t}(0.3e^{0.3t})}{(2+e^{0.3t})^2} =\\frac{360e^{0.3t}}{(2+e^{0.3t})^2}.\\]\n\nThe two $e^{0.6t}$ terms cancel exactly.\n\n\\[\\boxed{A=360}\\]"},{"title":"Part (e)","body":"Let $z=e^{0.3T}$. Since $T\\ge0$, require $z\\ge1$. Then $360z/(2+z)^2=8$ gives $45z=(2+z)^2$, hence\n\n\\[z^2-41z+4=0,\\qquad z=\\frac{41\\pm\\sqrt{1665}}2.\\]\n\nThe smaller root lies between 0 and 1 and would give $T\\lt 0$, so reject it. For the larger root,\n\n\\[T=\\frac1{0.3}\\ln\\!\\left(\\frac{41+\\sqrt{1665}}2\\right)=12.37061331\\ldots.\\]\n\n\\[\\boxed{T=12.4\\text{ years}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q03","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":3,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["03_GraphTransformations","08_ExponentialsLogs"],"secondaryTopicNames":["Graph Transformations","Exponentials & Logarithms"],"topics":["09_LogGraphsModels","03_GraphTransformations","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Graph Transformations","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q03_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2021_Oct_Q03_M06_09_LogGraphsModels.png","finalAnswer":"(a) $k=14.2\\text{ years (3 s.f.)};\\quad\\text{March 1814}$\n(b) $37.5\\ \\text{tonnes}$\n(c) $40\\ \\text{tonnes}$","steps":[{"title":"Part (a)","body":"(i) Extraction starts at $G=0$: $30e^{1-0.05k}=40$, so $1-0.05k=\\ln(4/3)$ and $k=20(1-\\ln(4/3))=14.24635855\\ldots$ years. (ii) This is 14 years and $12(0.24635855\\ldots)=2.95630261\\ldots$ months after 1 January 1800. Two full months have elapsed from January 1814, so the date is in March 1814. Use the unrounded fractional year to identify the month.\n\n\\[\\boxed{k=14.2\\text{ years (3 s.f.)};\\quad\\text{March 1814}}\\]"},{"title":"Part (b)","body":"On 1 January 1870, $t=70$. Substitute: $G(70)=40-30e^{1-0.05(70)}=40-30e^{-2.5}=37.53745004\\ldots$ tonnes.\n\n\\[\\boxed{37.5\\ \\text{tonnes}}\\]"},{"title":"Part (c)","body":"As $t\\to\\infty$, $e^{1-0.05t}\\to0$, so $G\\to40$ tonnes.\n\n\\[\\boxed{40\\ \\text{tonnes}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q07","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":7,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q07_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2021_Oct_Q07_M06_09_LogGraphsModels.png","finalAnswer":"(a) $M=7.5\\times10^3\\ \\mathrm{kg}$\n(b) $p=4.83,\\qquad q=1.93$\n(c) $\\text{Predicted mass (kg) when base radius is }1\\ \\mathrm{cm}$","steps":[{"title":"Part (a)","body":"At $r=45$, $\\log_{10}M=1.93\\log_{10}45+0.684$. Exponentiate to obtain $M=10^{0.684}45^{1.93}=7493.766412\\ldots$ kg.\n\n\\[\\boxed{M=7.5\\times10^3\\ \\mathrm{kg}}\\]"},{"title":"Part (b)","body":"Exponentiate the full equation:\n\n\\[M=10^{1.93\\log_{10}r+0.684}=10^{0.684}r^{1.93}.\\]\n\nTherefore $p=10^{0.684}=4.83058802\\ldots$ and $q=1.93$.\n\n\\[\\boxed{p=4.83,\\qquad q=1.93}\\]"},{"title":"Part (c)","body":"If the base radius is $r=1$ cm, the model gives $M=p\\cdot1^q=p$ kg. Thus p is the predicted mass in kilograms of a tree of base radius 1 cm.\n\n\\[\\boxed{\\text{Predicted mass (kg) when base radius is }1\\ \\mathrm{cm}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q04","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":4,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["09_LogGraphsModels","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q04_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2022_Jan_Q04_M07_09_LogGraphsModels.png","finalAnswer":"(a) $p=2.4$\n(b) $T=6.8\\ \\text{days}$\n(c) $80\\ \\mathrm{m^2}$","steps":[{"title":"Part (a)","body":"At $t=0$, the model gives $30=80p/(p+4)$. Thus $30p+120=80p$, so $50p=120$ and $p=2.4\\gt 0$.\n\n\\[\\boxed{p=2.4}\\]"},{"title":"Part (b)","body":"Put $E=e^{0.15T}$ and use $p=2.4$. At area $50\\,\\mathrm{m^2}$,\n\n\\[50=\\frac{192E}{2.4E+4}\\quad\\Longrightarrow\\quad 120E+200=192E\\quad\\Longrightarrow\\quad E=\\frac{25}{9}.\\]\n\nTaking natural logarithms gives $0.15T=\\ln(25/9)$, so $T=\\ln(25/9)/0.15=6.8110083\\ldots$ days.\n\n\\[\\boxed{T=6.8\\ \\text{days}}\\]"},{"title":"Part (c)","body":"Divide numerator and denominator by $pe^{0.15t}$: $A=80/(1+(4/p)e^{-0.15t})\\longrightarrow80$ as $t\\longrightarrow\\infty$. Thus the model's limiting pond surface area is $80\\,\\mathrm{m^2}$; the finite-time covered area approaches this value from below.\n\n\\[\\boxed{80\\ \\mathrm{m^2}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q08","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":8,"marks":8,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q08_M08_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2022_Jan_Q08_M08_09_LogGraphsModels.png","finalAnswer":"(a) $p=550,\\qquad q=1.2$\n(b) $p\\text{ represents the initial amount, approximately }550\\ \\mathrm{mg}$\n(c) $\\left.\\frac{dx}{dt}\\right|_{t=5}=-25\\ \\mathrm{mg\\,h^{-1}}$","steps":[{"title":"Part (a)","body":"Exponentiate base 10:\n\n\\[x=10^{2.74-0.079t}=10^{2.74}(10^{0.079})^{-t}.\\]\n\nThus $p=10^{2.74}=549.5408739\\ldots$ and $q=10^{0.079}=1.199499303\\ldots$. Round p to the nearest integer and q to two significant figures.\n\n\\[\\boxed{p=550,\\qquad q=1.2}\\]"},{"title":"Part (b)","body":"At $t=0$, $x=pq^0=p$. Thus p is the initial amount of antibiotic in the patient's bloodstream, approximately 550 milligrams immediately after the dose in this model.\n\n\\[\\boxed{p\\text{ represents the initial amount, approximately }550\\ \\mathrm{mg}}\\]"},{"title":"Part (c)","body":"For the second patient, write $x=400e^{-t\\ln1.4}$. Differentiate to obtain $dx/dt=-400\\ln(1.4)\\,1.4^{-t}$. At $t=5$, the derivative is $-25.02470969\\ldots\\,\\mathrm{mg\\,h^{-1}}$. The negative sign indicates the amount is decreasing.\n\n\\[\\boxed{\\left.\\frac{dx}{dt}\\right|_{t=5}=-25\\ \\mathrm{mg\\,h^{-1}}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q04","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":4,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q04_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2022_MayJune_Q04_M07_09_LogGraphsModels.png","finalAnswer":"(a) $\\log_{10}N=0.154t+3.08$\n(b) $a=1.20\\times10^3,\\qquad b=1.43$\n(c) $T=17.0\\ \\text{years}$","steps":[{"title":"Part (a)","body":"The slope is $(3.85-3.08)/(5-0)=0.154$ and the vertical intercept is 3.08. The plotted vertical coordinate is $\\log_{10}N$, not N.\n\n\\[\\boxed{\\log_{10}N=0.154t+3.08}\\]"},{"title":"Part (b)","body":"Taking logs of $N=ab^t$ gives $\\log_{10}N=\\log_{10}a+t\\log_{10}b$. Compare with (a): $\\log_{10}a=3.08$ and $\\log_{10}b=0.154$. Thus $a=10^{3.08}=1202.2644\\ldots$ and $b=10^{0.154}=1.4256076\\ldots$. To three significant figures:\n\n\\[\\boxed{a=1.20\\times10^3,\\qquad b=1.43}\\]"},{"title":"Part (c)","body":"Use the unrounded logarithmic model to avoid rounding drift:\n\n\\[\\log_{10}(500000)=0.154T+3.08 \\quad\\Longrightarrow\\quad T=\\frac{\\log_{10}(500000)-3.08}{0.154} =17.0062987\\ldots.\\]\n\n\\[\\boxed{T=17.0\\ \\text{years}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q05","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":5,"marks":11,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","13_NumericalMethods"],"secondaryTopicNames":["Exponentials & Logarithms","Numerical Methods"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","13_NumericalMethods"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Numerical Methods"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q05_M11_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2022_Oct_Q05_M11_09_LogGraphsModels.png","finalAnswer":"(a) $\\text{Loss}\\approx\\pounds830000$\n(b) $t\\in(6,7)\\subset[6,7]$\n(c) $t=\\frac14+\\frac{15}{8}\\ln\\frac{(2t+1)^2}{t+1}$\n(d) $t_2=6.220,\\qquad t_6=6.314$\n(e) $76\\ \\text{months}$","steps":[{"title":"Part (a)","body":"At one year,\n\n\\[P(1)=\\frac3{10}+\\frac34\\ln\\left(\\frac29\\right) =-0.8280580476\\ldots\\quad\\text{million pounds}.\\]\n\nThe negative sign indicates a loss. Its magnitude is about $828058$ pounds, which is approximately $830000$ pounds.\n\n\\[\\boxed{\\text{Loss}\\approx\\pounds830000}\\]"},{"title":"Part (b)","body":"The model is continuous for $t\\ge0$. Evaluate\n\n\\[P(6)=\\frac{23}{10}+\\frac34\\ln\\frac7{169}=-0.0879914\\ldots\\lt 0, \\qquad P(7)=\\frac{27}{10}+\\frac34\\ln\\frac8{225}=0.1975059\\ldots\\gt 0.\\]\n\nContinuity and the sign change give a zero between 6 and 7.\n\n\\[\\boxed{t\\in(6,7)\\subset[6,7]}\\]"},{"title":"Part (c)","body":"Set $P=0$ and move the logarithm to the other side:\n\n\\[\\frac{4t-1}{10}=-\\frac34\\ln\\frac{t+1}{(2t+1)^2} =\\frac34\\ln\\frac{(2t+1)^2}{t+1}.\\]\n\nMultiply by 10 and divide by 4 to obtain the required form.\n\n\\[\\boxed{t=\\frac14+\\frac{15}{8}\\ln\\frac{(2t+1)^2}{t+1}}\\]"},{"title":"Part (d)","body":"Starting with $t_1=6$, retain full calculator precision at each substitution:\n\n\\[t_2=6.2199785610\\ldots,\\quad t_3=6.2867730738\\ldots,\\quad t_4=6.3065963643\\ldots,\\quad t_5=6.3124397510\\ldots,\\quad t_6=6.3141587873\\ldots.\\]\n\nTherefore the requested values to three decimal places are as follows.\n\n\\[\\boxed{t_2=6.220,\\qquad t_6=6.314}\\]"},{"title":"Part (e)","body":"The break-even time is approximately $6.315$ years, or $6.315\\times12=75.78$ months. Profit starts just after that time; the first complete number of months is therefore 76, not 75. Indeed $P(75/12)\\lt 0$ and $P(76/12)\\gt 0$.\n\n\\[\\boxed{76\\ \\text{months}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q03","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":3,"marks":5,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q03_M05_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2023_Jan_Q03_M05_09_LogGraphsModels.png","finalAnswer":"(a) $\\log_{10}y=\\frac5{16}x+\\frac32$\n(b) $k=31.6,\\qquad b=2.05\\quad\\bigl(y\\approx31.6(2.05)^x\\bigr)$","steps":[{"title":"Part (a)","body":"The gradient in the $(x,\\log_{10}y)$ coordinates is $(1.5-0)/(0-(-4.8))=1.5/4.8=5/16$. The vertical intercept is $1.5=3/2$, giving the equation below.\n\n\\[\\boxed{\\log_{10}y=\\frac5{16}x+\\frac32}\\]"},{"title":"Part (b)","body":"Exponentiating base 10 gives\n\n\\[y=10^{(5/16)x+3/2}=10^{3/2}(10^{5/16})^x.\\]\n\nTherefore $k=10^{3/2}=31.62277660\\ldots$ and $b=10^{5/16}=2.053525026\\ldots$. To three significant figures the model constants are 31.6 and 2.05.\n\n\\[\\boxed{k=31.6,\\qquad b=2.05\\quad\\bigl(y\\approx31.6(2.05)^x\\bigr)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q10","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":10,"marks":9,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q10_M09_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2023_Jan_Q10_M09_09_LogGraphsModels.png","finalAnswer":"(a) $F(0)=35$\n(b) $k=\\frac{\\ln12}{15}$\n(c) $T=5.7\\ \\text{days},\\qquad T=20.8\\ \\text{days}$","steps":[{"title":"Part (a)","body":"At the start $t=0$, so $e^{kt}=1$ and the model gives $F(0)=350/(9+1)=35$ fruit flies.\n\n\\[\\boxed{F(0)=35}\\]"},{"title":"Part (b)","body":"Using $F(15)=200$,\n\n\\[200=\\frac{350e^{15k}}{9+e^{15k}} \\quad\\Longrightarrow\\quad1800+200e^{15k}=350e^{15k} \\quad\\Longrightarrow\\quad e^{15k}=12.\\]\n\nTake natural logs to obtain $15k=\\ln12$, as required.\n\n\\[\\boxed{k=\\frac{\\ln12}{15}}\\]"},{"title":"Part (c)","body":"By the quotient rule,\n\n\\[F'(t)=\\frac{350ke^{kt}(9+e^{kt})-350ke^{2kt}}{(9+e^{kt})^2} =\\frac{3150ke^{kt}}{(9+e^{kt})^2}.\\]\n\nSet $F'(T)=10$ and let $u=e^{kT}\\gt 0$. Then\n\n\\[315ku=(9+u)^2\\quad\\Longrightarrow\\quad u^2+(18-315k)u+81=0.\\]\n\nWith the exact $k=\\ln12/15$, the quadratic formula gives\n\n\\[u=\\frac{315k-18\\pm\\sqrt{(315k-18)^2-324}}2 =2.5615490777\\ldots\\ \\text{or}\\ 31.6214905678\\ldots.\\]\n\nBoth values are positive and at least 1, hence both correspond to $T\\ge0$. Finally $T=\\ln u/k$ gives $5.6779528361\\ldots$ or $20.8488936858\\ldots$ days. To one decimal place the two times are as follows.\n\n\\[\\boxed{T=5.7\\ \\text{days},\\qquad T=20.8\\ \\text{days}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q02","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":2,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q02_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2023_MayJune_Q02_M06_09_LogGraphsModels.png","finalAnswer":"(a) $\\log_6T=4-2\\log_6x,\\qquad T=\\frac1{36}$\n(b) $T=\\frac{1296}{x^2},\\qquad x\\gt 0$","steps":[{"title":"Part (a)","body":"(i) Write $Y=\\log_6T$, $X=\\log_6x$. The gradient is $(0-4)/(2-0)=-2$ and the intercept is 4, so $Y=4-2X$. (ii) Since $216=6^3$, $\\log_6T=4-2(3)=-2$, hence $T=6^{-2}=1/36$.\n\n\\[\\boxed{\\log_6T=4-2\\log_6x,\\qquad T=\\frac1{36}}\\]"},{"title":"Part (b)","body":"The log equation gives $\\log_6T+2\\log_6x=4$. For $x,T\\gt 0$, combine logs to obtain $\\log_6(Tx^2)=4$. Thus $Tx^2=6^4=1296$, or $T=1296/x^2$.\n\n\\[\\boxed{T=\\frac{1296}{x^2},\\qquad x\\gt 0}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q07","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":7,"marks":8,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q07_M08_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2023_MayJune_Q07_M08_09_LogGraphsModels.png","finalAnswer":"(a) $A=2500,\\qquad k=0.1733$\n(b) $1.79\\times10^3\\ \\text{bacteria per hour}$\n(c) $T=4.11\\ \\text{hours}$","steps":[{"title":"Part (a)","body":"At $t=0$, $2500=Ae^0$, so $A=2500$ exactly. At $t=8$, $10000=2500e^{8k}$; hence $e^{8k}=4$ and $k=\\ln4/8=0.1732867951\\ldots$. To four significant figures:\n\n\\[\\boxed{A=2500,\\qquad k=0.1733}\\]"},{"title":"Part (b)","body":"For the second population,\n\n\\[\\frac{dN}{dt}=-36000e^{-0.6t},\\qquad \\left.\\frac{dN}{dt}\\right|_{t=5}=-36000e^{-3}=-1792.334461\\ldots.\\]\n\nThe requested rate of decrease is the positive magnitude, to three significant figures.\n\n\\[\\boxed{1.79\\times10^3\\ \\text{bacteria per hour}}\\]"},{"title":"Part (c)","body":"Retain the exact value $k=\\ln4/8$. Equating populations gives\n\n\\[2500e^{kT}=60000e^{-0.6T}\\quad\\Longrightarrow\\quad e^{(k+0.6)T}=24.\\]\n\nTake natural logs and solve:\n\n\\[T=\\frac{\\ln24}{0.6+\\ln4/8}=4.109799689\\ldots\\ \\text{hours}.\\]\n\n\\[\\boxed{T=4.11\\ \\text{hours}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q04","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":4,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q04_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2023_Oct_Q04_M07_09_LogGraphsModels.png","finalAnswer":"(a) $A=93$\n(b) $T=12.05\\ \\text{months}$\n(c) $4.73\\times10^3\\ \\text{phones per month}$\n(d) $\\text{No: the limiting count is }125000\\text{ phones.}$","steps":[{"title":"Part (a)","body":"Initially $t=0$ and $N=32$, because $N$ is measured in thousands.\n\n\\[32=125-Ae^0=125-A.\\]\n\n\\[\\boxed{A=93}\\]"},{"title":"Part (b)","body":"For 100000 phones, use $N=100$:\n\n\\[100=125-93e^{-0.109T}\\quad\\Longrightarrow\\quad e^{-0.109T}=\\frac{25}{93}.\\]\n\nTaking natural logarithms,\n\n\\[T=\\frac{\\ln(93/25)}{0.109}=12.0525107\\ldots\\ \\text{months}.\\]\n\n\\[\\boxed{T=12.05\\ \\text{months}}\\]"},{"title":"Part (c)","body":"Differentiate the model:\n\n\\[\\frac{dN}{dt}=93(0.109)e^{-0.109t}.\\]\n\nAt $t=7$, this is $4.7265337\\ldots$ thousand phones per month. Multiplying by 1000 gives $4726.5337\\ldots$ phones per month.\n\n\\[\\boxed{4.73\\times10^3\\ \\text{phones per month}}\\]"},{"title":"Part (d)","body":"For $t\\ge0$, $93e^{-0.109t}\\gt 0$, so $N\\lt 125$ and $N\\to125$ as $t\\to\\infty$. The model can therefore never reach 150000 phones: its limiting count is 125000.\n\n\\[\\boxed{\\text{No: the limiting count is }125000\\text{ phones.}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q06","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":6,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q06_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2023_Oct_Q06_M06_09_LogGraphsModels.png","finalAnswer":"(a) $S=3.08\\times10^4\\ \\mathrm{km}^2$\n(b) $S=31600(0.986)^t$\n(c) $\\text{About }98.6\\%\\text{ of the coral-covered sea-floor area remains each year.}$","steps":[{"title":"Part (a)","body":"Substitute $t=2$ into the logarithmic model:\n\n\\[\\log_{10}S=4.5-0.006(2)=4.488\\quad\\Longrightarrow\\quad S=10^{4.488}.\\]\n\nThus $S=30760.968\\ldots\\ \\mathrm{km}^2$. To 3 significant figures, the area is $3.08\\times10^4\\ \\mathrm{km}^2$.\n\n\\[\\boxed{S=3.08\\times10^4\\ \\mathrm{km}^2}\\]"},{"title":"Part (b)","body":"Exponentiating and using index laws,\n\n\\[S=10^{4.5-0.006t}=10^{4.5}(10^{-0.006})^t.\\]\n\nThus $p=31622.7766\\ldots$ and $q=0.9862795\\ldots$. To 3 significant figures, $p=3.16\\times10^4$ and $q=0.986$. Hence the complete model, with both constants rounded as requested, is $S=31600(0.986)^t$, where $S$ is in $\\mathrm{km}^2$ and $t$ is in years.\n\n\\[\\boxed{S=31600(0.986)^t}\\]"},{"title":"Part (c)","body":"The factor $q$ is the yearly multiplier for the sea-floor area covered by coral reefs. Each year, about $98.6\\%$ of the previous year's coral-covered sea-floor area remains. This is a yearly decrease of about $1.4\\%$ (or $1.372\\ldots\\%$ using the unrounded value of $q$).\n\n\\[\\boxed{\\text{About }98.6\\%\\text{ of the coral-covered sea-floor area remains each year.}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q03","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":3,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q03_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2024_Jan_Q03_M07_09_LogGraphsModels.png","finalAnswer":"(a) $a=10.96,\\quad b=2.399$\n(b) $T=9.51\\ \\text{months}$\n(c) $\\text{Yes: }D(12)\\approx398107\\gt 350000$","steps":[{"title":"Part (a)","body":"Exponentiating in base 10,\n\n\\[D=10^{1.04+0.38t}=10^{1.04}(10^{0.38})^t.\\]\n\nThus $a=10^{1.04}=10.96478196\\ldots$ and $b=10^{0.38}=2.398832919\\ldots$. To four significant figures the displayed model is $D\\approx10.96(2.399)^t$.\n\n\\[\\boxed{a=10.96,\\quad b=2.399}\\]"},{"title":"Part (b)","body":"Use the original unrounded logarithmic model:\n\n\\[\\log_{10}45000=1.04+0.38T, \\qquad T=\\frac{\\log_{10}45000-1.04}{0.38}=9.508453984\\ldots.\\]\n\n\\[\\boxed{T=9.51\\ \\text{months}}\\]"},{"title":"Part (c)","body":"At 12 months,\n\n\\[D(12)=10^{1.04+0.38(12)}=10^{5.6}=398107.17\\ldots.\\]\n\nThis exceeds the target of 350000 pounds. The model is increasing because $10^{0.38}\\gt 1$, so the target is reached within the first 12 months.\n\n\\[\\boxed{\\text{Yes: }D(12)\\approx398107\\gt 350000}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q05","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":5,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q05_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2024_Jan_Q05_M07_09_LogGraphsModels.png","finalAnswer":"(a) $A=8$\n(b) $B=0.00639$\n(c) $\\frac{dT}{dt}=-0.0505\\ ^\\circ\\mathrm{C}\\,\\mathrm{min}^{-1}$\n(d) $T\\gt 10\\gt 5$","steps":[{"title":"Part (a)","body":"At $t=0$, $18=10+Ae^0=10+A$.\n\n\\[\\boxed{A=8}\\]"},{"title":"Part (b)","body":"At $t=45$, $16=10+8e^{-45B}$, so $e^{-45B}=6/8=3/4$. Taking logarithms,\n\n\\[-45B=\\ln(3/4),\\qquad B=\\frac{\\ln(4/3)}{45}=0.006392934943\\ldots.\\]\n\n\\[\\boxed{B=0.00639}\\]"},{"title":"Part (c)","body":"Differentiate $T=10+8e^{-Bt}$:\n\n\\[\\frac{dT}{dt}=-8Be^{-Bt}.\\]\n\nAt $t=2$, using the unrounded value $B=\\ln(4/3)/45$, $dT/dt=-0.05049372834\\ldots$. The negative sign means the temperature is falling.\n\n\\[\\boxed{\\frac{dT}{dt}=-0.0505\\ ^\\circ\\mathrm{C}\\,\\mathrm{min}^{-1}}\\]"},{"title":"Part (d)","body":"For every finite $t\\ge0$, $8e^{-Bt}\\gt 0$ because $B\\gt 0$. Thus $T=10+8e^{-Bt}\\gt 10$; as $t\\to\\infty$, T approaches 10 from above. It therefore cannot reach 5 degrees Celsius.\n\n\\[\\boxed{T\\gt 10\\gt 5}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q03","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":3,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q03_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2024_MayJune_Q03_M06_09_LogGraphsModels.png","finalAnswer":"(i) $Y=6-3X;\\quad(0,6),\\ (2,0)$\n(ii) $a=81,\\quad b=9$","steps":[{"title":"Part (i)","body":"Put $X=\\log_{10}x$ and $Y=\\log_{10}y$. Taking logarithms of $y=10^6/x^3$ gives\n\n\\[Y=6-3X.\\]\n\nAt $X=0$, $Y=6$; at $Y=0$, $X=2$. The graph is a straight line of gradient $-3$.\n\n\\[\\boxed{Y=6-3X;\\quad(0,6),\\ (2,0)}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2024_MayJune_Q03-1.png","alt":"Sketch for part (i)"}]},{"title":"Part (ii)","body":"The gradient in the given plot is $(4-0)/(0-(-2))=2$ and its vertical intercept is 4. Therefore $\\log_3N=2t+4$. Exponentiating in base 3,\n\n\\[N=3^{2t+4}=3^4(3^2)^t=81\\cdot9^t.\\]\n\n\\[\\boxed{a=81,\\quad b=9}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q08","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":8,"marks":10,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation","13_NumericalMethods"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation","Numerical Methods"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation","13_NumericalMethods"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation","Numerical Methods"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q08_M10_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2024_MayJune_Q08_M10_09_LogGraphsModels.png","finalAnswer":"(a) $d=54.93\\ \\text{m}$\n(b) $x=50\\ln\\left(\\frac{150}{x+50}\\right)$\n(c) $x_2=31.43,\\quad x_{\\mathrm{maximum}}=30.88\\ \\text{m}$","steps":[{"title":"Part (a)","body":"At the first landing, $h=0$ and $x=d\\gt 0$:\n\n\\[0=d(1.5-0.5e^{0.02d}),\\qquad e^{0.02d}=3.\\]\n\nTaking logarithms, $0.02d=\\ln3$, hence $d=50\\ln3=54.930614\\ldots$. The root $x=0$ is the launch point, not the landing point.\n\n\\[\\boxed{d=54.93\\ \\text{m}}\\]"},{"title":"Part (b)","body":"By the product and chain rules,\n\n\\[h'(x)=1.5-0.5e^{0.02x}-0.01xe^{0.02x}.\\]\n\nAt a stationary point,\n\n\\[1.5=0.01(x+50)e^{0.02x},\\qquad e^{0.02x}=\\frac{150}{x+50}.\\]\n\nSince $x+50\\gt 0$, logarithms give $0.02x=\\ln(150/(x+50))$. Also $h”(x)=-(0.02+0.0002x)e^{0.02x}\\lt 0$ on $[0,d]$. Thus the stationary point is the unique maximum; the endpoints both have zero height.\n\n\\[\\boxed{x=50\\ln\\left(\\frac{150}{x+50}\\right)}\\]"},{"title":"Part (c)","body":"(i) With $x_1=30$,\n\n\\[x_2=50\\ln\\left(\\frac{150}{30+50}\\right)=31.43043297\\ldots.\\]\n\n(ii) Continuing with full intermediate precision gives $x_3=30.54431108\\ldots$, $x_4=31.09139065\\ldots$, $x_5=30.75292479\\ldots$ and $x_6=30.96205562\\ldots$. Continued iteration converges to $30.88212\\ldots$, which lies in $(0,d)$. This is the horizontal distance at maximum height, not the maximum height itself.\n\n\\[\\boxed{x_2=31.43,\\quad x_{\\mathrm{maximum}}=30.88\\ \\text{m}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q04","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":4,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q04_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2024_Oct_Q04_M06_09_LogGraphsModels.png","finalAnswer":"(a) $N(0)=100$\n(b) $a=100,\\qquad b=2.24$\n(c) $\\left.\\frac{dN}{dt}\\right|_{t=5}=4.53\\times10^3\\ \\text{bacteria per hour}$","steps":[{"title":"Part (a)","body":"At $t=0$, $\\log_{10}N=2$, so $N=10^2$.\n\n\\[\\boxed{N(0)=100}\\]"},{"title":"Part (b)","body":"Exponentiating base 10 gives\n\n\\[N=10^{0.35t+2}=10^2(10^{0.35})^t=100(10^{0.35})^t.\\]\n\nThus $a=100$ and $b=10^{0.35}=2.238721\\ldots$, which is $2.24$ to 2 decimal places.\n\n\\[\\boxed{a=100,\\qquad b=2.24}\\]"},{"title":"Part (c)","body":"Retain the unrounded base $10^{0.35}$ when differentiating:\n\n\\[\\frac{dN}{dt}=100(10^{0.35})^t\\ln(10^{0.35}) =0.35\\ln(10)\\,10^{0.35t+2}.\\]\n\nAt $t=5$ this is $0.35\\ln(10)\\,10^{3.75}=4531.9356\\ldots$ bacteria per hour.\n\n\\[\\boxed{\\left.\\frac{dN}{dt}\\right|_{t=5}=4.53\\times10^3\\ \\text{bacteria per hour}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q08","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":8,"marks":12,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation","13_NumericalMethods"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation","Numerical Methods"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation","13_NumericalMethods"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation","Numerical Methods"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q08_M12_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2024_Oct_Q08_M12_09_LogGraphsModels.png","finalAnswer":"(a) $H(0)=52\\ \\text{bpm}$\n(b) $L=32$\n(c) $T=1.158\\ \\text{minutes}$\n(d) $t=5\\ln\\left(\\frac8{1+4e^{-0.9t}}\\right)$\n(e) $t_2=10.3947,\\quad M=10.3955\\ \\text{minutes}$","steps":[{"title":"Part (a)","body":"At $t=0$, $H=32+40-20=52$.\n\n\\[\\boxed{H(0)=52\\ \\text{bpm}}\\]"},{"title":"Part (b)","body":"As $t\\to\\infty$, both decaying exponential terms tend to zero.\n\n\\[\\boxed{L=32}\\]"},{"title":"Part (c)","body":"\\[\\frac{dH}{dt}=-8e^{-0.2t}+18e^{-0.9t}.\\]\n\nAt the maximum,\n\n\\[18e^{-0.9T}=8e^{-0.2T} \\quad\\Longrightarrow\\quad e^{0.7T}=\\frac94 \\quad\\Longrightarrow\\quad T=\\frac{10}{7}\\ln\\frac94=1.1584717\\ldots.\\]\n\nAlso $H”(t)=1.6e^{-0.2t}-16.2e^{-0.9t}$. At the stationary point, $e^{-0.9T}=(4/9)e^{-0.2T}$, so $H”(T)=-5.6e^{-0.2T}\\lt 0$, confirming a maximum.\n\n\\[\\boxed{T=1.158\\ \\text{minutes}}\\]"},{"title":"Part (d)","body":"For $H=37$,\n\n\\[5=40e^{-0.2t}-20e^{-0.9t} \\quad\\Longrightarrow\\quad 8e^{-0.2t}=1+4e^{-0.9t}.\\]\n\nTaking logarithms gives\n\n\\[-0.2t=\\ln\\left(\\frac{1+4e^{-0.9t}}8\\right) \\quad\\Longrightarrow\\quad t=-5\\ln\\left(\\frac{1+4e^{-0.9t}}8\\right).\\]\n\nUsing $-\\ln u=\\ln(1/u)$ for $u\\gt 0$ then gives\n\n\\[t=5\\ln\\left(\\frac8{1+4e^{-0.9t}}\\right).\\]\n\n\\[\\boxed{t=5\\ln\\left(\\frac8{1+4e^{-0.9t}}\\right)}\\]"},{"title":"Part (e)","body":"Starting with $t_1=10$,\n\n\\[t_2=5\\ln\\left(\\frac8{1+4e^{-9}}\\right)=10.3947401213\\ldots.\\]\n\nContinuing without rounding intermediate values gives $t_3=10.3954778346\\ldots$, $t_4=10.3954789826\\ldots$ and $t_5=10.3954789844\\ldots$. Thus (i) $t_2=10.3947$, and (ii) $M=10.3955$ minutes, both to 4 decimal places.\n\n\\[\\boxed{t_2=10.3947,\\quad M=10.3955\\ \\text{minutes}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q02","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":2,"marks":3,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q02_M03_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2025_Jan_Q02_M03_09_LogGraphsModels.png","finalAnswer":"(a) $A(0)=10\\ \\mathrm{m}^2$\n(b) $T=13.26\\text{ weeks}$","steps":[{"title":"Part (a)","body":"At $t=0$, $\\log_{10}A=1$, hence $A=10^1=10$ square metres.\n\n\\[\\boxed{A(0)=10\\ \\mathrm{m}^2}\\]"},{"title":"Part (b)","body":"Substitute $A=25$ into the model:\n\n\\[\\log_{10}25=1+0.03T\\quad\\Longrightarrow\\quad T=\\frac{\\log_{10}25-1}{0.03}=13.2646669557\\ldots.\\]\n\n\\[\\boxed{T=13.26\\text{ weeks}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q05","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":5,"marks":9,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["03_GraphTransformations","08_ExponentialsLogs","10_DifferentiationTechniques"],"secondaryTopicNames":["Graph Transformations","Exponentials & Logarithms","Differentiation Techniques"],"topics":["09_LogGraphsModels","03_GraphTransformations","08_ExponentialsLogs","10_DifferentiationTechniques"],"topicNames":["Log Graphs & Exponential Models","Graph Transformations","Exponentials & Logarithms","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q05_M09_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2025_Jan_Q05_M09_09_LogGraphsModels.png","finalAnswer":"(a) $H(0)=304^\\circ\\mathrm C$\n(b) $H=24\\text{ is the horizontal asymptote}$\n(c) $t=16.95\\text{ minutes}$\n(d) $a=1.2,\\quad b=-0.05$","steps":[{"title":"Part (a)","body":"At $t=0$, $e^{-0.05t}=1$, so $H=280+24=304$ degrees Celsius.\n\n\\[\\boxed{H(0)=304^\\circ\\mathrm C}\\]"},{"title":"Part (b)","body":"The curve starts at $(0,304)$ and decreases for $t\\ge0$. The exponential term stays positive and tends to zero, so the curve approaches $H=24$ from above without crossing it.\n\n\\[\\boxed{H=24\\text{ is the horizontal asymptote}}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2025_Jan_Q05-1.png","alt":"Sketch for part (b)"}]},{"title":"Part (c)","body":"Substitute $H=144$:\n\n\\[144=280e^{-0.05t}+24\\ \\Longrightarrow\\ e^{-0.05t}=\\frac{120}{280}=\\frac37.\\]\n\nTake natural logarithms: $-0.05t=\\ln(3/7)$. Hence $t=-20\\ln(3/7)=20\\ln(7/3)=16.9459572077\\ldots$ minutes.\n\n\\[\\boxed{t=16.95\\text{ minutes}}\\]"},{"title":"Part (d)","body":"Differentiate using the chain rule:\n\n\\[\\frac{dH}{dt}=-0.05(280)e^{-0.05t}=-14e^{-0.05t}.\\]\n\nThe original equation gives $280e^{-0.05t}=H-24$, so\n\n\\[\\frac{dH}{dt}=-0.05(H-24)=1.2-0.05H.\\]\n\n\\[\\boxed{a=1.2,\\quad b=-0.05}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q03","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":3,"marks":5,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q03_M05_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2025_MayJune_Q03_M05_09_LogGraphsModels.png","finalAnswer":"(a) $\\log_{10}y=-\\frac47\\log_{10}x-2$\n(b) $y=\\frac1{100}x^{-4/7}$, $p=\\frac1{100},\\quad q=-\\frac47$","steps":[{"title":"Part (a)","body":"The gradient in the logarithmic coordinates is\n\n\\[m=\\frac{-2-0}{0-(-3.5)}=-\\frac47.\\]\n\nUsing the vertical intercept $-2$,\n\n\\[\\boxed{\\log_{10}y=-\\frac47\\log_{10}x-2}.\\]"},{"title":"Part (b)","body":"For $x\\gt 0$, the logarithm laws give\n\n\\[\\log_{10}y=\\log_{10}(x^{-4/7})+\\log_{10}\\frac1{100} =\\log_{10}\\left(\\frac1{100}x^{-4/7}\\right).\\]\n\nTherefore\n\n\\[\\boxed{y=\\frac1{100}x^{-4/7}},\\qquad \\boxed{p=\\frac1{100},\\quad q=-\\frac47}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q06","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":6,"marks":8,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q06_M08_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2025_MayJune_Q06_M08_09_LogGraphsModels.png","finalAnswer":"(a) $A=54$\n(b) $0.521$\n(c) $2.19\\text{ minutes}$","steps":[{"title":"Part (a)","body":"At $t=0$, $75=21+A$, so $\\boxed{A=54}$."},{"title":"Part (b)","body":"At $t=5$, $25=21+54e^{-5k}$, hence\n\n\\[e^{-5k}=\\frac2{27},\\qquad k=\\frac15\\ln\\frac{27}{2}=0.520537937\\ldots=\\boxed{0.521}.\\]"},{"title":"Part (c)","body":"Differentiate the temperature model:\n\n\\[\\frac{d\\theta}{dt}=-54ke^{-kt}.\\]\n\nA decrease of $9\\,{}^{\\circ}\\mathrm{C}$ per minute means $d\\theta/dt=-9$, not $+9$. Thus\n\n\\[-54ke^{-kT}=-9\\ \\Longrightarrow\\ e^{-kT}=\\frac1{6k} \\ \\Longrightarrow\\ T=\\frac{\\ln(6k)}{k}.\\]\n\nUsing the unrounded value of $k$,\n\n\\[T=2.187865\\ldots=\\boxed{2.19\\text{ minutes}}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q03","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":3,"marks":9,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q03_M09_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2025_Oct_Q03_M09_09_LogGraphsModels.png","finalAnswer":"(a) $log10(V)=0.05*t+2$\n(b) $V=100*(1.12)^t$\n(c) $13$","steps":[{"title":"Part (a)","body":"The gradient is $(2.25-2)/(5-0)=0.05$ and the vertical intercept is $2$. Hence $\\log_{10}V=0.05t+2$."},{"title":"Part (b)","body":"\\[V=10^{0.05t+2}=100(10^{0.05})^t.\\]\n\nThus $a=100$ exactly and $b=10^{0.05}=1.122018454\\ldots=1.12$ to three significant figures. In the requested rounded-parameter form, $V=100(1.12)^t$; retain the unrounded base for later calculations."},{"title":"Part (c)","body":"Differentiating the unrounded model,\n\n\\[\\frac{dV}{dt}=100(0.05\\ln10)\\,10^{0.05t}=5\\ln10\\,10^{0.05t}.\\]\n\nAt $t=T$ this equals $50$, so\n\n\\[10^{0.05T}=\\frac{10}{\\ln10},\\qquad T=\\frac{\\ln(10/\\ln10)}{0.05\\ln10}=12.755686226\\ldots.\\]\n\nTherefore $T=13$ years to the nearest integer."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q05","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":5,"marks":8,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q05_M08_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2025_Oct_Q05_M08_09_LogGraphsModels.png","finalAnswer":"(a) $200$\n(b) $400*exp(t/10)*(19-exp(t/5))/(19+exp(t/5))^2$\n(c) $exp(T/5)=19$\n(d) $459$","steps":[{"title":"Part (a)","body":"At $t=0$, $N=4000/(19+1)=200$ squirrels."},{"title":"Part (b)","body":"The quotient rule gives\n\n\\[\\frac{dN}{dt} =\\frac{400e^{0.1t}(19+e^{0.2t})-800e^{0.3t}} {(19+e^{0.2t})^2} =\\frac{400e^{0.1t}(19-e^{0.2t})}{(19+e^{0.2t})^2}.\\]"},{"title":"Part (c)","body":"At $t=T$, the derivative is zero. The exponential and denominator are positive, so $19-e^{0.2T}=0$. Therefore $e^{0.2T}=19$ and $A=19$. The derivative is positive before $T$ and negative after $T$, confirming a maximum."},{"title":"Part (d)","body":"Since $e^{0.2T}=19$, we have $e^{0.1T}=\\sqrt{19}$. Substitution into the model gives\n\n\\[N_{\\max}=\\frac{4000\\sqrt{19}}{19+19} =\\frac{2000}{\\sqrt{19}}=458.831467741\\ldots.\\]\n\nThe maximum number is $459$ squirrels to the nearest whole number."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q04","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":4,"marks":6,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs"],"secondaryTopicNames":["Exponentials & Logarithms"],"topics":["09_LogGraphsModels","08_ExponentialsLogs"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q04_M06_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2026_Jan_Q04_M06_09_LogGraphsModels.png","finalAnswer":"(a) $191\\text{ beats per minute}$\n(b) $p=10^{2.4}=251\\ \\text{(3 s.f.)},\\qquad q=0.25$\n(c) $predicted heart rate, in beats per minute, for a mammal of mass $1$ kg$","steps":[{"title":"Part (a)","body":"At $m=3$,\n\n\\[\\log_{10}h=2.4-0.25\\log_{10}3, \\qquad h=10^{2.4-0.25\\log_{10}3}=190.862095\\ldots.\\]\n\nThe predicted heart rate is $191$ beats per minute (3 significant figures)."},{"title":"Part (b)","body":"Using the power law of logarithms,\n\n\\[\\log_{10}h=\\log_{10}(10^{2.4})-\\log_{10}(m^{0.25}) =\\log_{10}\\!\\left(\\frac{10^{2.4}}{m^{0.25}}\\right).\\]\n\nTherefore\n\n\\[h=\\frac{10^{2.4}}{m^{0.25}},\\qquad p=10^{2.4}=251\\ \\text{(3 s.f.)},\\qquad q=0.25.\\]\n\nThe model, with its coefficient rounded as requested, is\n\n\\[h=\\frac{251}{m^{0.25}}.\\]"},{"title":"Part (c)","body":"When $m=1$, $h=p$. Thus $p$ is the model's predicted heart rate, in beats per minute, for a mammal of mass $1$ kg."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q10","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":10,"marks":9,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q10_M09_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2026_Jan_Q10_M09_09_LogGraphsModels.png","finalAnswer":"(a) $180e\\text{ insects per year}$\n(b) $P=2000,\\ k=0.145\\text{ (3 d.p.)}$\n(c) $14.5\\text{ years}$","steps":[{"title":"Part (a)","body":"\\[\\frac{dN_A}{dt}=900(0.2)e^{0.2t}=180e^{0.2t}.\\]\n\nAt $t=5$, the growth rate is $180e=489.290729\\ldots$ insects per year."},{"title":"Part (b)","body":"At $t=0$, $10000=8000+P$, so $P=2000$ exactly. Using the population at $t=4$,\n\n\\[11570=8000+2000e^{4k} \\quad\\Longrightarrow\\quad e^{4k}=\\frac{3570}{2000}=1.785.\\]\n\nTaking natural logarithms,\n\n\\[k=\\frac{\\ln1.785}{4}=0.144854604\\ldots=0.145\\quad\\text{(3 d.p.)}.\\]"},{"title":"Part (c)","body":"At equality, $8000+900e^{0.2T}=8000+2000e^{kT}$, hence\n\n\\[e^{(0.2-k)T}=\\frac{20}{9},\\qquad T=\\frac{\\ln(20/9)}{0.2-k}.\\]\n\nUse the unrounded value $k=\\ln(1.785)/4$:\n\n\\[T=14.480042784\\ldots=14.5\\text{ years (1 decimal place)}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q05","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":5,"marks":7,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q05_M07_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2026_MayJune_Q05_M07_09_LogGraphsModels.png","finalAnswer":"(a) $a=316,\\quad b=1.19$\n(b) $19\\%\\text{ per year}$\n(c) $\\frac{dH}{dt}=1.3\\times10^2\\text{ households per year}$","steps":[{"title":"Part (a)","body":"Taking base-10 logarithms gives\n\n\\[\\log_{10}H=\\log_{10}a+t\\log_{10}b.\\]\n\nThe vertical intercept is $2.5$ and the gradient is $\\dfrac{3.25-2.5}{10-0}=0.075$. Therefore\n\n\\[a=10^{2.5}=316.227766\\ldots,\\qquad b=10^{0.075}=1.188502227\\ldots.\\]\n\nTo 3 significant figures, $\\boxed{a=316,\\quad b=1.19}$."},{"title":"Part (b)","body":"Each year the model multiplies the number of recycling households by $b$. This means an increase of approximately $\\boxed{19\\%\\text{ per year}}$ (about $18.85\\%$ using the unrounded value)."},{"title":"Part (c)","body":"Retain the unrounded constants:\n\n\\[H=10^{2.5+0.075t},\\qquad \\frac{dH}{dt}=0.075\\ln(10)\\,10^{2.5+0.075t}.\\]\n\nAt $t=5$ this is $129.5021421\\ldots$, hence\n\n\\[\\boxed{\\frac{dH}{dt}=1.3\\times10^2\\text{ households per year}}\\]\n\nto 2 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q07","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":7,"marks":12,"topic":"09_LogGraphsModels","topicName":"Log Graphs & Exponential Models","primaryTopic":"09_LogGraphsModels","primaryTopicName":"Log Graphs & Exponential Models","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"topics":["09_LogGraphsModels","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Log Graphs & Exponential Models","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q07_M12_09_LogGraphsModels.png","downloadName":"WMA13-01_Y2026_MayJune_Q07_M12_09_LogGraphsModels.png","finalAnswer":"(a) $T=6.93\\text{ years}$\n(b) $-0.97\\text{ thousand pounds per year}$\n(c)(i) $m=32$\n(c)(ii) $\\pounds13\\,000$\n(d) $\\alpha=4.38\\text{ years}$","steps":[{"title":"Part (a)","body":"Prices in the model are in thousands of pounds, so\n\n\\[15=7+16e^{-0.1T}\\quad\\Longrightarrow\\quad e^{-0.1T}=\\frac12.\\]\n\nTaking logarithms gives $T=10\\ln2=6.9314718\\ldots$, hence $\\boxed{T=6.93\\text{ years}}$."},{"title":"Part (b)","body":"\\[\\frac{dP_C}{dt}=-1.6e^{-0.1t},\\qquad \\left.\\frac{dP_C}{dt}\\right|_{t=5}=-1.6e^{-0.5}=-0.970449\\ldots.\\]\n\nThus the answer is $\\boxed{-0.97\\text{ thousand pounds per year}}$ to 2 decimal places."},{"title":"Part (c)(i)","body":"At $t=0$, $36=4+m$, so $\\boxed{m=32}$."},{"title":"Part (c)(ii)","body":"The initial car price is $7+16=23$ thousand pounds. The difference is $36-23=13$ thousand pounds, or $\\boxed{\\pounds13\\,000}$."},{"title":"Part (d)","body":"Equating the models with $m=32$ gives\n\n\\[7+16e^{-0.1\\alpha}=4+32e^{-0.2\\alpha}.\\]\n\nLet $u=e^{-0.1\\alpha}\\gt 0$. Then $32u^2-16u-3=0$, so\n\n\\[u=\\frac{16\\pm\\sqrt{256+384}}{64}=\\frac{2\\pm\\sqrt{10}}8.\\]\n\nReject the negative root because an exponential is positive. Hence\n\n\\[\\alpha=-10\\ln\\left(\\frac{2+\\sqrt{10}}8\\right)=4.3806365\\ldots, \\qquad \\boxed{\\alpha=4.38\\text{ years}}.\\]\n\nThis value is inside the model interval $0\\leq t\\leq15$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q04","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":4,"marks":11,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["01_RationalAlgebra","06_TrigIdentities","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Trig Identities & Exact Values","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","01_RationalAlgebra","06_TrigIdentities","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Rational Algebra","Trig Identities & Exact Values","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q04_M11_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2020_Jan_Q04_M11_10_DifferentiationTechniques.png","finalAnswer":"(i)(a) $\\frac{(2x+5)(2x-17)}{(x-3)^2}$\n(i)(b) $x\\lt -\\frac52\\quad\\text{or}\\quad x\\gt \\frac{17}{2}$\n(ii) $\\tan4x+2x=0$, $k=2$","steps":[{"title":"Part (i)(a)","body":"Using the quotient rule and the chain rule,\n\n\\[\\begin{aligned} f'(x)&=\\frac{(x-3)\\,4(2x+5)-(2x+5)^2}{(x-3)^2}\\\\ &=\\frac{(2x+5)\\{4(x-3)-(2x+5)\\}}{(x-3)^2}\\\\ &=\\boxed{\\frac{(2x+5)(2x-17)}{(x-3)^2}},\\qquad x\\ne3. \\end{aligned}\\]\n\nThus $P(x)=(2x+5)(2x-17)$ and $Q(x)=(x-3)^2$ are fully factorised quadratics."},{"title":"Part (i)(b)","body":"For $x\\ne3$, the denominator $(x-3)^2$ is positive, so the sign of $f'(x)$ is the sign of $(2x+5)(2x-17)$. For an increasing function we require\n\n\\[(2x+5)(2x-17)\\gt 0.\\]\n\nBoth factors are negative when $x\\lt -\\frac52$, and both are positive when $x\\gt \\frac{17}{2}$. Therefore the required values are\n\n\\[\\boxed{x\\lt -\\frac52\\quad\\text{or}\\quad x\\gt \\frac{17}{2}}.\\]"},{"title":"Part (ii)","body":"For $0\\lt x\\lt \\frac{\\pi}{4}$, we have $\\sin4x\\gt 0$. Applying the product rule and the chain rule gives\n\n\\[\\begin{aligned} g'(x)&=\\sqrt{\\sin4x} +x\\left(\\frac{1}{2\\sqrt{\\sin4x}}\\right)4\\cos4x\\\\ &=\\frac{\\sin4x+2x\\cos4x}{\\sqrt{\\sin4x}}. \\end{aligned}\\]\n\nSince $g(0)=0$ while $g(x)\\gt 0$ in the interior, the stated maximum $M$ does not occur at $x=0$. Its coordinate therefore lies in $0\\lt x\\lt \\frac{\\pi}{4}$, where $g$ is differentiable, so $g'(x)=0$ at $M$. Consequently,\n\n\\[\\sin4x+2x\\cos4x=0.\\]\n\nAt such a point $\\cos4x\\ne0$: the only interior zero of $\\cos4x$ is $x=\\frac{\\pi}{8}$, where the left-hand side above is $1$, not $0$. Dividing by $\\cos4x$ therefore gives\n\n\\[\\boxed{\\tan4x+2x=0},\\qquad\\boxed{k=2}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q03","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":3,"marks":7,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["01_RationalAlgebra","02_Functions","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Functions, Composition & Inverses","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","01_RationalAlgebra","02_Functions","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Rational Algebra","Functions, Composition & Inverses","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q03_M07_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2020_Oct_Q03_M07_10_DifferentiationTechniques.png","finalAnswer":"(a) $f'(x)=\\frac{4(x-2)}{(4x-1)^{3/2}}$\n(b) $\\operatorname{range}(f)=[\\sqrt7,\\infty)$","steps":[{"title":"Part (a)","body":"Write $f(x)=(2x+3)(4x-1)^{-1/2}$. The product and chain rules give\n\n\\[f'(x)=2(4x-1)^{-1/2}-2(2x+3)(4x-1)^{-3/2} =\\frac{2(4x-1)-2(2x+3)}{(4x-1)^{3/2}} =\\frac{4(x-2)}{(4x-1)^{3/2}},\\quad x\\gt \\tfrac14.\\]\n\n\\[\\boxed{f'(x)=\\frac{4(x-2)}{(4x-1)^{3/2}}}\\]"},{"title":"Part (b)","body":"The denominator of $f'(x)$ is positive throughout the domain, so the derivative is negative for $1/4\\lt x\\lt 2$ and positive for $x\\gt 2$. Consequently $x=2$ is the global minimum, with $f(2)=7/\\sqrt7=\\sqrt7$. Also $f(x)\\to\\infty$ as $x\\to1/4^+$ and as $x\\to\\infty$. By continuity all values at least $\\sqrt7$ are attained, including the minimum.\n\n\\[\\boxed{\\operatorname{range}(f)=[\\sqrt7,\\infty)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q08","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":8,"marks":9,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities","07_TrigEquations","08_ExponentialsLogs","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Exponentials & Logarithms","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","06_TrigIdentities","07_TrigEquations","08_ExponentialsLogs","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values","Trig Equations & R-Form","Exponentials & Logarithms","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q08_M09_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2020_Oct_Q08_M09_10_DifferentiationTechniques.png","finalAnswer":"(i)(a) $g'(x)=e^{3x}\\sec2x(3+2\\tan2x)$\n(i)(b) $x=-\\frac12\\arctan\\frac32\\approx-0.491$\n(ii) $f(x)=\\sqrt{1-e^{2x}},\\qquad x\\lt 0$","steps":[{"title":"Part (i)(a)","body":"By the product and chain rules,\n\n\\[g'(x)=3e^{3x}\\sec2x+2e^{3x}\\sec2x\\tan2x =e^{3x}\\sec2x(3+2\\tan2x).\\]\n\n\\[\\boxed{g'(x)=e^{3x}\\sec2x(3+2\\tan2x)}\\]"},{"title":"Part (i)(b)","body":"For $-\\pi/4\\lt x\\lt \\pi/4$, $e^{3x}\\sec2x$ is positive and nonzero. Hence $g'(x)=0$ precisely when $3+2\\tan2x=0$, or $\\tan2x=-3/2$. Since $-\\pi/2\\lt 2x\\lt \\pi/2$, tangent is one-to-one there:\n\n\\[x=-\\frac12\\arctan\\frac32=-0.4913968616\\ldots.\\]\n\n\\[\\boxed{x=-\\frac12\\arctan\\frac32\\approx-0.491}\\]"},{"title":"Part (ii)","body":"Differentiate $x=\\ln(\\sin y)$ with respect to y:\n\n\\[\\frac{dx}{dy}=\\frac{\\cos y}{\\sin y},\\qquad \\frac{dy}{dx}=\\frac{\\sin y}{\\cos y}.\\]\n\nThe original equation gives $\\sin y=e^x$. Since $0\\lt y\\lt \\pi/2$, cosine is positive, so $\\cos y=\\sqrt{1-\\sin^2y}=\\sqrt{1-e^{2x}}$. Therefore\n\n\\[\\frac{dy}{dx}=\\frac{e^x}{\\sqrt{1-e^{2x}}},\\qquad f(x)=\\sqrt{1-e^{2x}}.\\]\n\nHere $x\\lt 0$ from the original interval, so the square root is real and nonzero.\n\n\\[\\boxed{f(x)=\\sqrt{1-e^{2x}},\\qquad x\\lt 0}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q10","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":10,"marks":10,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","06_TrigIdentities","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q10_M10_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2021_Jan_Q10_M10_10_DifferentiationTechniques.png","finalAnswer":"(a) $\\frac{dx}{dy}=12\\sec^22y\\tan2y$\n(b) $p=\\sqrt3,\\quad q=4$\n(c) $y=-\\frac{16\\sqrt3}{3}x+\\frac{64\\sqrt3}{3}+\\frac\\pi{12}$","steps":[{"title":"Part (a)","body":"Apply the chain rule twice:\n\n\\[\\frac{dx}{dy}=3\\cdot2\\sec2y\\,(2\\sec2y\\tan2y)=12\\sec^22y\\tan2y.\\]\n\n\\[\\boxed{\\frac{dx}{dy}=12\\sec^22y\\tan2y}\\]"},{"title":"Part (b)","body":"From $x=3\\sec^22y$, $\\sec^22y=x/3$ and $\\tan^22y=x/3-1$. Since $0\\lt 2y\\lt \\pi/2$, tangent is positive, so $\\tan2y=\\sqrt{(x-3)/3}$. Thus $dx/dy=4x\\sqrt{(x-3)/3}\\gt 0$. Taking the reciprocal gives\n\n\\[\\frac{dy}{dx}=\\frac{\\sqrt3}{4x\\sqrt{x-3}},\\qquad p=\\sqrt3,\\quad q=4.\\]\n\n\\[\\boxed{p=\\sqrt3,\\quad q=4}\\]"},{"title":"Part (c)","body":"At $y=\\pi/12$, $2y=\\pi/6$ and $x=3(4/3)=4$. The tangent gradient is $\\sqrt3/(4\\cdot4\\sqrt1)=\\sqrt3/16$. Therefore the normal gradient is $-16/\\sqrt3=-16\\sqrt3/3$. Using the point $(4,\\pi/12)$,\n\n\\[y-\\frac\\pi{12}=-\\frac{16\\sqrt3}{3}(x-4) \\Longrightarrow y=-\\frac{16\\sqrt3}{3}x+\\frac{64\\sqrt3}{3}+\\frac\\pi{12}.\\]\n\n\\[\\boxed{y=-\\frac{16\\sqrt3}{3}x+\\frac{64\\sqrt3}{3}+\\frac\\pi{12}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q07","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":7,"marks":5,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["10_DifferentiationTechniques","06_TrigIdentities"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q07_M05_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2021_MayJune_Q07_M05_10_DifferentiationTechniques.png","finalAnswer":"(main) $\\frac{dy}{dx}=\\frac1{4\\sqrt{6x-x^2}},\\qquad A=4,\\ B=6$","steps":[{"title":"Part (main)","body":"Differentiate x with respect to y:\n\n\\[\\frac{dx}{dy}=6\\cdot2\\sin2y\\cos2y\\cdot2=24\\sin2y\\cos2y.\\]\n\nSince $0\\lt 2y\\lt \\pi/2$, both sine and cosine are positive. Using $\\sin^22y=x/6$ and $\\cos^22y=1-x/6$,\n\n\\[\\frac{dx}{dy}=24\\sqrt{x/6}\\sqrt{1-x/6} =4\\sqrt{6x-x^2}.\\]\n\nOn $0\\lt x\\lt 6$ this is nonzero, so take its reciprocal.\n\n\\[\\boxed{\\frac{dy}{dx}=\\frac1{4\\sqrt{6x-x^2}},\\qquad A=4,\\ B=6}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q06","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":6,"marks":8,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["01_RationalAlgebra","05_TrigFunctions","06_TrigIdentities","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Trigonometric Functions & Graphs","Trig Identities & Exact Values","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","01_RationalAlgebra","05_TrigFunctions","06_TrigIdentities","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Rational Algebra","Trigonometric Functions & Graphs","Trig Identities & Exact Values","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q06_M08_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2021_Oct_Q06_M08_10_DifferentiationTechniques.png","finalAnswer":"(i) $p=23,\\qquad x=\\frac{\\sqrt{23}}2$\n(ii) $A=4,\\quad B=-12;\\qquad\\text{maximum gradient}=16$","steps":[{"title":"Part (i)","body":"Differentiate to obtain $y'=6x/(x^2-5)-8x$. At a stationary point in $x\\gt \\sqrt5$, x is nonzero, so $6/(x^2-5)=8$, giving $6=8x^2-40$ and $x^2=23/4$. The original positive domain selects $x=\\sqrt{23}/2$, which exceeds $\\sqrt5$. Hence $p=23$.\n\n\\[\\boxed{p=23,\\qquad x=\\frac{\\sqrt{23}}2}\\]"},{"title":"Part (ii)","body":"(a) Differentiate the squared sine with the chain rule: $y'=4-24\\sin x\\cos x=4-12\\sin2x$. Thus $A=4$, $B=-12$. (b) Since $-1\\le\\sin2x\\le1$, the largest derivative is attained when $\\sin2x=-1$: $4-12(-1)=16$.\n\n\\[\\boxed{A=4,\\quad B=-12;\\qquad\\text{maximum gradient}=16}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q08","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":8,"marks":7,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","02_Functions","03_GraphTransformations","05_TrigFunctions","06_TrigIdentities","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Functions, Composition & Inverses","Graph Transformations","Trigonometric Functions & Graphs","Trig Identities & Exact Values","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q08_M07_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2021_Oct_Q08_M07_10_DifferentiationTechniques.png","finalAnswer":"(a) $y=\\arcsin(x/2),\\quad -2\\le x\\le2$\n(b) $A=4,\\qquad\\frac{dy}{dx}=\\frac1{\\sqrt{4-x^2}}$\n(c) $y=\\frac{x}{\\sqrt2}+\\frac\\pi4-1$","steps":[{"title":"Part (a)","body":"The principal arcsine curve increases from $(-2,-\\pi/2)$ through $(0,0)$ to $(2,\\pi/2)$. It is concave down on the negative-x half, concave up on the positive-x half, and vertical at both ends.\n\n\\[\\boxed{y=\\arcsin(x/2),\\quad -2\\le x\\le2}\\]","figures":[{"src":"assets/solution-diagrams/wma13/WMA13-01_2021_Oct_Q08-1.png","alt":"Sketch for part (a)"}]},{"title":"Part (b)","body":"Differentiate the supplied inverse relation: $dx/dy=2\\cos y$. For $-\\pi/2\\lt y\\lt \\pi/2$, cosine is positive, so $\\cos y=\\sqrt{1-\\sin^2y}=\\sqrt{1-x^2/4}$. Taking the reciprocal gives\n\n\\[\\frac{dy}{dx}=\\frac1{2\\cos y}=\\frac1{\\sqrt{4-x^2}},\\qquad -2\\lt x\\lt 2.\\]\n\nThus $A=4$; the endpoints have vertical tangents, not finite derivatives.\n\n\\[\\boxed{A=4,\\qquad\\frac{dy}{dx}=\\frac1{\\sqrt{4-x^2}}}\\]"},{"title":"Part (c)","body":"At $y=\\pi/4$, $x=2\\sin(\\pi/4)=\\sqrt2$. The gradient is $1/\\sqrt{4-2}=1/\\sqrt2$. Hence $y-\\pi/4=(x-\\sqrt2)/\\sqrt2$, so $y=x/\\sqrt2+\\pi/4-1$.\n\n\\[\\boxed{y=\\frac{x}{\\sqrt2}+\\frac\\pi4-1}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q10","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":10,"marks":7,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["02_Functions","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Functions, Composition & Inverses","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","02_Functions","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Functions, Composition & Inverses","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q10_M07_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2022_Jan_Q10_M07_10_DifferentiationTechniques.png","finalAnswer":"(a) $\\frac{dy}{dx}=\\frac{y}{x(1+2y)}\\quad\\text{where defined}$\n(b) $-\\frac1{2e}\\lt k\\lt 0$","steps":[{"title":"Part (a)","body":"Differentiate x with respect to y by the product rule:\n\n\\[\\frac{dx}{dy}=e^{2y}+2ye^{2y}=e^{2y}(1+2y).\\]\n\nWhere $dx/dy\\ne0$, take the reciprocal:\n\n\\[\\frac{dy}{dx}=\\frac{e^{-2y}}{1+2y}.\\]\n\nFor $y\\ne0$, the original relation gives $e^{2y}=x/y$, hence the required form $dy/dx=y/[x(1+2y)]$. At the origin, that last quotient is $0/0$; the preceding uncancelled derivative gives $dy/dx=1$. At $y=-1/2$ there is no finite $dy/dx$.\n\n\\[\\boxed{\\frac{dy}{dx}=\\frac{y}{x(1+2y)}\\quad\\text{where defined}}\\]"},{"title":"Part (b)","body":"Consider $x=h(y)=ye^{2y}$. Its derivative $h'(y)=e^{2y}(1+2y)$ vanishes at $y=-1/2$. It is negative before this y value and positive after it, so the minimum x value is $h(-1/2)=-1/(2e)$. As $y\\to-\\infty$, $h(y)\\to0$ from below; also $h(0)=0$ and h then increases without bound. Thus a level $x=k$ meets both negative-y branches precisely between the minimum and zero. At the minimum the two intersections coincide; at zero there is just the finite point $y=0$.\n\n\\[\\boxed{-\\frac1{2e}\\lt k\\lt 0}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q04","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":4,"marks":5,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["02_Functions","08_ExponentialsLogs"],"secondaryTopicNames":["Functions, Composition & Inverses","Exponentials & Logarithms"],"topics":["10_DifferentiationTechniques","02_Functions","08_ExponentialsLogs"],"topicNames":["Differentiation Techniques","Functions, Composition & Inverses","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q04_M05_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2022_Oct_Q04_M05_10_DifferentiationTechniques.png","finalAnswer":"(a) $x=\\frac{10^y-1}{2}$\n(b) $\\frac{dy}{dx}=\\frac2{(2x+1)\\ln10}$","steps":[{"title":"Part (a)","body":"The logarithm is base 10. Thus $10^y=2x+1$ and $2x=10^y-1$.\n\n\\[\\boxed{x=\\frac{10^y-1}{2}}\\]"},{"title":"Part (b)","body":"Differentiate the result of (a) with respect to y:\n\n\\[\\frac{dx}{dy}=\\frac12\\,10^y\\ln10.\\]\n\nTake the reciprocal and use $10^y=2x+1$:\n\n\\[\\frac{dy}{dx}=\\frac2{10^y\\ln10}=\\frac2{(2x+1)\\ln10}.\\]\n\nThe original logarithm requires $x\\gt -1/2$.\n\n\\[\\boxed{\\frac{dy}{dx}=\\frac2{(2x+1)\\ln10}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q06","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":6,"marks":6,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["10_DifferentiationTechniques","06_TrigIdentities"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q06_M06_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2022_Oct_Q06_M06_10_DifferentiationTechniques.png","finalAnswer":"(main) $a=2,\\quad b=3,\\quad c=-2$","steps":[{"title":"Part (main)","body":"With $y=(2+3\\sin x)/(\\cos x+\\sin x)$, the quotient rule gives\n\n\\[\\frac{dy}{dx}=\\frac{3\\cos x(\\cos x+\\sin x)-(2+3\\sin x)(\\cos x-\\sin x)}{(\\cos x+\\sin x)^2}.\\]\n\nExpand the numerator and cancel the opposite mixed terms:\n\n\\[3\\cos^2x+3\\sin^2x-2\\cos x+2\\sin x=3-2\\cos x+2\\sin x.\\]\n\nThe denominator is $1+2\\sin x\\cos x$. Divide numerator and denominator by $\\cos x$ to obtain\n\n\\[\\frac{dy}{dx}=\\frac{2\\tan x+3\\sec x-2}{\\sec x+2\\sin x}.\\]\n\nThis displayed form is used where its trigonometric terms are defined; the preceding quotient form also covers points with $\\cos x=0$ when the original denominator is nonzero.\n\n\\[\\boxed{a=2,\\quad b=3,\\quad c=-2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q03","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":3,"marks":7,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities","12_Integration"],"secondaryTopicNames":["Trig Identities & Exact Values","Integration"],"topics":["10_DifferentiationTechniques","06_TrigIdentities","12_Integration"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q03_M07_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2023_MayJune_Q03_M07_10_DifferentiationTechniques.png","finalAnswer":"(i) $6\\cot3x$\n(ii)(a) $36x(3x^2-4)^5$\n(ii)(b) $R=-112$","steps":[{"title":"Part (i)","body":"Differentiate the logarithm directly on its domain $\\sin3x\\ne0$:\n\n\\[\\frac{d}{dx}\\ln(\\sin^2 3x) =\\frac{2\\sin3x\\cos3x\\cdot3}{\\sin^2 3x}=6\\cot3x.\\]\n\nThis does not assume $\\sin3x\\gt 0$; the logarithm's argument is its square.\n\n\\[\\boxed{6\\cot3x}\\]"},{"title":"Part (ii)(a)","body":"Apply the power and chain rules:\n\n\\[\\frac{d}{dx}(3x^2-4)^6=6(3x^2-4)^5(6x)=36x(3x^2-4)^5.\\]\n\n\\[\\boxed{36x(3x^2-4)^5}\\]"},{"title":"Part (ii)(b)","body":"From part (ii)(a), an antiderivative of $x(3x^2-4)^5$ is $(3x^2-4)^6/36$.\n\n\\[R=\\left[\\frac{(3x^2-4)^6}{36}\\right]_0^{\\sqrt2} =\\frac{2^6-(-4)^6}{36}=\\frac{64-4096}{36}=-112.\\]\n\n\\[\\boxed{R=-112}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q10","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":10,"marks":8,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["01_RationalAlgebra","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","01_RationalAlgebra","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Rational Algebra","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q10_M08_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2023_MayJune_Q10_M08_10_DifferentiationTechniques.png","finalAnswer":"(a) $\\frac{dx}{dy}=\\frac{2(y-3)(y+1)}{3(y-1)^2},\\quad y\\ne1$\n(b) $x=-\\frac43,\\qquad x=4$","steps":[{"title":"Part (a)","body":"The quotient rule gives, for $y\\ne1$,\n\n\\[\\frac{dx}{dy}=\\frac{4y(3y-3)-3(2y^2+6)}{(3y-3)^2} =\\frac{6y^2-12y-18}{9(y-1)^2} =\\frac{2(y-3)(y+1)}{3(y-1)^2}.\\]\n\n\\[\\boxed{\\frac{dx}{dy}=\\frac{2(y-3)(y+1)}{3(y-1)^2},\\quad y\\ne1}\\]"},{"title":"Part (b)","body":"A tangent parallel to the $y$-axis is vertical, so $dx/dy=0$. The numerator gives $(y-3)(y+1)=0$, hence $y=3$ or $y=-1$; neither makes the denominator zero. Then\n\n\\[x(3)=\\frac{18+6}{9-3}=4,\\qquad x(-1)=\\frac{2+6}{-3-3}=-\\frac43.\\]\n\nThus $Q=(4,3)$ and $P=(-4/3,-1)$, with the vertical tangent equations below.\n\n\\[\\boxed{x=-\\frac43,\\qquad x=4}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q10","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":10,"marks":9,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["01_RationalAlgebra","02_Functions","06_TrigIdentities","07_TrigEquations","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Functions, Composition & Inverses","Trig Identities & Exact Values","Trig Equations & R-Form","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","01_RationalAlgebra","02_Functions","06_TrigIdentities","07_TrigEquations","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Rational Algebra","Functions, Composition & Inverses","Trig Identities & Exact Values","Trig Equations & R-Form","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q10_M09_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2023_Oct_Q10_M09_10_DifferentiationTechniques.png","finalAnswer":"(a) $y=\\frac\\pi{24}$\n(b) $\\frac{dx}{dy}=8\\sin4y\\cos4y$\n(c) $q=16,\\qquad r=-64,\\qquad s=-\\frac12$\n(d) $\\text{(i) }x=\\frac12,\\qquad\\text{(ii) }\\min\\frac{dy}{dx}=\\frac14$","steps":[{"title":"Part (a)","body":"At $x=1/4$, $\\sin^2 4y=1/4$. Since $0\\le4y\\le\\pi/2$,\n\n\\[\\sin4y=\\frac12\\quad\\Longrightarrow\\quad4y=\\frac\\pi6.\\]\n\nOnly this branch lies in the given range of $y$.\n\n\\[\\boxed{y=\\frac\\pi{24}}\\]"},{"title":"Part (b)","body":"Differentiate $x=(\\sin4y)^2$ with respect to $y$:\n\n\\[\\frac{dx}{dy}=2\\sin4y\\,(4\\cos4y).\\]\n\n\\[\\boxed{\\frac{dx}{dy}=8\\sin4y\\cos4y}\\]"},{"title":"Part (c)","body":"On the interior of the given interval, $\\sin4y=\\sqrt{x}$ and $\\cos4y=\\sqrt{1-x}$ are positive. Taking the reciprocal,\n\n\\[\\frac{dy}{dx}=\\frac1{8\\sqrt{x}\\sqrt{1-x}} =\\frac1{\\sqrt{64x-64x^2}}.\\]\n\nComplete the square:\n\n\\[64x-64x^2=16-64\\left(x-\\frac12\\right)^2.\\]\n\nThus $dy/dx=(q+r(x+s)^2)^{-1/2}$ has the constants below, with $0\\lt x\\lt 1$ for a finite derivative; the endpoints have vertical tangents.\n\n\\[\\boxed{q=16,\\qquad r=-64,\\qquad s=-\\frac12}\\]"},{"title":"Part (d)","body":"The derivative is positive. Its minimum occurs when the square root in the denominator is largest. Since $(x-1/2)^2\\ge0$, the largest radicand is 16, attained at $x=1/2$. Hence the smallest gradient is $1/\\sqrt{16}$.\n\n\\[\\boxed{\\text{(i) }x=\\frac12,\\qquad\\text{(ii) }\\min\\frac{dy}{dx}=\\frac14}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q10","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":10,"marks":9,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities","07_TrigEquations","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","06_TrigIdentities","07_TrigEquations","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values","Trig Equations & R-Form","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q10_M09_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2025_Jan_Q10_M09_10_DifferentiationTechniques.png","finalAnswer":"(a) $\\frac{dx}{dy}=-6\\sin2y$\n(b) $\\frac{dy}{dx}=-\\frac1{2\\sqrt{9-x^2}},\\qquad k=-\\frac12$\n(c) $a=\\sqrt5,\\qquad b=\\frac12\\arccos\\!\\left(\\frac{\\sqrt5}{3}\\right)$","steps":[{"title":"Part (a)","body":"Differentiate $x=3\\cos2y$ with respect to $y$ using the chain rule:\n\n\\[\\frac{dx}{dy}=3(-\\sin2y)\\cdot2=-6\\sin2y.\\]\n\n\\[\\boxed{\\frac{dx}{dy}=-6\\sin2y}\\]"},{"title":"Part (b)","body":"For $0\\lt y\\lt \\pi/2$, $\\sin2y\\gt 0$ and\n\n\\[\\frac{dy}{dx}=\\frac1{dx/dy}=-\\frac1{6\\sin2y}.\\]\n\nSince $\\cos2y=x/3$ and the sine is positive on this interval,\n\n\\[\\sin2y=\\sqrt{1-\\cos^22y}=\\sqrt{1-x^2/9}=\\frac{\\sqrt{9-x^2}}3.\\]\n\nConsequently $dy/dx=-1/(2\\sqrt{9-x^2})$, valid for $-3\\lt x\\lt 3$. The endpoint tangents are vertical; there is no finite derivative there.\n\n\\[\\boxed{\\frac{dy}{dx}=-\\frac1{2\\sqrt{9-x^2}},\\qquad k=-\\frac12}\\]"},{"title":"Part (c)","body":"Set the gradient equal to $-1/4$:\n\n\\[-\\frac1{2\\sqrt{9-a^2}}=-\\frac14 \\quad\\Longrightarrow\\quad \\sqrt{9-a^2}=2 \\quad\\Longrightarrow\\quad a^2=5.\\]\n\nBecause $a\\gt 0$, take $a=\\sqrt5$. Substitute into $a=3\\cos2b$:\n\n\\[\\cos2b=\\frac{\\sqrt5}{3}\\quad\\Longrightarrow\\quad b=\\frac12\\arccos\\!\\left(\\frac{\\sqrt5}{3}\\right).\\]\n\nHere $0\\lt 2b\\lt \\pi/2$ since both coordinates are positive, so the principal arccos value is the required one.\n\n\\[\\boxed{a=\\sqrt5,\\qquad b=\\frac12\\arccos\\!\\left(\\frac{\\sqrt5}{3}\\right)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q09","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":9,"marks":11,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities","07_TrigEquations","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","06_TrigIdentities","07_TrigEquations","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values","Trig Equations & R-Form","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q09_M11_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2025_MayJune_Q09_M11_10_DifferentiationTechniques.png","finalAnswer":"(a) $y_A=\\frac\\pi4,\\qquad y_B=\\frac{7\\pi}{12}$\n(b) $\\frac1{4-9x^2}$, $p=4,\\ q=9$\n(c) $x_D=\\frac{2\\pi}{9}$","steps":[{"title":"Part (a)","body":"On the $y$ axis, $x=0$, so $\\sin(3y+\\pi/4)=0$. Since $\\pi/12\\lt y\\lt 3\\pi/4$, we have $\\pi/2\\lt 3y+\\pi/4\\lt 5\\pi/2$. Therefore the possible angles are $\\pi$ and $2\\pi$, giving\n\n\\[\\boxed{y_A=\\frac\\pi4,\\qquad y_B=\\frac{7\\pi}{12}}.\\]"},{"title":"Part (b)","body":"Differentiate $x$ with respect to $y$, then take the reciprocal:\n\n\\[\\frac{dx}{dy}=2\\cos(3y+\\pi/4),\\qquad \\frac{dy}{dx}=\\frac1{2\\cos(3y+\\pi/4)}.\\]\n\nUsing $\\sin(3y+\\pi/4)=3x/2$,\n\n\\[\\left(\\frac{dy}{dx}\\right)^2 =\\frac1{4(1-\\sin^2(3y+\\pi/4))} =\\boxed{\\frac1{4-9x^2}}.\\]\n\nThus $\\boxed{p=4,\\ q=9}$. The derivative formula applies where the tangent is not vertical."},{"title":"Part (c)","body":"At $x=0$, part (b) gives $|dy/dx|=1/2$. The sketch shows a negative tangent gradient at $A$ and a positive one at $B$. The normal at $A$ therefore has gradient $2$, while the tangent at $B$ has gradient $1/2$:\n\n\\[y=2x+\\frac\\pi4,\\qquad y=\\frac{x}{2}+\\frac{7\\pi}{12}.\\]\n\nAt their intersection,\n\n\\[\\frac32x=\\frac{7\\pi}{12}-\\frac\\pi4=\\frac\\pi3 \\quad\\Longrightarrow\\quad\\boxed{x_D=\\frac{2\\pi}{9}}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q02","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":2,"marks":6,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["10_DifferentiationTechniques","01_RationalAlgebra"],"topicNames":["Differentiation Techniques","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q02_M06_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2026_Jan_Q02_M06_10_DifferentiationTechniques.png","finalAnswer":"(i) $x(2\\ln(2x)+1)$\n(ii) $a=4,\\ b=-1$","steps":[{"title":"Part (i)","body":"Use the product rule and $\\frac{d}{dx}\\ln(2x)=1/x$:\n\n\\[\\frac{dy}{dx}=2x\\ln(2x)+x^2\\frac1x =2x\\ln(2x)+x=x\\bigl(2\\ln(2x)+1\\bigr).\\]"},{"title":"Part (ii)","body":"Write $f(x)=e^{2x}(4x+3)^{-2}$. Product and chain rules give\n\n\\[f'(x)=2e^{2x}(4x+3)^{-2}-8e^{2x}(4x+3)^{-3}.\\]\n\nFactoring out $2e^{2x}(4x+3)^{-3}$,\n\n\\[f'(x)=\\frac{2e^{2x}\\bigl((4x+3)-4\\bigr)}{(4x+3)^3} =\\frac{2e^{2x}(4x-1)}{(4x+3)^3}.\\]\n\nThus $a=4$ and $b=-1$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q08","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":8,"marks":4,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["06_TrigIdentities","08_ExponentialsLogs"],"secondaryTopicNames":["Trig Identities & Exact Values","Exponentials & Logarithms"],"topics":["10_DifferentiationTechniques","06_TrigIdentities","08_ExponentialsLogs"],"topicNames":["Differentiation Techniques","Trig Identities & Exact Values","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q08_M04_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2026_Jan_Q08_M04_10_DifferentiationTechniques.png","finalAnswer":"(main) $a=2,\\ b=4,\\ n=2$","steps":[{"title":"Solution","body":"\\paragraph{Solution} Differentiate $x=e^{2\\tan y}$ with respect to $y$:\n\n\\[\\frac{dx}{dy}=2\\sec^2 y\\,e^{2\\tan y}=2x\\sec^2y.\\]\n\nThis is positive on the stated interval, so\n\n\\[\\frac{dy}{dx}=\\frac1{2x\\sec^2y}.\\]\n\nTaking logarithms of the original relation gives $\\ln x=2\\tan y$. Using $\\sec^2y=1+\\tan^2y$,\n\n\\[\\frac{dy}{dx}=\\frac1{2x\\left(1+\\frac{(\\ln x)^2}{4}\\right)} =\\frac2{x\\bigl(4+(\\ln x)^2\\bigr)}.\\]\n\nHence $a=2$, $b=4$ and $n=2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q03","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":3,"marks":8,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["01_RationalAlgebra","03_GraphTransformations","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Graph Transformations","Applications of Differentiation"],"topics":["10_DifferentiationTechniques","01_RationalAlgebra","03_GraphTransformations","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Rational Algebra","Graph Transformations","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q03_M08_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2026_MayJune_Q03_M08_10_DifferentiationTechniques.png","finalAnswer":"(a) $\\frac{4x^2-24x+27}{(x-3)^2}$\n(b) $(3/2,-2)$\n(c) $(5/4,-7)$","steps":[{"title":"Part (a)","body":"Using the quotient rule,\n\n\\[f'(x)=\\frac{(x-3)(8x-14)-(4x^2-14x+15)}{(x-3)^2} =\\boxed{\\frac{4x^2-24x+27}{(x-3)^2}}.\\]\n\nThus $a=4$, $b=-24$ and $c=27$."},{"title":"Part (b)","body":"A stationary point requires\n\n\\[4x^2-24x+27=(2x-3)(2x-9)=0.\\]\n\nThe roots are $3/2$ and $9/2$. Reject $9/2$ because the stated domain is $x\\lt 3$. At $x=3/2$, $f(x)=-2$, so the turning point is $\\boxed{(3/2,-2)}$. The derivative changes from positive to negative there, confirming a maximum."},{"title":"Part (c)","body":"The inside factor 2 halves the horizontal coordinate; adding 3 raises the vertical coordinate by 3. Therefore\n\n\\[(x,y)\\mapsto(x/2,y+3),\\qquad (5/2,-10)\\mapsto\\boxed{(5/4,-7)}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q06","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":6,"marks":6,"topic":"10_DifferentiationTechniques","topicName":"Differentiation Techniques","primaryTopic":"10_DifferentiationTechniques","primaryTopicName":"Differentiation Techniques","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q06_M06_10_DifferentiationTechniques.png","downloadName":"WMA13-01_Y2026_MayJune_Q06_M06_10_DifferentiationTechniques.png","finalAnswer":"$x_Q=\\frac{27}{4}$","steps":[{"title":"Solution","body":"At $y=\\pi/4$,\n\n\\[x=\\left(3\\sin\\frac\\pi2-\\frac{6(\\pi/4)}\\pi\\right)^2 =\\left(3-\\frac32\\right)^2=\\frac94.\\]\n\nDifferentiate $x$ with respect to $y$ using the chain rule:\n\n\\[\\frac{dx}{dy}=2\\left(3\\sin2y-\\frac{6y}\\pi\\right) \\left(6\\cos2y-\\frac6\\pi\\right).\\]\n\nAt $P$, $dx/dy=2(3/2)(-6/\\pi)=-18/\\pi$. Since this is nonzero, the tangent gradient is $\\dfrac{dy}{dx}=-\\dfrac\\pi{18}$, and its equation is\n\n\\[y-\\frac\\pi4=-\\frac\\pi{18}\\left(x-\\frac94\\right).\\]\n\nPut $y=0$ for its intersection with the $x$-axis:\n\n\\[x-\\frac94=\\frac{18}{4},\\qquad \\boxed{x_Q=\\frac{27}{4}}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q07","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":7,"marks":11,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["07_TrigEquations","10_DifferentiationTechniques","13_NumericalMethods"],"secondaryTopicNames":["Trig Equations & R-Form","Differentiation Techniques","Numerical Methods"],"topics":["11_ApplicationsOfDifferentiation","07_TrigEquations","10_DifferentiationTechniques","13_NumericalMethods"],"topicNames":["Applications of Differentiation","Trig Equations & R-Form","Differentiation Techniques","Numerical Methods"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q07_M11_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2020_Jan_Q07_M11_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $0.8\\lt \\alpha\\lt 0.9$\n(b)(i) $x_2=0.8327$\n(b)(ii) $x_5=0.8110$\n(c) $\\beta=\\frac{7\\pi}{18}$, $\\lambda=\\frac{19\\pi}{18}$","steps":[{"title":"Part (a)","body":"Let $f(x)=2\\cos3x-3x+4$, using radians. Then\n\n\\[\\begin{aligned} f(0.8)&=2\\cos2.4-2.4+4=0.1252125\\ldots\\gt 0,\\\\ f(0.9)&=2\\cos2.7-2.7+4=-0.5081443\\ldots\\lt 0. \\end{aligned}\\]\n\nThe function is continuous on $[0.8,0.9]$, so this change of sign shows that there is a root between the endpoints. Moreover, $f'(x)=-6\\sin3x-3\\lt 0$ on this interval, so this root is unique there. Thus the crossing shown at $P$ has $\\boxed{0.8\\lt \\alpha\\lt 0.9}$."},{"title":"Part (b)(i)","body":"Using the inverse cosine in radians,\n\n\\[x_2=\\frac13\\arccos(1.5(0.8)-2) =\\frac13\\arccos(-0.8)=0.8326971\\ldots.\\]\n\nHence $\\boxed{x_2=0.8327}$ to 4 decimal places."},{"title":"Part (b)(ii)","body":"Continue the iteration, retaining the full calculator values at each step:\n\n\\[\\begin{aligned} x_3&=\\frac13\\arccos(1.5x_2-2)=0.8067674\\ldots,\\\\ x_4&=\\frac13\\arccos(1.5x_3-2)=0.8271196\\ldots,\\\\ x_5&=\\frac13\\arccos(1.5x_4-2)=0.8110216\\ldots. \\end{aligned}\\]\n\nTherefore $\\boxed{x_5=0.8110}$ to 4 decimal places."},{"title":"Part (c)","body":"Differentiate the curve equation:\n\n\\[\\frac{dy}{dx}=-6\\sin3x-3, \\qquad \\frac{d^2y}{dx^2}=-18\\cos3x.\\]\n\nAt a stationary point,\n\n\\[-6\\sin3x-3=0 \\quad\\Longrightarrow\\quad \\sin3x=-\\frac12.\\]\n\nFor $x\\gt 0$, the stationary points therefore belong to the two families\n\n\\[3x=\\frac{7\\pi}{6}+2n\\pi \\quad\\text{or}\\quad 3x=\\frac{11\\pi}{6}+2n\\pi, \\qquad n=0,1,2,\\ldots.\\]\n\nIn the first family, $\\cos3x=-\\frac{\\sqrt3}{2}$, giving $y”=9\\sqrt3\\gt 0$, so these are local minima. In the second family, $\\cos3x=\\frac{\\sqrt3}{2}$ and $y”=-9\\sqrt3\\lt 0$, so these are local maxima and are excluded. Thus all positive minimum coordinates are\n\n\\[x=\\frac{7\\pi}{18}+\\frac{2n\\pi}{3},\\qquad n=0,1,2,\\ldots.\\]\n\nThe two smallest are obtained with $n=0$ and $n=1$:\n\n\\[\\boxed{\\beta=\\frac{7\\pi}{18}}, \\qquad \\boxed{\\lambda=\\frac{19\\pi}{18}}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q09","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":9,"marks":14,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","12_Integration"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Integration"],"topics":["11_ApplicationsOfDifferentiation","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","12_Integration"],"topicNames":["Applications of Differentiation","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q09_M14_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2020_Oct_Q09_M14_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $P=2,\\qquad Q=5$\n(b) $y=\\frac{11}{4}x-2$\n(c) $\\operatorname{Area}(R)=\\frac{20}{3}-5\\ln2$","steps":[{"title":"Part (a)","body":"Factor the denominator as $(x-4)(x+3)$ and multiply the proposed identity through by it:\n\n\\[x^4-x^3-10x^2+3x-9=(x^2+P)(x^2-x-12)+Q(x+3).\\]\n\nThe right side expands to $x^4-x^3+(P-12)x^2+(Q-P)x+3Q-12P$. Comparing coefficients gives $P-12=-10$, so $P=2$, and $Q-P=3$, so $Q=5$. The constant check is $3(5)-12(2)=-9$, as required. The identity holds where the original fraction is defined: the stated $x\\gt -3$ still excludes $x=4$.\n\n\\[\\boxed{P=2,\\qquad Q=5}\\]"},{"title":"Part (b)","body":"From (a), $g(x)=x^2+2+5/(x-4)$ on the curve domain. Thus $g'(x)=2x-5/(x-4)^2$. At $x=2$, $g(2)=4+2-5/2=7/2$ and $g'(2)=4-5/4=11/4$. The tangent through $(2,7/2)$ is\n\n\\[y-\\frac72=\\frac{11}{4}(x-2) \\quad\\Longrightarrow\\quad y=\\frac{11}{4}x-2.\\]\n\n\\[\\boxed{y=\\frac{11}{4}x-2}\\]"},{"title":"Part (c)","body":"The source shading is above the x-axis from $x=0$ to $x=2$, so integrate g over those bounds.\n\n\\[\\operatorname{Area}(R)=\\int_0^2\\left(x^2+2+\\frac5{x-4}\\right)\\,dx =\\left[\\frac{x^3}{3}+2x+5\\ln|x-4|\\right]_0^2.\\]\n\nThe absolute value is essential because $x-4\\lt 0$ throughout this interval. Evaluating gives\n\n\\[\\frac83+4+5\\ln2-5\\ln4=\\frac{20}{3}-5\\ln2.\\]\n\nThus $a=20/3$ and $b=-5$ in the requested form.\n\n\\[\\boxed{\\operatorname{Area}(R)=\\frac{20}{3}-5\\ln2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q01","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":1,"marks":4,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["10_DifferentiationTechniques"],"secondaryTopicNames":["Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q01_M04_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2022_Jan_Q01_M04_11_ApplicationsOfDifferentiation.png","finalAnswer":"(main) $x=-\\frac{17}{6}$","steps":[{"title":"Part (main)","body":"Apply the product rule:\n\n\\[y'=2e^{3x}+3(2x+5)e^{3x}=e^{3x}(6x+17).\\]\n\nAt a stationary point, $y'=0$. Since $e^{3x}\\gt 0$ for every real x, $6x+17=0$, which determines the unique stationary x coordinate.\n\n\\[\\boxed{x=-\\frac{17}{6}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q05","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":5,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_RationalAlgebra","10_DifferentiationTechniques","13_NumericalMethods"],"secondaryTopicNames":["Rational Algebra","Differentiation Techniques","Numerical Methods"],"topics":["11_ApplicationsOfDifferentiation","01_RationalAlgebra","10_DifferentiationTechniques","13_NumericalMethods"],"topicNames":["Applications of Differentiation","Rational Algebra","Differentiation Techniques","Numerical Methods"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q05_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2022_Jan_Q05_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $-1.25\\lt x_P\\lt -1.2$\n(b) $\\text{(i) }x_2=6.3637,\\qquad\\text{(ii) }x_Q=6.4142$\n(c) $x_M=\\frac{-3+\\sqrt{105}}4$","steps":[{"title":"Part (a)","body":"Let $F(x)=6\\ln(2x+3)-x^2/2+4$. Then $F(-1.25)=-0.94013308\\ldots$ and $F(-1.2)=0.21504626\\ldots$. The log argument is positive on this interval, so F is continuous there. The change of sign proves a zero between these endpoints, giving the stated bracket for P.\n\n\\[\\boxed{-1.25\\lt x_P\\lt -1.2}\\]"},{"title":"Part (b)","body":"Apply the given recurrence with $x_1=6$:\n\n\\[x_2=\\sqrt{12\\ln15+8}=6.363694085\\ldots.\\]\n\nContinuing without rounding the internal values,\n\n\\[x_3=6.408185698\\ldots,\\quad x_4=6.413466053\\ldots,\\quad x_5=6.414090476\\ldots,\\quad x_6=6.414164285\\ldots,\\quad x_7=6.414173009\\ldots.\\]\n\nFurther iteration settles at $6.41417418\\ldots$. The positive square-root branch corresponds to Q.\n\n\\[\\boxed{\\text{(i) }x_2=6.3637,\\qquad\\text{(ii) }x_Q=6.4142}\\]"},{"title":"Part (c)","body":"Differentiate: $F'(x)=12/(2x+3)-x$. For a stationary point, $12=x(2x+3)$, or $2x^2+3x-12=0$. The quadratic formula gives $x=(-3\\pm\\sqrt{105})/4$. The negative choice is less than $-3/2$ and outside the original domain. Also $F”(x)=-24/(2x+3)^2-1\\lt 0$, confirming the admissible point is a maximum.\n\n\\[\\boxed{x_M=\\frac{-3+\\sqrt{105}}4}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q01","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":1,"marks":6,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["10_DifferentiationTechniques"],"secondaryTopicNames":["Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q01_M06_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2022_MayJune_Q01_M06_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $\\frac{dy}{dx}=18(3x-2)^5$\n(b) $3x-54y+53=0$","steps":[{"title":"Part (a)","body":"Differentiate the sixth power and multiply by the derivative of $3x-2$: $dy/dx=6(3x-2)^5\\cdot3$.\n\n\\[\\boxed{\\frac{dy}{dx}=18(3x-2)^5}\\]"},{"title":"Part (b)","body":"At $P=(1/3,1)$, the tangent gradient is $18(-1)^5=-18$. The normal gradient is $-1/(-18)=1/18$. Thus\n\n\\[y-1=\\frac1{18}(x-1/3)\\ \\Longrightarrow\\ 54y-54=3x-1.\\]\n\nRearranging with integer coefficients gives the required equation.\n\n\\[\\boxed{3x-54y+53=0}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q06","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":6,"marks":10,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_RationalAlgebra","02_Functions","03_GraphTransformations","10_DifferentiationTechniques"],"secondaryTopicNames":["Rational Algebra","Functions, Composition & Inverses","Graph Transformations","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","01_RationalAlgebra","02_Functions","03_GraphTransformations","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Rational Algebra","Functions, Composition & Inverses","Graph Transformations","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q06_M10_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2022_MayJune_Q06_M10_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $k=10$\n(b) $x=-2,\\quad\\frac15$\n(c) $P=(-2,10)$\n(d) $-56\\le g(x)\\le24$","steps":[{"title":"Part (a)","body":"Use product and chain rules:\n\n\\[f'(x)=10x(4x+9)^{1/2}+10(x^2-2)(4x+9)^{-1/2}.\\]\n\nWith a common denominator,\n\n\\[f'(x)=\\frac{10x(4x+9)+10(x^2-2)}{\\sqrt{4x+9}} =\\frac{10(5x^2+9x-2)}{\\sqrt{4x+9}}.\\]\n\nThis derivative formula applies for $x\\gt -9/4$; the endpoint derivative is not finite.\n\n\\[\\boxed{k=10}\\]"},{"title":"Part (b)","body":"The denominator is positive in the derivative domain. Thus $5x^2+9x-2=(5x-1)(x+2)=0$.\n\n\\[\\boxed{x=-2,\\quad\\frac15}\\]"},{"title":"Part (c)","body":"The derivative changes from positive to negative at $x=-2$, so this is the local maximum P. Substitute into f: $f(-2)=5(4-2)\\sqrt{-8+9}=10$.\n\n\\[\\boxed{P=(-2,10)}\\]"},{"title":"Part (d)","body":"On $[-9/4,0]$, f rises from $f(-9/4)=0$ to $f(-2)=10$, then decreases to $f(0)=-30$. The other stationary point $1/5$ is outside this restricted interval. Thus the minimum and maximum of f on it are $-30$ and 10. Applying the positive vertical transformation $g=2f+4$ gives endpoints $2(-30)+4=-56$ and $2(10)+4=24$, both attained.\n\n\\[\\boxed{-56\\le g(x)\\le24}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q03","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":3,"marks":7,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["02_Functions","10_DifferentiationTechniques"],"secondaryTopicNames":["Functions, Composition & Inverses","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","02_Functions","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Functions, Composition & Inverses","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q03_M07_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2022_Oct_Q03_M07_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $A=\\left(\\frac43,\\frac{4e^4}{9}\\right)$\n(b) $0\\lt k\\le\\frac{4e^4}{9}$","steps":[{"title":"Part (a)","body":"By the product rule,\n\n\\[f'(x)=2(x-2)e^{3x}+3(x-2)^2e^{3x} =e^{3x}(x-2)(3x-4).\\]\n\nSince the exponential is positive, stationary points have $x=2$ or $x=4/3$. The sign of $f'$ changes from positive to negative at $4/3$, so this is the maximum A.\n\n\\[f(4/3)=(-2/3)^2e^4=\\frac49e^4.\\]\n\n\\[\\boxed{A=\\left(\\frac43,\\frac{4e^4}{9}\\right)}\\]"},{"title":"Part (b)","body":"The curve is nonnegative and has just one zero, $x=2$; hence $k=0$ is excluded. It tends to 0 from above as $x\\to-\\infty$, rises to $4e^4/9$, falls to 0, then rises without bound. For $0\\lt k\\lt 4e^4/9$ there are three intersections. At the maximum level there are two distinct intersections, including A. For a larger positive k there is only one.\n\n\\[\\boxed{0\\lt k\\le\\frac{4e^4}{9}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q07","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":7,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["06_TrigIdentities","10_DifferentiationTechniques"],"secondaryTopicNames":["Trig Identities & Exact Values","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","06_TrigIdentities","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Trig Identities & Exact Values","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q07_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2023_Jan_Q07_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $\\frac{dy}{dx}=\\frac3{x^2+9},\\qquad a=3,\\quad b=9$\n(b) $x_Q=\\sqrt3-\\frac{4\\pi}{3}$","steps":[{"title":"Part (a)","body":"Put $u=y-\\pi/6$. Since $x=3\\tan u$,\n\n\\[\\frac{dx}{dy}=3\\sec^2u=3(1+\\tan^2u) =3\\left(1+\\frac{x^2}{9}\\right)=\\frac{x^2+9}{3}.\\]\n\nThis is positive for all real $x$, so we may take the reciprocal: $dy/dx=3/(x^2+9)$. Thus the required integers are $a=3$, $b=9$.\n\n\\[\\boxed{\\frac{dy}{dx}=\\frac3{x^2+9},\\qquad a=3,\\quad b=9}\\]"},{"title":"Part (b)","body":"At $y=\\pi/3$, $x=3\\tan(\\pi/3-\\pi/6)=3\\tan(\\pi/6)=\\sqrt3$. The tangent gradient is $3/((\\sqrt3)^2+9)=1/4$. Its point-gradient equation is\n\n\\[y-\\frac\\pi3=\\frac14(x-\\sqrt3).\\]\n\nAt its x-axis crossing $y=0$, $-4\\pi/3=x-\\sqrt3$.\n\n\\[\\boxed{x_Q=\\sqrt3-\\frac{4\\pi}{3}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q08","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":8,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_RationalAlgebra","03_GraphTransformations","10_DifferentiationTechniques"],"secondaryTopicNames":["Rational Algebra","Graph Transformations","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","01_RationalAlgebra","03_GraphTransformations","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Rational Algebra","Graph Transformations","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q08_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2023_MayJune_Q08_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $A=2$\n(b) $\\left(-\\frac12,0\\right),\\quad\\left(\\frac14,\\frac{27}{8e}\\right)$\n(c) $\\left(\\frac94,\\frac{27}{e}\\right)$","steps":[{"title":"Part (a)","body":"The product rule gives\n\n\\[f'(x)=6(2x+1)^2e^{-4x}-4(2x+1)^3e^{-4x} =(2x+1)^2e^{-4x}[6-4(2x+1)] =2(2x+1)^2(1-4x)e^{-4x}.\\]\n\nComparison with the stated form gives $A=2$.\n\n\\[\\boxed{A=2}\\]"},{"title":"Part (b)","body":"Since $e^{-4x}\\gt 0$, $f'(x)=0$ means $2x+1=0$ or $1-4x=0$. Thus $x=-1/2$ or $x=1/4$. Substitution gives $f(-1/2)=0$ and $f(1/4)=(3/2)^3e^{-1}=27/(8e)$.\n\n\\[\\boxed{\\left(-\\frac12,0\\right),\\quad\\left(\\frac14,\\frac{27}{8e}\\right)}\\]"},{"title":"Part (c)","body":"The derivative changes from positive to negative at $x=1/4$, so this is the maximum; at $x=-1/2$ it does not change sign. The transformation $g(x)=8f(x-2)$ sends $(x,y)$ to $(x+2,8y)$. Hence the maximum stationary point is $(1/4+2,8\\cdot27/(8e))=(9/4,27/e)$.\n\n\\[\\boxed{\\left(\\frac94,\\frac{27}{e}\\right)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q05","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":5,"marks":7,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["02_Functions","08_ExponentialsLogs","10_DifferentiationTechniques"],"secondaryTopicNames":["Functions, Composition & Inverses","Exponentials & Logarithms","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","02_Functions","08_ExponentialsLogs","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Functions, Composition & Inverses","Exponentials & Logarithms","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q05_M07_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2023_Oct_Q05_M07_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $A=2,\\qquad B=1$\n(b) $x=0,\\quad x=-\\sqrt{e-k},\\quad x=\\sqrt{e-k}$\n(c) $\\text{Upper limit }e$","steps":[{"title":"Part (a)","body":"Set $u=x^2+k\\gt 0$. Applying the quotient and chain rules,\n\n\\[\\frac{dy}{dx}=\\frac{(2x/u)u-2x\\ln u}{u^2} =\\frac{2x(1-\\ln(x^2+k))}{(x^2+k)^2}.\\]\n\nComparing with the required form identifies both constants.\n\n\\[\\boxed{A=2,\\qquad B=1}\\]"},{"title":"Part (b)","body":"The denominator is positive, so stationary points satisfy\n\n\\[x=0\\quad\\text{or}\\quad \\ln(x^2+k)=1 \\quad\\Longrightarrow\\quad x=0\\quad\\text{or}\\quad x=\\pm\\sqrt{e-k}.\\]\n\nThere are three distinct real stationary points precisely when $e-k\\gt 0$. In that case the factor $1-\\ln(x^2+k)$ is positive between the outer roots and negative outside them; $2x$ changes sign at zero. Thus the derivative changes sign at all three points, so all are turning points. Together with $k\\gt 0$, the three coordinates below are real and distinct; the restriction is $0\\lt k\\lt e$.\n\n\\[\\boxed{x=0,\\quad x=-\\sqrt{e-k},\\quad x=\\sqrt{e-k}}\\]"},{"title":"Part (c)","body":"At $k=e$, the two outer stationary points merge with $x=0$, so there are no longer three distinct turning points. Values of $k$ can approach $e$ from below, but cannot equal it under this condition.\n\n\\[\\boxed{\\text{Upper limit }e}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q06","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":6,"marks":7,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q06_M07_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2024_Jan_Q06_M07_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $R=\\left(\\frac{3\\pi}{2},0\\right)$\n(b) $3\\sin^2x+\\sin x-3=0,\\quad a=3,\\ b=1,\\ c=-3$\n(c) $x_Q=2.131$","steps":[{"title":"Part (a)","body":"Since $2e^{3\\sin x}\\gt 0$, zeros occur when $\\cos x=0$. The labelled point R is the right-hand crossing, at $x=3\\pi/2$.\n\n\\[\\boxed{R=\\left(\\frac{3\\pi}{2},0\\right)}\\]"},{"title":"Part (b)","body":"For $f(x)=2e^{3\\sin x}\\cos x$, the product and chain rules give\n\n\\[f'(x)=2\\left(3e^{3\\sin x}\\cos^2x-e^{3\\sin x}\\sin x\\right) =2e^{3\\sin x}(3\\cos^2x-\\sin x).\\]\n\nAt a turning point the derivative is zero. The exponential factor is nonzero, so $3\\cos^2x-\\sin x=0$. Substitute $\\cos^2x=1-\\sin^2x$ and rearrange: $3-3\\sin^2x-\\sin x=0$.\n\n\\[\\boxed{3\\sin^2x+\\sin x-3=0,\\quad a=3,\\ b=1,\\ c=-3}\\]"},{"title":"Part (c)","body":"Solving $3s^2+s-3=0$ for $s=\\sin x$ gives\n\n\\[s=\\frac{-1\\pm\\sqrt{37}}6.\\]\n\nThe negative root is less than $-1$, so it is impossible for a real sine. Let $\\beta=\\arcsin((\\sqrt{37}-1)/6)$ in the first quadrant. The labelled minimum Q lies in the second quadrant, hence $x_Q=\\pi-\\beta=2.131037293\\ldots$.\n\n\\[\\boxed{x_Q=2.131}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q07","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":7,"marks":12,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","12_Integration"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Integration"],"topics":["11_ApplicationsOfDifferentiation","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques","12_Integration"],"topicNames":["Applications of Differentiation","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q07_M12_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2024_Jan_Q07_M12_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $\\frac{dy}{dx}=-\\frac{16}{3(3x-k)^2}$\n(b) $k=\\frac73\\ \\text{or}\\ \\frac{11}{3}$\n(c) $x-12y+31=0$\n(d) $\\frac{16}{27}\\ln10,\\quad\\lambda=\\frac{16}{27}$","steps":[{"title":"Part (a)","body":"Write $y=(16/9)(3x-k)^{-1}$. The chain rule gives\n\n\\[\\frac{dy}{dx}=\\frac{16}{9}(-1)(3x-k)^{-2}\\cdot3.\\]\n\n\\[\\boxed{\\frac{dy}{dx}=-\\frac{16}{3(3x-k)^2}}\\]"},{"title":"Part (b)","body":"At $x=1$, the given gradient yields\n\n\\[-\\frac{16}{3(3-k)^2}=-12 \\quad\\Longrightarrow\\quad(3-k)^2=\\frac49.\\]\n\nHence $3-k=\\pm2/3$. Both resulting k-values are positive and different from 3.\n\n\\[\\boxed{k=\\frac73\\ \\text{or}\\ \\frac{11}{3}}\\]"},{"title":"Part (c)","body":"Since $k\\lt 3$, use $k=7/3$. At $x=1$, $y=16/[9(3-7/3)]=8/3$. The tangent gradient is $-12$, so the normal gradient is $1/12$:\n\n\\[y-\\frac83=\\frac1{12}(x-1),\\qquad12y-32=x-1.\\]\n\n\\[\\boxed{x-12y+31=0}\\]"},{"title":"Part (d)","body":"With $k=7/3$, the denominator does not vanish on $[1,3]$. Using the reciprocal-linear antiderivative,\n\n\\[\\int_1^3\\frac{16}{9(3x-7/3)}\\,dx =\\left[\\frac{16}{27}\\ln|3x-7/3|\\right]_1^3 =\\frac{16}{27}\\left(\\ln\\frac{20}{3}-\\ln\\frac23\\right) =\\frac{16}{27}\\ln\\left(\\frac{20/3}{2/3}\\right).\\]\n\n\\[\\boxed{\\frac{16}{27}\\ln10,\\quad\\lambda=\\frac{16}{27}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q06","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":6,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["10_DifferentiationTechniques","12_Integration"],"secondaryTopicNames":["Differentiation Techniques","Integration"],"topics":["11_ApplicationsOfDifferentiation","10_DifferentiationTechniques","12_Integration"],"topicNames":["Applications of Differentiation","Differentiation Techniques","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q06_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2024_MayJune_Q06_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $5x+2y-50=0$\n(b) $\\operatorname{Area}(R)=\\frac{155}{6}$","steps":[{"title":"Part (a)","body":"For $y=(4x-7)^{1/2}$,\n\n\\[\\frac{dy}{dx}=\\frac12(4x-7)^{-1/2}\\cdot4=\\frac2{\\sqrt{4x-7}}.\\]\n\nAt $P=(8,5)$, the tangent gradient is $2/5$, so the normal gradient is $-5/2$. The point-gradient equation is\n\n\\[y-5=-\\frac52(x-8),\\qquad 2y-10=-5x+40.\\]\n\n\\[\\boxed{5x+2y-50=0}\\]"},{"title":"Part (b)","body":"The curve meets the $x$-axis at $x=7/4$. The normal meets it at $x=10$. Split the shaded region at $P$, into a curve area from $7/4$ to 8 and a triangle from 8 to 10:\n\n\\[\\int_{7/4}^8\\sqrt{4x-7}\\,dx =\\left[\\frac{(4x-7)^{3/2}}6\\right]_{7/4}^8=\\frac{125}{6}.\\]\n\nThe triangle has area $\\frac12(10-8)\\cdot5=5$. Hence the total area is $125/6+5$.\n\n\\[\\boxed{\\operatorname{Area}(R)=\\frac{155}{6}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q09","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":9,"marks":10,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["05_TrigFunctions","06_TrigIdentities","10_DifferentiationTechniques"],"secondaryTopicNames":["Trigonometric Functions & Graphs","Trig Identities & Exact Values","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","05_TrigFunctions","06_TrigIdentities","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Trigonometric Functions & Graphs","Trig Identities & Exact Values","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q09_M10_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2024_MayJune_Q09_M10_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $k=2$\n(b) $\\frac{dx}{dy}=8\\sin y\\cos y,\\qquad\\frac{dy}{dx}=\\frac1{2\\sqrt{x+1}\\sqrt{3-x}}$\n(c) $\\operatorname{Area}(OPN)=\\frac13\\pi+\\frac{\\sqrt3}{108}\\pi^2$","steps":[{"title":"Part (a)","body":"At $y=\\pi/3$, $x=4(\\sqrt3/2)^2-1=3-1=2$.\n\n\\[\\boxed{k=2}\\]"},{"title":"Part (b)","body":"(i) Differentiating with respect to $y$ gives\n\n\\[\\frac{dx}{dy}=8\\sin y\\cos y.\\]\n\n(ii) For $0\\lt y\\lt \\pi/2$, both sine and cosine are positive, and $-1\\lt x\\lt 3$. From $x+1=4\\sin^2y$,\n\n\\[\\sin y=\\frac{\\sqrt{x+1}}2,\\qquad \\cos y=\\sqrt{1-\\frac{x+1}{4}}=\\frac{\\sqrt{3-x}}2.\\]\n\nConsequently $dx/dy=2\\sqrt{x+1}\\sqrt{3-x}$. Taking the reciprocal proves the required formula on $-1\\lt x\\lt 3$. At $x=-1$ and $x=3$ the denominator is zero: these are endpoint vertical tangents, not finite derivatives.\n\n\\[\\boxed{\\frac{dx}{dy}=8\\sin y\\cos y,\\qquad\\frac{dy}{dx}=\\frac1{2\\sqrt{x+1}\\sqrt{3-x}}}\\]"},{"title":"Part (c)","body":"At $P=(2,\\pi/3)$ the tangent gradient is $1/(2\\sqrt3)$, so the normal gradient is $-2\\sqrt3$. Thus the normal is $y-\\pi/3=-2\\sqrt3(x-2)$. Setting $y=0$ gives $N=(2+\\pi/(6\\sqrt3),0)$. Triangle OPN has horizontal base $ON=2+\\pi/(6\\sqrt3)$ and perpendicular height $\\pi/3$:\n\n\\[\\operatorname{Area}(OPN)=\\frac12\\left(2+\\frac\\pi{6\\sqrt3}\\right)\\frac\\pi3 =\\frac\\pi3+\\frac{\\pi^2}{36\\sqrt3}.\\]\n\n\\[\\boxed{\\operatorname{Area}(OPN)=\\frac13\\pi+\\frac{\\sqrt3}{108}\\pi^2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q02","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":2,"marks":5,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["10_DifferentiationTechniques"],"secondaryTopicNames":["Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q02_M05_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2024_Oct_Q02_M05_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $\\frac{dy}{dx}=\\frac1{4y+5}$\n(b) $P=\\left(-\\frac{73}{8},-\\frac54\\right)$","steps":[{"title":"Part (a)","body":"Differentiate $x=2y^2+5y-6$ with respect to $y$:\n\n\\[\\frac{dx}{dy}=4y+5,\\qquad \\frac{dy}{dx}=\\frac{1}{4y+5},\\quad y\\ne-\\frac54.\\]\n\n\\[\\boxed{\\frac{dy}{dx}=\\frac1{4y+5}}\\]"},{"title":"Part (b)","body":"A tangent parallel to the $y$-axis is vertical, so use $dx/dy=0$:\n\n\\[4y+5=0\\quad\\Longrightarrow\\quad y=-\\frac54.\\]\n\nSubstituting into the curve gives\n\n\\[x=2\\left(-\\frac54\\right)^2+5\\left(-\\frac54\\right)-6 =\\frac{25}{8}-\\frac{25}{4}-6=-\\frac{73}{8}.\\]\n\n\\[\\boxed{P=\\left(-\\frac{73}{8},-\\frac54\\right)}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q03","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":3,"marks":6,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_RationalAlgebra","10_DifferentiationTechniques"],"secondaryTopicNames":["Rational Algebra","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","01_RationalAlgebra","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Rational Algebra","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q03_M06_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2025_Jan_Q03_M06_11_ApplicationsOfDifferentiation.png","finalAnswer":"(main) $-3\\lt x\\lt \\frac52$","steps":[{"title":"Part (main)","body":"Apply the quotient rule, retaining the restriction $x\\ne-3$:\n\n\\[\\frac{dy}{dx}=\\frac{4(x+3)^2-(4x+1)2(x+3)}{(x+3)^4} =\\frac{(x+3)[4(x+3)-2(4x+1)]}{(x+3)^4} =\\frac{10-4x}{(x+3)^3}.\\]\n\nThe numerator vanishes at $10-4x=0$, so $x=5/2$; the denominator changes sign at the excluded value $x=-3$. For $x\\lt -3$, the numerator is positive and denominator negative, so $y'\\lt 0$. For $-3\\lt x\\lt 5/2$, both are positive, so $y'\\gt 0$. For $x\\gt 5/2$, the numerator is negative and denominator positive, so $y'\\lt 0$. Thus the positive-gradient interval is as follows.\n\n\\[\\boxed{-3\\lt x\\lt \\frac52}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q09","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":9,"marks":8,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["02_Functions","03_GraphTransformations","08_ExponentialsLogs","10_DifferentiationTechniques"],"secondaryTopicNames":["Functions, Composition & Inverses","Graph Transformations","Exponentials & Logarithms","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","02_Functions","03_GraphTransformations","08_ExponentialsLogs","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Functions, Composition & Inverses","Graph Transformations","Exponentials & Logarithms","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q09_M08_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2025_Jan_Q09_M08_11_ApplicationsOfDifferentiation.png","finalAnswer":"(a) $x_P=\\frac14$\n(b) $Q=\\left(\\frac1{4e^2},-\\frac6e\\right)$\n(c) $g(x)\\le\\frac{12}{e}$","steps":[{"title":"Part (a)","body":"Since $x\\gt 0$, $6\\sqrt{x}$ is positive. Therefore $f(x)=0$ requires $\\ln(4x)=0$, so $4x=1$ and $x=1/4$.\n\n\\[\\boxed{x_P=\\frac14}\\]"},{"title":"Part (b)","body":"Apply the product and chain rules:\n\n\\[f'(x)=\\frac3{\\sqrt{x}}\\ln(4x)+6\\sqrt{x}\\frac1x =\\frac3{\\sqrt{x}}[\\ln(4x)+2].\\]\n\nAt $Q$, set $f'(x)=0$. Since $3/\\sqrt{x}\\gt 0$,\n\n\\[\\ln(4x)+2=0\\quad\\Longrightarrow\\quad4x=e^{-2} \\quad\\Longrightarrow\\quad x=\\frac1{4e^2}.\\]\n\nThen $\\sqrt{x}=1/(2e)$ and $\\ln(4x)=-2$, giving $f(x)=6(1/(2e))(-2)=-6/e$.\n\n\\[\\boxed{Q=\\left(\\frac1{4e^2},-\\frac6e\\right)}\\]"},{"title":"Part (c)","body":"The factor $3/\\sqrt{x}$ is positive and $\\ln(4x)+2$ increases through zero at $Q$, so $f'$ changes from negative to positive: $Q$ is the global minimum. As $x\\to\\infty$, $f(x)\\to\\infty$, hence the range of $f$ is $[-6/e,\\infty)$. Multiplication by $-2$ reverses the inequality and includes the maximum $12/e$.\n\n\\[\\boxed{g(x)\\le\\frac{12}{e}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q07","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":7,"marks":7,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_RationalAlgebra","04_Modulus","10_DifferentiationTechniques"],"secondaryTopicNames":["Rational Algebra","Modulus","Differentiation Techniques"],"topics":["11_ApplicationsOfDifferentiation","01_RationalAlgebra","04_Modulus","10_DifferentiationTechniques"],"topicNames":["Applications of Differentiation","Rational Algebra","Modulus","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q07_M07_11_ApplicationsOfDifferentiation.png","downloadName":"WMA13-01_Y2025_Oct_Q07_M07_11_ApplicationsOfDifferentiation.png","finalAnswer":"(main) $(-infinity,(2-2*sqrt(2))/3) union ((2+2*sqrt(2))/3,infinity)$","steps":[{"title":"Solution","body":"\\paragraph{Solution} Put $u=x^2+(3k-2)x$, so $u'=2x+3k-2$. By the product and chain rules,\n\n\\[\\frac{dy}{dx}=2e^u+2xe^u(2x+3k-2) =2e^u\\bigl(2x^2+(3k-2)x+1\\bigr).\\]\n\nAs $2e^u\\gt 0$, stationary points satisfy\n\n\\[2x^2+(3k-2)x+1=0.\\]\n\nFor two distinct real roots, the discriminant must be positive:\n\n\\[(3k-2)^2-8\\gt 0 \\Longleftrightarrow |3k-2|\\gt 2\\sqrt2.\\]\n\nConsequently\n\n\\[k\\lt \\frac{2-2\\sqrt2}{3}\\quad\\hbox{or}\\quad k\\gt \\frac{2+2\\sqrt2}{3}.\\]\n\nFor these values the quadratic changes sign at both simple roots, so both stationary points are genuine turning points. Equality gives a repeated root with no derivative sign change and is excluded."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Jan_Q08","year":2020,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2020","qNo":8,"marks":10,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2020_Jan_Q08_M10_12_Integration.png","downloadName":"WMA13-01_Y2020_Jan_Q08_M10_12_Integration.png","finalAnswer":"(i) $2\\ln\\left(\\frac52\\right)$\n(ii) $A=2,\\qquad B=-3,\\qquad C=4$, $\\int h(x)\\,dx=x^2-3x-\\frac4{x-1}+K$","steps":[{"title":"Part (i)","body":"Since $3x-1\\gt 0$ throughout $3\\le x\\le42$, an antiderivative is\n\n\\[\\int\\frac{2}{3x-1}\\,dx=\\frac23\\ln(3x-1)+K.\\]\n\nThe factor $1/3$ compensates for the derivative of $3x-1$. Thus\n\n\\[\\begin{aligned} \\int_3^{42}\\frac{2}{3x-1}\\,dx &=\\left[\\frac23\\ln(3x-1)\\right]_3^{42}\\\\ &=\\frac23\\bigl(\\ln125-\\ln8\\bigr)\\\\ &=\\frac23\\ln\\left(\\frac{125}{8}\\right) =\\frac23\\ln\\left(\\left(\\frac52\\right)^3\\right). \\end{aligned}\\]\n\nUsing $\\ln(a^3)=3\\ln a$ for $a\\gt 0$, the exact value in simplest form is\n\n\\[\\boxed{2\\ln\\left(\\frac52\\right).}\\]"},{"title":"Part (ii)","body":"Multiply the given decomposition by $(x-1)^2$:\n\n\\[\\begin{aligned} 2x^3-7x^2+8x+1 &=(Ax+B)(x-1)^2+C\\\\ &=Ax^3+(B-2A)x^2+(A-2B)x+(B+C). \\end{aligned}\\]\n\nComparing coefficients gives\n\n\\[A=2,\\qquad B-2A=-7\\ \\Longrightarrow\\ B=-3, \\qquad B+C=1\\ \\Longrightarrow\\ C=4.\\]\n\nThe coefficient of $x$ also agrees, since $A-2B=2-2(-3)=8$. Hence\n\n\\[\\boxed{A=2,\\qquad B=-3,\\qquad C=4,} \\qquad h(x)=2x-3+4(x-1)^{-2}.\\]\n\nIntegrating each term,\n\n\\[\\begin{aligned} \\int h(x)\\,dx &=\\int\\bigl(2x-3+4(x-1)^{-2}\\bigr)\\,dx\\\\ &=x^2-3x-4(x-1)^{-1}+K. \\end{aligned}\\]\n\nTherefore, for $x\\gt 1$,\n\n\\[\\boxed{\\int h(x)\\,dx=x^2-3x-\\frac4{x-1}+K,}\\]\n\nwhere $K$ is an arbitrary constant of integration, distinct from the coefficient $C=4$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q01","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":1,"marks":3,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["12_Integration","01_RationalAlgebra"],"topicNames":["Integration","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q01_M03_12_Integration.png","downloadName":"WMA13-01_Y2021_Jan_Q01_M03_12_Integration.png","finalAnswer":"(main) $\\frac12\\ln x+\\frac5{4x^2}+C$","steps":[{"title":"Part (main)","body":"First split the fraction into powers:\n\n\\[\\frac{x^2-5}{2x^3}=\\frac12x^{-1}-\\frac52x^{-3}.\\]\n\nIntegrate term by term. Since $x\\gt 0$, use $\\ln x$ without absolute-value notation:\n\n\\[\\int\\frac{x^2-5}{2x^3}\\,dx=\\frac12\\ln x+\\frac54x^{-2}+C.\\]\n\n\\[\\boxed{\\frac12\\ln x+\\frac5{4x^2}+C}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q09","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":9,"marks":4,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["10_DifferentiationTechniques"],"secondaryTopicNames":["Differentiation Techniques"],"topics":["12_Integration","10_DifferentiationTechniques"],"topicNames":["Integration","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q09_M04_12_Integration.png","downloadName":"WMA13-01_Y2021_Jan_Q09_M04_12_Integration.png","finalAnswer":"(i) $\\frac12\\ln(3x^2-4x+5)+C$\n(ii) $-\\frac1{4(e^{2x}-1)^2}+C$","steps":[{"title":"Part (i)","body":"The denominator derivative is $6x-4=2(3x-2)$. Hence reverse the logarithmic chain rule:\n\n\\[\\int\\frac{3x-2}{3x^2-4x+5}\\,dx=\\frac12\\ln(3x^2-4x+5)+C.\\]\n\nThe log argument is always positive because $3x^2-4x+5=3(x-2/3)^2+11/3$.\n\n\\[\\boxed{\\frac12\\ln(3x^2-4x+5)+C}\\]"},{"title":"Part (ii)","body":"Put $u=e^{2x}-1$, so $du=2e^{2x}\\,dx$. Then $\\int e^{2x}(e^{2x}-1)^{-3}\\,dx=(1/2)\\int u^{-3}\\,du=-1/(4u^2)+C$. The source excludes $x=0$, where the integrand is undefined.\n\n\\[\\boxed{-\\frac1{4(e^{2x}-1)^2}+C}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q03","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":3,"marks":8,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q03_M08_12_Integration.png","downloadName":"WMA13-01_Y2021_MayJune_Q03_M08_12_Integration.png","finalAnswer":"(i) $-\\frac6{2x-1}+C$\n(ii) $A=4,\\ B=-5;\\qquad I=12+5\\ln2$","steps":[{"title":"Part (i)","body":"Write the integrand as $12(2x-1)^{-2}$. Reverse the chain rule, dividing by the inner derivative 2:\n\n\\[\\int12(2x-1)^{-2}\\,dx=-6(2x-1)^{-1}+C.\\]\n\n\\[\\boxed{-\\frac6{2x-1}+C}\\]"},{"title":"Part (ii)","body":"(a) Since $4x+3=4(x+2)-5$,\n\n\\[\\frac{4x+3}{x+2}=4-\\frac5{x+2},\\qquad A=4,\\ B=-5.\\]\n\n(b) A primitive is $4x-5\\ln|x+2|$. The absolute value is essential here: $x+2$ is negative throughout $[-8,-5]$.\n\n\\[\\int_{-8}^{-5}\\frac{4x+3}{x+2}\\,dx =(-20-5\\ln3)-(-32-5\\ln6) =12+5\\ln2.\\]\n\n\\[\\boxed{A=4,\\ B=-5;\\qquad I=12+5\\ln2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q05","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":5,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["10_DifferentiationTechniques"],"secondaryTopicNames":["Differentiation Techniques"],"topics":["12_Integration","10_DifferentiationTechniques"],"topicNames":["Integration","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q05_M06_12_Integration.png","downloadName":"WMA13-01_Y2021_Oct_Q05_M06_12_Integration.png","finalAnswer":"(i) $\\frac{48}{25}$\n(ii) $\\frac{(x^2+3)^8}{16}+C$","steps":[{"title":"Part (i)","body":"Write the integrand as $8(2x-3)^{-3}$. A primitive is $-2(2x-3)^{-2}$, because its derivative is $8(2x-3)^{-3}$. Thus\n\n\\[\\int_2^4\\frac8{(2x-3)^3}\\,dx =\\left[-\\frac2{(2x-3)^2}\\right]_2^4 =-\\frac2{25}-(-2)=\\frac{48}{25}.\\]\n\n\\[\\boxed{\\frac{48}{25}}\\]"},{"title":"Part (ii)","body":"Since $d(x^2+3)/dx=2x$, reverse the chain rule:\n\n\\[\\int x(x^2+3)^7\\,dx=\\frac12\\cdot\\frac{(x^2+3)^8}{8}+C.\\]\n\n\\[\\boxed{\\frac{(x^2+3)^8}{16}+C}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q10","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":10,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["06_TrigIdentities","07_TrigEquations"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form"],"topics":["12_Integration","06_TrigIdentities","07_TrigEquations"],"topicNames":["Integration","Trig Identities & Exact Values","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q10_M07_12_Integration.png","downloadName":"WMA13-01_Y2021_Oct_Q10_M07_12_Integration.png","finalAnswer":"(a) $p=3,\\quad q=4,\\quad r=2$\n(b) $2\\pi-\\frac{3\\sqrt3}{4}$","steps":[{"title":"Part (a)","body":"Expand and use $\\cos^22x=(1+\\cos4x)/2$:\n\n\\[(1+2\\cos2x)^2=1+4\\cos2x+4\\cos^22x =3+4\\cos2x+2\\cos4x.\\]\n\n\\[\\boxed{p=3,\\quad q=4,\\quad r=2}\\]"},{"title":"Part (b)","body":"The zeros satisfy $\\cos2x=-1/2$. The first two positive values are $x=\\pi/3$ and $x=2\\pi/3$, so $a=2\\pi/3$. The squared curve is nonnegative, so integrate directly for the total shaded area:\n\n\\[\\mathcal A=\\int_0^{2\\pi/3}(3+4\\cos2x+2\\cos4x)\\,dx =\\left[3x+2\\sin2x+\\tfrac12\\sin4x\\right]_0^{2\\pi/3}.\\]\n\nUse $\\sin(4\\pi/3)=-\\sqrt3/2$ and $\\sin(8\\pi/3)=\\sqrt3/2$ to obtain $\\mathcal A=2\\pi-\\sqrt3+\\sqrt3/4=2\\pi-3\\sqrt3/4$.\n\n\\[\\boxed{2\\pi-\\frac{3\\sqrt3}{4}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Jan_Q03","year":2022,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2022","qNo":3,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques"],"topics":["12_Integration","08_ExponentialsLogs","10_DifferentiationTechniques"],"topicNames":["Integration","Exponentials & Logarithms","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2022_Jan_Q03_M06_12_Integration.png","downloadName":"WMA13-01_Y2022_Jan_Q03_M06_12_Integration.png","finalAnswer":"(i) $\\frac{(2x-5)^8}{16}+C$\n(ii) $a=\\frac94$","steps":[{"title":"Part (i)","body":"Raise the power by one, divide by the new power and by the inner derivative 2:\n\n\\[\\int(2x-5)^7\\,dx=\\frac{(2x-5)^8}{2\\cdot8}+C.\\]\n\n\\[\\boxed{\\frac{(2x-5)^8}{16}+C}\\]"},{"title":"Part (ii)","body":"The derivative of $1+2\\cos x$ is $-2\\sin x$, so a primitive is $-2\\ln(1+2\\cos x)$. The log argument is positive throughout $0\\le x\\le\\pi/3$. Hence\n\n\\[\\int_0^{\\pi/3}\\frac{4\\sin x}{1+2\\cos x}\\,dx =[-2\\ln(1+2\\cos x)]_0^{\\pi/3} =-2\\ln2+2\\ln3=\\ln\\frac94.\\]\n\n\\[\\boxed{a=\\frac94}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q03","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":3,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q03_M06_12_Integration.png","downloadName":"WMA13-01_Y2022_MayJune_Q03_M06_12_Integration.png","finalAnswer":"(a) $\\frac32\\ln(3x^2+k)+C$\n(b) $k=9$","steps":[{"title":"Part (a)","body":"Since $d(3x^2+k)/dx=6x$, the numerator is $3/2$ times this derivative. The denominator is positive because $k\\gt 0$, so\n\n\\[\\int\\frac{9x}{3x^2+k}\\,dx=\\frac32\\ln(3x^2+k)+C.\\]\n\n\\[\\boxed{\\frac32\\ln(3x^2+k)+C}\\]"},{"title":"Part (b)","body":"Apply the limits to (a) and combine the logarithms:\n\n\\[\\frac32\\ln\\frac{75+k}{12+k}=\\ln8.\\]\n\nHence $\\ln((75+k)/(12+k))=(2/3)\\ln8=\\ln4$, so $75+k=4(12+k)$. This gives $27=3k$ and $k=9$, consistent with $k\\gt 0$.\n\n\\[\\boxed{k=9}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_Oct_Q01","year":2022,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2022","qNo":1,"marks":9,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2022_Oct_Q01_M09_12_Integration.png","downloadName":"WMA13-01_Y2022_Oct_Q01_M09_12_Integration.png","finalAnswer":"(a) $A=2,\\quad B=-6,\\quad C=3$\n(b) $4+\\ln8$","steps":[{"title":"Part (a)","body":"Clear the denominator in the proposed identity:\n\n\\[2x^3-4x-15=(Ax+B)(x^2+3x+4)+C(2x+3).\\]\n\nMatching coefficients gives $A=2$, $3A+B=0$, hence $B=-6$. Then $4A+3B+2C=-4$ gives $C=3$; the constant checks as $4B+3C=-24+9=-15$. Therefore $f(x)=2x-6+3(2x+3)/(x^2+3x+4)$.\n\n\\[\\boxed{A=2,\\quad B=-6,\\quad C=3}\\]"},{"title":"Part (b)","body":"The numerator $2x+3$ is the derivative of $x^2+3x+4$. This quadratic is $(x+3/2)^2+7/4\\gt 0$, so\n\n\\[\\int f(x)\\,dx=x^2-6x+3\\ln(x^2+3x+4)+K.\\]\n\nUsing both limits,\n\n\\[\\int_3^5f(x)\\,dx=(-5+3\\ln44)-(-9+3\\ln22) =4+3\\ln2=4+\\ln8.\\]\n\nThus $p=4$ and $q=8$ are integers, as required.\n\n\\[\\boxed{4+\\ln8}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q08","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":8,"marks":5,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["12_Integration","06_TrigIdentities"],"topicNames":["Integration","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q08_M05_12_Integration.png","downloadName":"WMA13-01_Y2023_Jan_Q08_M05_12_Integration.png","finalAnswer":"(main) $\\int(2\\cos x-\\sin x)^2\\,dx=\\frac52x+\\frac34\\sin2x+\\cos2x+K$","steps":[{"title":"Part (main)","body":"Expand the square first:\n\n\\[(2\\cos x-\\sin x)^2=4\\cos^2x-4\\sin x\\cos x+\\sin^2x.\\]\n\nUse $\\cos^2x=(1+\\cos2x)/2$, $\\sin^2x=(1-\\cos2x)/2$, and $2\\sin x\\cos x=\\sin2x$. The integrand becomes\n\n\\[\\frac52+\\frac32\\cos2x-2\\sin2x.\\]\n\nIntegrating with the angle-2 chain factors gives $5x/2+3\\sin2x/4+\\cos2x+K$.\n\n\\[\\boxed{\\int(2\\cos x-\\sin x)^2\\,dx=\\frac52x+\\frac34\\sin2x+\\cos2x+K}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_MayJune_Q02","year":2024,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2024","qNo":2,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2024_MayJune_Q02_M07_12_Integration.png","downloadName":"WMA13-01_Y2024_MayJune_Q02_M07_12_Integration.png","finalAnswer":"(a) $A=2,\\quad B=-1,\\quad C=6$\n(b) $44+6\\ln3,\\qquad \\alpha=44,\\quad\\beta=6$","steps":[{"title":"Part (a)","body":"Multiplying the proposed identity by $x-2$ gives\n\n\\[2x^2-5x+8=(Ax+B)(x-2)+C=Ax^2+(B-2A)x+C-2B.\\]\n\nThus $A=2$, $B-4=-5$ and $C-2(-1)=8$, giving $B=-1$, $C=6$. Hence $g(x)=2x-1+6/(x-2)$, for $x\\ne2$.\n\n\\[\\boxed{A=2,\\quad B=-1,\\quad C=6}\\]"},{"title":"Part (b)","body":"Since $x-2\\gt 0$ throughout $[4,8]$,\n\n\\[\\int_4^8g(x)\\,dx=\\left[x^2-x+6\\ln(x-2)\\right]_4^8 =(64-8+6\\ln6)-(16-4+6\\ln2) =44+6\\ln(6/2).\\]\n\n\\[\\boxed{44+6\\ln3,\\qquad \\alpha=44,\\quad\\beta=6}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Oct_Q09","year":2024,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2024","qNo":9,"marks":14,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"topics":["12_Integration","01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Integration","Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2024_Oct_Q09_M14_12_Integration.png","downloadName":"WMA13-01_Y2024_Oct_Q09_M14_12_Integration.png","finalAnswer":"(a) $f'(x)=\\frac{4(3x^2+3x+2)}{(2x+1)^2}$\n(b) $16y+5x=106$\n(c) $A=3,\\quad B=\\frac12,\\quad D=-\\frac52$\n(d) $\\operatorname{Area}(R)=\\frac{964}{15}-\\frac54\\ln3$","steps":[{"title":"Part (a)","body":"With $u=6x^2+4x-2$ and $v=2x+1$, the quotient rule gives\n\n\\[f'(x)=\\frac{(12x+4)(2x+1)-2(6x^2+4x-2)}{(2x+1)^2} =\\frac{12x^2+12x+8}{(2x+1)^2}.\\]\n\n\\[\\boxed{f'(x)=\\frac{4(3x^2+3x+2)}{(2x+1)^2}}\\]"},{"title":"Part (b)","body":"At $x=2$, $f'(2)=80/25=16/5$, so the normal gradient is $-5/16$. Through $P=(2,6)$,\n\n\\[y-6=-\\frac5{16}(x-2) \\quad\\Longrightarrow\\quad16y-96=-5x+10.\\]\n\n\\[\\boxed{16y+5x=106}\\]"},{"title":"Part (c)","body":"Multiplying the proposed identity by $2x+1$ gives\n\n\\[6x^2+4x-2=(Ax+B)(2x+1)+D =2Ax^2+(A+2B)x+B+D.\\]\n\nCompare coefficients: $2A=6$, $A+2B=4$, $B+D=-2$. Thus $f(x)=3x+\\frac12-\\frac{5}{2(2x+1)}$.\n\n\\[\\boxed{A=3,\\quad B=\\frac12,\\quad D=-\\frac52}\\]"},{"title":"Part (d)","body":"The curve meets the $x$-axis when $6x^2+4x-2=2(3x-1)(x+1)=0$. The root $x=-1$ is outside $x\\gt -1/2$, leaving $x=1/3$. The normal meets the axis at $x=106/5$. Split the shaded region at $P$: a curve area from $1/3$ to 2, then a triangle.\n\n\\[\\int_{1/3}^{2}f(x)\\,dx =\\left[\\frac32x^2+\\frac12x-\\frac54\\ln(2x+1)\\right]_{1/3}^{2} =7-\\frac13-\\frac54\\ln\\left(\\frac5{5/3}\\right) =\\frac{20}{3}-\\frac54\\ln3.\\]\n\nThe triangle has area $\\frac12(106/5-2)\\cdot6=288/5$. Adding gives the exact area of $R$.\n\n\\[\\boxed{\\operatorname{Area}(R)=\\frac{964}{15}-\\frac54\\ln3}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q04","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":4,"marks":9,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q04_M09_12_Integration.png","downloadName":"WMA13-01_Y2025_Jan_Q04_M09_12_Integration.png","finalAnswer":"(a)(i) $A=4,\\quad B=2,\\quad C=-13$\n(a)(ii) $D=0$\n(b) $36-13\\ln2$","steps":[{"title":"Part (a)(i)","body":"Multiply the identity by $x^2+4$:\n\n\\[4x^3+2x^2+3x+8=(Ax+B)(x^2+4)+Cx+D =Ax^3+Bx^2+(4A+C)x+4B+D.\\]\n\nComparing the cubic, quadratic and linear coefficients gives $A=4$, $B=2$ and $4A+C=3$, hence $C=3-16=-13$.\n\n\\[\\boxed{A=4,\\quad B=2,\\quad C=-13}\\]"},{"title":"Part (a)(ii)","body":"The $x^2$ coefficients give $B=2$, while the constant terms give $4B+D=8$. Substitute $B=2$: $4(2)+D=8$, so $D=0$.\n\n\\[\\boxed{D=0}\\]"},{"title":"Part (b)","body":"Using the decomposition, the integrand is $4x+2-13x/(x^2+4)$. Since the derivative of $x^2+4$ is $2x$, an antiderivative is\n\n\\[F(x)=2x^2+2x-\\frac{13}{2}\\ln(x^2+4).\\]\n\nTherefore\n\n\\[\\int_1^4\\frac{4x^3+2x^2+3x+8}{x^2+4}\\,dx =\\left[2x^2+2x-\\frac{13}{2}\\ln(x^2+4)\\right]_1^4 =40-\\frac{13}{2}\\ln20-\\left(4-\\frac{13}{2}\\ln5\\right).\\]\n\nCombine the logarithms: $36-\\frac{13}{2}\\ln4=36-13\\ln2$.\n\n\\[\\boxed{36-13\\ln2}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q05","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":5,"marks":4,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["06_TrigIdentities","10_DifferentiationTechniques"],"secondaryTopicNames":["Trig Identities & Exact Values","Differentiation Techniques"],"topics":["12_Integration","06_TrigIdentities","10_DifferentiationTechniques"],"topicNames":["Integration","Trig Identities & Exact Values","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q05_M04_12_Integration.png","downloadName":"WMA13-01_Y2025_MayJune_Q05_M04_12_Integration.png","finalAnswer":"(i) $\\frac{x}{2}-\\frac{\\sin6x}{12}+C$\n(ii) $\\frac15(x^2+4)^{5/2}+C$","steps":[{"title":"Part (i)","body":"Use $\\sin^2(3x)=(1-\\cos6x)/2$:\n\n\\[\\int\\sin^2(3x)\\,dx=\\frac12\\int(1-\\cos6x)\\,dx =\\boxed{\\frac{x}{2}-\\frac{\\sin6x}{12}+C}.\\]"},{"title":"Part (ii)","body":"The derivative of $(x^2+4)^{5/2}$ is $5x(x^2+4)^{3/2}$. Therefore\n\n\\[\\int x(x^2+4)^{3/2}\\,dx=\\boxed{\\frac15(x^2+4)^{5/2}+C}.\\]\n\nFor example, differentiating this answer gives\n\n\\[\\frac15\\cdot\\frac52(x^2+4)^{3/2}\\cdot2x=x(x^2+4)^{3/2},\\]\n\nwhich recovers the integrand. Each indefinite integral has its own arbitrary constant."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q06","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":6,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms","Differentiation Techniques"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs","10_DifferentiationTechniques"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q06_M07_12_Integration.png","downloadName":"WMA13-01_Y2025_Oct_Q06_M07_12_Integration.png","finalAnswer":"(i) $4*x/(2*x^2+5)$\n(ii) $23$","steps":[{"title":"Part (i)","body":"Using the chain rule,\n\n\\[\\frac{dy}{dx}=\\frac{1}{2x^2+5}(4x)=\\frac{4x}{2x^2+5}.\\]"},{"title":"Part (ii)","body":"Treat $k$ as a constant when integrating:\n\n\\[\\int_1^k\\frac{21x}{3x^2+k}\\,dx =\\left[\\frac72\\ln(3x^2+k)\\right]_1^k =\\frac72\\ln\\left(\\frac{3k^2+k}{k+3}\\right).\\]\n\nThe stated inequality therefore implies\n\n\\[\\ln\\left(\\frac{3k^2+k}{k+3}\\right)\\lt 2\\ln8=\\ln64.\\]\n\nSince the exponential is increasing and $k+3\\gt 0$,\n\n\\[3k^2+k\\lt 64(k+3) \\Longrightarrow k^2-21k-64\\lt 0.\\]\n\nThe roots are $(21\\pm\\sqrt{697})/2$, so the positive upper bound is $k\\lt (21+\\sqrt{697})/2=23.700378782\\ldots$. With $k\\gt 1$ an integer, the greatest possible value is $k=23$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q03","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":3,"marks":10,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["01_RationalAlgebra","08_ExponentialsLogs"],"secondaryTopicNames":["Rational Algebra","Exponentials & Logarithms"],"topics":["12_Integration","01_RationalAlgebra","08_ExponentialsLogs"],"topicNames":["Integration","Rational Algebra","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q03_M10_12_Integration.png","downloadName":"WMA13-01_Y2026_Jan_Q03_M10_12_Integration.png","finalAnswer":"(i) $\\frac{(3x+5)^8}{12}+C$\n(ii)(a) $a=4,\\ b=-3,\\ c=4$\n(ii)(b) $126+8\\ln2$","steps":[{"title":"Part (i)","body":"Increase the power to $8$ and divide by both $8$ and the inner derivative $3$:\n\n\\[\\int 2(3x+5)^7\\,dx=\\frac{(3x+5)^8}{12}+C.\\]"},{"title":"Part (ii)(a)","body":"The denominator is $x^2+x-2$. The first quotient term is $4x$. Subtracting $4x(x^2+x-2)$ leaves $-3x^2+x+14$. The next quotient term is $-3$. Subtracting $-3(x^2+x-2)$ leaves $4x+8$. Thus polynomial division gives\n\n\\[4x^3+x^2-7x+14=(4x-3)(x^2+x-2)+4x+8.\\]\n\nSince $4x+8=4(x+2)$,\n\n\\[f(x)=4x-3+\\frac{4(x+2)}{(x-1)(x+2)} =4x-3+\\frac4{x-1}.\\]\n\nHence $a=4$, $b=-3$, $c=4$."},{"title":"Part (ii)(b)","body":"For $x\\gt 1$, an antiderivative is $2x^2-3x+4\\ln(x-1)$, so\n\n\\[\\int_3^9 f(x)\\,dx =\\bigl[2x^2-3x+4\\ln(x-1)\\bigr]_3^9 =135+4\\ln8-9-4\\ln2.\\]\n\nThus the exact integral is $126+8\\ln2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q04","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":4,"marks":5,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["12_Integration","06_TrigIdentities"],"topicNames":["Integration","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q04_M05_12_Integration.png","downloadName":"WMA13-01_Y2026_MayJune_Q04_M05_12_Integration.png","finalAnswer":"$\\frac\\pi{36}+\\frac1{12}$","steps":[{"title":"Solution","body":"First expand and use the double-angle identity:\n\n\\[(\\sin3x+\\cos3x)^2=\\sin^2 3x+\\cos^2 3x+2\\sin3x\\cos3x=1+\\sin6x.\\]\n\nHence\n\n\\[\\begin{aligned} \\int_{\\pi/18}^{\\pi/12}(\\sin3x+\\cos3x)^2\\,dx &=\\left[x-\\frac16\\cos6x\\right]_{\\pi/18}^{\\pi/12}\\\\ &=\\left(\\frac\\pi{12}-\\frac16\\cos\\frac\\pi2\\right) -\\left(\\frac\\pi{18}-\\frac16\\cos\\frac\\pi3\\right)\\\\ &=\\frac\\pi{12}-\\frac\\pi{18}+\\frac1{12} =\\boxed{\\frac\\pi{36}+\\frac1{12}}. \\end{aligned}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2020_Oct_Q06","year":2020,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2020","qNo":6,"marks":9,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["03_GraphTransformations","08_ExponentialsLogs"],"secondaryTopicNames":["Graph Transformations","Exponentials & Logarithms"],"topics":["13_NumericalMethods","03_GraphTransformations","08_ExponentialsLogs"],"topicNames":["Numerical Methods","Graph Transformations","Exponentials & Logarithms"],"image":"ial/wma13/questions/WMA13-01_Y2020_Oct_Q06_M09_13_NumericalMethods.png","downloadName":"WMA13-01_Y2020_Oct_Q06_M09_13_NumericalMethods.png","finalAnswer":"(a) $x=\\ln(3e),\\qquad k=3e$\n(b) $\\alpha=1.134\\text{ to 3 d.p.}$\n(c) $x_2=-2.628388,\\qquad\\beta=-2.620330$","steps":[{"title":"Part (a)","body":"At P, $18=5e^{x-1}+3$, so $e^{x-1}=3$. Taking natural logarithms gives $x-1=\\ln3$, hence $x=1+\\ln3=\\ln e+\\ln3=\\ln(3e)$.\n\n\\[\\boxed{x=\\ln(3e),\\qquad k=3e}\\]"},{"title":"Part (b)","body":"Define $F(x)=5e^{x-1}+x^2-7$; its zeros are the intersection abscissae, and F is continuous. At the endpoints of the three-decimal rounding interval,\n\n\\[F(1.1335)=-0.0010714193\\ldots\\lt 0,\\qquad F(1.1345)=0.0069135450\\ldots\\gt 0.\\]\n\nContinuity guarantees a root between them. Moreover $F'(x)=5e^{x-1}+2x\\gt 0$ on this positive interval, so that root is unique there. It is the positive intersection $\\alpha$, and rounds to 1.134 to three decimal places.\n\n\\[\\boxed{\\alpha=1.134\\text{ to 3 d.p.}}\\]"},{"title":"Part (c)","body":"Start at $x_1=-3$ and keep full precision in $x_{n+1}=-\\sqrt{7-5e^{x_n-1}}$:\n\n\\[\\begin{array}{c|r}n&x_n\\\\\\hline 1&-3\\\\2&-2.628387681746\\\\3&-2.620535277934\\\\ 4&-2.620335527988\\\\5&-2.620330426051\\\\6&-2.620330295726\\\\7&-2.620330292397 \\end{array}\\]\n\nThe later iterates agree to six decimal places. The negative root corresponds to $\\beta$ in the figure.\n\n\\[\\boxed{x_2=-2.628388,\\qquad\\beta=-2.620330}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Jan_Q06","year":2021,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2021","qNo":6,"marks":8,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques","Applications of Differentiation"],"topics":["13_NumericalMethods","06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Numerical Methods","Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_Jan_Q06_M08_13_NumericalMethods.png","downloadName":"WMA13-01_Y2021_Jan_Q06_M08_13_NumericalMethods.png","finalAnswer":"(a) $f^{\\prime}(x)=\\cos(x/3)-\\frac{x}{3}\\sin(x/3)$\n(b) $k=3;\\quad x=3\\arctan(3/x)\\text{ on the selected branch}$\n(c) $x_2=2.628,\\qquad x_6=2.586$\n(d) $x=2.581\\text{ correct to 3 d.p.}$","steps":[{"title":"Part (a)","body":"By the product and chain rules, $f'(x)=\\cos(x/3)-(x/3)\\sin(x/3)$.\n\n\\[\\boxed{f^{\\prime}(x)=\\cos(x/3)-\\frac{x}{3}\\sin(x/3)}\\]"},{"title":"Part (b)","body":"Set $f'(x)=0$: $\\cos(x/3)=(x/3)\\sin(x/3)$. At a solution, cosine cannot vanish (that would leave a nonzero right side), so $\\tan(x/3)=3/x$. On the principal positive branch $0\\lt x/3\\lt \\pi/2$, this gives\n\n\\[x=3\\arctan(3/x),\\qquad k=3.\\]\n\nThis is the branch used by the supplied iteration for the root near 2.581. The original domain $x\\gt 0$ also admits later tangent branches: in general $x=3\\arctan(3/x)+3n\\pi$. The principal-branch rearrangement must not be interpreted as listing every positive stationary point.\n\n\\[\\boxed{k=3;\\quad x=3\\arctan(3/x)\\text{ on the selected branch}}\\]"},{"title":"Part (c)","body":"Using radians and $x_1=2.5$, the successive values are\n\n\\[\\begin{array}{c|rrrrrr}n&1&2&3&4&5&6\\\\\\hline x_n&2.5&2.628174152&2.554102174&2.596526871&2.572101407&2.586122337 \\end{array}\\]\n\nKeep full precision between steps and round the requested terms only.\n\n\\[\\boxed{x_2=2.628,\\qquad x_6=2.586}\\]"},{"title":"Part (d)","body":"Define $F(x)=\\cos(x/3)-(x/3)\\sin(x/3)$, which is continuous near 2.581. The rounding interval endpoints give\n\n\\[F(2.5805)=0.0003467157\\ldots\\gt 0,\\qquad F(2.5815)=-0.0003456897\\ldots\\lt 0.\\]\n\nBy continuity a root lies strictly between these endpoints; every number in this open interval rounds to 2.581 to three decimal places.\n\n\\[\\boxed{x=2.581\\text{ correct to 3 d.p.}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_MayJune_Q01","year":2021,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2021","qNo":1,"marks":7,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques","Applications of Differentiation"],"topics":["13_NumericalMethods","06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Numerical Methods","Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_MayJune_Q01_M07_13_NumericalMethods.png","downloadName":"WMA13-01_Y2021_MayJune_Q01_M07_13_NumericalMethods.png","finalAnswer":"(a) $x=2\\arctan(4/x)$\n(b) $x_2=2.214,\\qquad x_6=2.155$","steps":[{"title":"Part (a)","body":"Using the product and chain rules,\n\n\\[y'=2x\\cos(x/2)-\\frac{x^2}{2}\\sin(x/2).\\]\n\nAt a stationary point, divide by $x/2$, since $x\\gt 0$, to obtain $4\\cos(x/2)=x\\sin(x/2)$. The endpoint $x=\\pi$ does not satisfy this equation, so at P we have $0\\lt x\\lt \\pi$ and $\\cos(x/2)\\gt 0$. Hence $\\tan(x/2)=4/x$. The principal arctangent is valid because $0\\lt x/2\\lt \\pi/2$:\n\n\\[x=2\\arctan(4/x).\\]\n\n\\[\\boxed{x=2\\arctan(4/x)}\\]"},{"title":"Part (b)","body":"Use radian mode and retain full calculator precision between iterations:\n\n\\[\\begin{array}{c|rrrrrr}n&1&2&3&4&5&6\\\\\\hline x_n&2&2.214297436&2.130426058&2.162810067&2.150238622&2.155108774 \\end{array}\\]\n\nThus the requested second and sixth terms, not the limiting value, are as below.\n\n\\[\\boxed{x_2=2.214,\\qquad x_6=2.155}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2021_Oct_Q09","year":2021,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2021","qNo":9,"marks":9,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"topics":["13_NumericalMethods","01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Numerical Methods","Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2021_Oct_Q09_M09_13_NumericalMethods.png","downloadName":"WMA13-01_Y2021_Oct_Q09_M09_13_NumericalMethods.png","finalAnswer":"(a) $f^{\\prime}(x)=e^{-x/2}(-x^3/2+3x^2+2x-4)$\n(b) $x=-\\frac12\\sqrt{16+e^{x/2}}$\n(c) $\\text{(i) }x_2=-2.0229;\\qquad\\text{(ii) }x_P=-2.0226$","steps":[{"title":"Part (a)","body":"Write $f(x)=(x^3-4x)e^{-x/2}$. By the product rule,\n\n\\[f'(x)=(3x^2-4)e^{-x/2}-\\frac12(x^3-4x)e^{-x/2} =e^{-x/2}\\left(-\\frac{x^3}{2}+3x^2+2x-4\\right).\\]\n\n\\[\\boxed{f^{\\prime}(x)=e^{-x/2}(-x^3/2+3x^2+2x-4)}\\]"},{"title":"Part (b)","body":"At O, $f'(0)=-4$, so the normal gradient is $1/4$ and its equation is $y=x/4$. At the other intersection P, x is nonzero; equating curve and normal and dividing by x gives $(x^2-4)e^{-x/2}=1/4$. Thus $x^2=4+e^{x/2}/4=(16+e^{x/2})/4$. Since P lies in the third quadrant, select the negative square root.\n\n\\[\\boxed{x=-\\frac12\\sqrt{16+e^{x/2}}}\\]"},{"title":"Part (c)","body":"Starting from $x_1=-2$, $x_2=-\\tfrac12\\sqrt{16+e^{-1}}=-2.0228617996\\ldots$. Further unrounded iterates are $x_3=-2.0226034084\\ldots$, $x_4=-2.0226063126\\ldots$ and $x_5=-2.0226062799\\ldots$. The continuing sequence settles at $-2.0226062803\\ldots$.\n\n\\[\\boxed{\\text{(i) }x_2=-2.0229;\\qquad\\text{(ii) }x_P=-2.0226}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2022_MayJune_Q08","year":2022,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2022","qNo":8,"marks":12,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation","12_Integration"],"secondaryTopicNames":["Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation","Integration"],"topics":["13_NumericalMethods","08_ExponentialsLogs","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Numerical Methods","Exponentials & Logarithms","Differentiation Techniques","Applications of Differentiation","Integration"],"image":"ial/wma13/questions/WMA13-01_Y2022_MayJune_Q08_M12_13_NumericalMethods.png","downloadName":"WMA13-01_Y2022_MayJune_Q08_M12_13_NumericalMethods.png","finalAnswer":"(a) $v_{\\max}=11.9\\ \\mathrm{m\\,s^{-1}}$\n(b) $T=\\frac1{12}(116-16e^{-0.75T}+e^{T-10}-e^{-10})$\n(c) $T_2=9.7493,\\qquad T=9.7293\\ \\mathrm{s}$","steps":[{"title":"Part (a)","body":"Differentiate the velocity:\n\n\\[v'(t)=-e^{t-10}+9e^{-0.75t}.\\]\n\nAt a stationary velocity, $e^{t-10}=9e^{-0.75t}$, so $e^{1.75t}=9e^{10}$ and $t=(10+\\ln9)/1.75=6.9698426\\ldots$ seconds. The second derivative $-e^{t-10}-6.75e^{-0.75t}$ is negative, so this is a maximum. Substitute this unrounded time into v to get $11.88728125\\ldots$ metres per second.\n\n\\[\\boxed{v_{\\max}=11.9\\ \\mathrm{m\\,s^{-1}}}\\]"},{"title":"Part (b)","body":"Integrating the velocity gives $12t-e^{t-10}+16e^{-0.75t}$. Evaluate between 0 and T:\n\n\\[100=12T-e^{T-10}+16e^{-0.75T}-(-e^{-10}+16).\\]\n\nRearrange to $12T=116-16e^{-0.75T}+e^{T-10}-e^{-10}$ and divide by 12.\n\n\\[\\boxed{T=\\frac1{12}(116-16e^{-0.75T}+e^{T-10}-e^{-10})}\\]"},{"title":"Part (c)","body":"With $T_1=10$, substitution gives $T_2=9.7492587708\\ldots$. Continuing with unrounded values gives\n\n\\[T_3=9.7306248365\\ldots,\\quad T_4=9.7294150526\\ldots,\\quad T_5=9.7293372715\\ldots,\\quad T_6=9.7293322738\\ldots.\\]\n\nFurther iteration settles at $9.7293319307\\ldots$ seconds. Thus (i) $T_2=9.7493$ and (ii) the race time is $9.7293$ seconds, to four decimal places.\n\n\\[\\boxed{T_2=9.7493,\\qquad T=9.7293\\ \\mathrm{s}}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Jan_Q09","year":2023,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2023","qNo":9,"marks":11,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"topics":["13_NumericalMethods","01_RationalAlgebra","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Numerical Methods","Rational Algebra","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2023_Jan_Q09_M11_13_NumericalMethods.png","downloadName":"WMA13-01_Y2023_Jan_Q09_M11_13_NumericalMethods.png","finalAnswer":"(a) $\\frac{dy}{dx}=\\frac{4xe^{x^2}}{\\sqrt{3+4e^{x^2}}}$\n(b) $4x^2e^{x^2}-4e^{x^2}-3=0$\n(c) $1\\lt \\alpha\\lt 2$\n(d) $x=\\frac12\\sqrt{4+3e^{-x^2}}$\n(e) $x_3=1.0997,\\qquad\\alpha=1.1051$","steps":[{"title":"Part (a)","body":"Differentiate $y=(3+4e^{x^2})^{1/2}$ using the chain rule:\n\n\\[\\frac{dy}{dx}=\\frac12(3+4e^{x^2})^{-1/2}\\cdot4e^{x^2}\\cdot2x =\\frac{4xe^{x^2}}{\\sqrt{3+4e^{x^2}}}.\\]\n\n\\[\\boxed{\\frac{dy}{dx}=\\frac{4xe^{x^2}}{\\sqrt{3+4e^{x^2}}}}\\]"},{"title":"Part (b)","body":"Since the tangent at $P=(\\alpha,\\sqrt{3+4e^{\\alpha^2}})$ passes through the origin, its gradient is $y_P/\\alpha$, with $\\alpha\\gt 0$. Equate this to the derivative:\n\n\\[\\frac{4\\alpha e^{\\alpha^2}}{\\sqrt{3+4e^{\\alpha^2}}} =\\frac{\\sqrt{3+4e^{\\alpha^2}}}{\\alpha} \\quad\\Longrightarrow\\quad4\\alpha^2e^{\\alpha^2}=3+4e^{\\alpha^2}.\\]\n\nConsequently $x=\\alpha$ solves the displayed equation.\n\n\\[\\boxed{4x^2e^{x^2}-4e^{x^2}-3=0}\\]"},{"title":"Part (c)","body":"Let $h(x)=4x^2e^{x^2}-4e^{x^2}-3$, a continuous function. Then $h(1)=-3\\lt 0$ and $h(2)=12e^4-3=652.1778\\ldots\\gt 0$, so a root lies between 1 and 2. Moreover $h'(x)=8x^3e^{x^2}\\gt 0$ for $x\\gt 0$, so this is the unique positive root corresponding to the tangent abscissa $\\alpha$.\n\n\\[\\boxed{1\\lt \\alpha\\lt 2}\\]"},{"title":"Part (d)","body":"From $4x^2e^{x^2}=4e^{x^2}+3$, divide by the positive $e^{x^2}$ to get $4x^2=4+3e^{-x^2}$. The source domain has $x\\ge0$, so take the positive square root.\n\n\\[\\boxed{x=\\frac12\\sqrt{4+3e^{-x^2}}}\\]"},{"title":"Part (e)","body":"With $x_1=1$, the unrounded iterates start\n\n\\[x_2=1.1295616764\\ldots,\\quad x_3=1.0997193683\\ldots,\\quad x_4=1.1062486441\\ldots,\\quad x_5=1.1048012899\\ldots.\\]\n\nContinue: $x_6=1.1051212304\\ldots$, $x_7=1.1050504628\\ldots$, $x_8=1.1050661137\\ldots$, $x_9=1.1050626523\\ldots$; further iteration settles at $1.1050632792\\ldots$. Therefore (i) $x_3=1.0997$ and (ii) $\\alpha=1.1051$, both to four decimal places.\n\n\\[\\boxed{x_3=1.0997,\\qquad\\alpha=1.1051}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_MayJune_Q01","year":2023,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2023","qNo":1,"marks":5,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":[],"secondaryTopicNames":[],"topics":["13_NumericalMethods"],"topicNames":["Numerical Methods"],"image":"ial/wma13/questions/WMA13-01_Y2023_MayJune_Q01_M05_13_NumericalMethods.png","downloadName":"WMA13-01_Y2023_MayJune_Q01_M05_13_NumericalMethods.png","finalAnswer":"(a) $3\\lt \\alpha\\lt 4$\n(b) $x_2=3.1591,\\qquad\\alpha=3.1589$","steps":[{"title":"Part (a)","body":"The polynomial $g$ is continuous on $[3,4]$.\n\n\\[g(3)=729+6-1000=-265\\lt 0,\\qquad g(4)=4096+8-1000=3104\\gt 0.\\]\n\nThere is a sign change, so the intermediate value theorem gives a root strictly between 3 and 4.\n\n\\[\\boxed{3\\lt \\alpha\\lt 4}\\]"},{"title":"Part (b)","body":"(i) With $x_1=3$, $x_2=\\sqrt[6]{994}=3.1591074477\\ldots$. (ii) Retaining unrounded values gives\n\n\\[x_3=3.1589388680\\ldots,\\quad x_4=3.1589390467\\ldots,\\quad x_5=3.1589390465\\ldots.\\]\n\nFurther iteration leaves the displayed four decimal places unchanged.\n\n\\[\\boxed{x_2=3.1591,\\qquad\\alpha=3.1589}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2023_Oct_Q01","year":2023,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2023","qNo":1,"marks":5,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":[],"secondaryTopicNames":[],"topics":["13_NumericalMethods"],"topicNames":["Numerical Methods"],"image":"ial/wma13/questions/WMA13-01_Y2023_Oct_Q01_M05_13_NumericalMethods.png","downloadName":"WMA13-01_Y2023_Oct_Q01_M05_13_NumericalMethods.png","finalAnswer":"(a) $1\\lt \\alpha\\lt 2$\n(b) $x_2=1.5105,\\qquad\\alpha=1.7340$","steps":[{"title":"Part (a)","body":"The function $f(x)=x^2-5x+e^x$ is continuous on $[1,2]$.\n\n\\[f(1)=e-4=-1.2817\\ldots\\lt 0,\\qquad f(2)=e^2-6=1.3891\\ldots\\gt 0.\\]\n\nSince the endpoint values have opposite signs, there is a root strictly between 1 and 2.\n\n\\[\\boxed{1\\lt \\alpha\\lt 2}\\]"},{"title":"Part (b)","body":"Using the given iteration with $x_1=1$,\n\n\\[x_2=\\sqrt{5-e}=1.5105357\\ldots.\\]\n\nContinue with unrounded values:\n\n\\[x_3=1.7388278\\ldots,\\quad x_4=1.7330522\\ldots,\\quad x_5=1.7341754\\ldots,\\quad x_6=1.7339613\\ldots.\\]\n\nSubsequent iterates are $1.7340023\\ldots,1.7339945\\ldots,1.7339960\\ldots$, which settle to $1.7339957\\ldots$. Thus (i) $x_2=1.5105$ and (ii) $\\alpha=1.7340$, each to 4 decimal places.\n\n\\[\\boxed{x_2=1.5105,\\qquad\\alpha=1.7340}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2024_Jan_Q02","year":2024,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2024","qNo":2,"marks":6,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["13_NumericalMethods","01_RationalAlgebra"],"topicNames":["Numerical Methods","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2024_Jan_Q02_M06_13_NumericalMethods.png","downloadName":"WMA13-01_Y2024_Jan_Q02_M06_13_NumericalMethods.png","finalAnswer":"(a) $2\\lt \\alpha\\lt 3$\n(b) $x=\\sqrt[3]{\\frac{5x^2-4x+7}{x}}$\n(c) $x_2=2.1179,\\quad\\alpha=2.1565$","steps":[{"title":"Part (a)","body":"For $f(x)=x^4-5x^2+4x-7$,\n\n\\[f(2)=16-20+8-7=-3,\\qquad f(3)=81-45+12-7=41.\\]\n\nThe polynomial is continuous on $[2,3]$ and the endpoint values have opposite signs. Therefore a root lies strictly between 2 and 3.\n\n\\[\\boxed{2\\lt \\alpha\\lt 3}\\]"},{"title":"Part (b)","body":"Rearrange $x^4-5x^2+4x-7=0$ to $x^4=5x^2-4x+7$. Since $f(0)=-7$, zero is not a root, so division by $x$ is valid at a root:\n\n\\[x^3=\\frac{5x^2-4x+7}{x}.\\]\n\nTaking the real cube root gives the requested form.\n\n\\[\\boxed{x=\\sqrt[3]{\\frac{5x^2-4x+7}{x}}}\\]"},{"title":"Part (c)","body":"With $x_1=2$,\n\n\\[x_2=\\sqrt[3]{\\frac{5(2)^2-4(2)+7}{2}}=\\sqrt[3]{\\frac{19}{2}}=2.117911792\\ldots.\\]\n\nContinue using unrounded intermediate values: $x_3=2.146846021\\ldots$, $x_4=2.154063147\\ldots$, $x_5=2.155869187\\ldots$, $x_6=2.156321484\\ldots$. Further iteration gives $x_{10}=2.156472046\\ldots$ and $x_{13}=2.156472632\\ldots$.\n\n\\[\\boxed{x_2=2.1179,\\quad\\alpha=2.1565}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Jan_Q01","year":2025,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2025","qNo":1,"marks":6,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["06_TrigIdentities"],"secondaryTopicNames":["Trig Identities & Exact Values"],"topics":["13_NumericalMethods","06_TrigIdentities"],"topicNames":["Numerical Methods","Trig Identities & Exact Values"],"image":"ial/wma13/questions/WMA13-01_Y2025_Jan_Q01_M06_13_NumericalMethods.png","downloadName":"WMA13-01_Y2025_Jan_Q01_M06_13_NumericalMethods.png","finalAnswer":"(a) $0.1\\lt \\alpha\\lt 0.2$\n(b) $x=\\frac12-\\frac{1}{3\\cos x}$\n(c)(i) $x_2=0.1629$\n(c)(ii) $\\alpha=0.1622$","steps":[{"title":"Part (a)","body":"Work in radians. Substituting the endpoints into $f(x)=2\\sec x+6x-3$ gives\n\n\\[f(0.1)=-0.3899581632\\ldots\\lt 0,\\qquad f(0.2)=0.2406776899\\ldots\\gt 0.\\]\n\nThe function is continuous on $[0.1,0.2]$ since $\\cos x\\ne0$ there. The sign change therefore places a root between the endpoints. Since the given root is unique, this root is $\\alpha$.\n\n\\[\\boxed{0.1\\lt \\alpha\\lt 0.2}\\]"},{"title":"Part (b)","body":"Set $f(x)=0$ and use $\\sec x=1/\\cos x$:\n\n\\[\\frac{2}{\\cos x}+6x-3=0 \\ \\Longrightarrow\\ 6x=3-\\frac{2}{\\cos x} \\ \\Longrightarrow\\ x=\\frac12-\\frac{1}{3\\cos x}.\\]\n\nThus $\\alpha$, which satisfies $f(\\alpha)=0$, satisfies this rearranged equation.\n\n\\[\\boxed{x=\\frac12-\\frac{1}{3\\cos x}}\\]"},{"title":"Part (c)(i)","body":"With $x_1=0.15$ and angles in radians,\n\n\\[x_2=\\frac12-\\frac{1}{3\\cos(0.15)}=0.1628811858\\ldots.\\]\n\nRound only the displayed result to four decimal places.\n\n\\[\\boxed{x_2=0.1629}\\]"},{"title":"Part (c)(ii)","body":"Continuing the iteration with unrounded internal values gives\n\n\\[x_3=0.1621955413\\ldots,\\quad x_4=0.1622335203\\ldots,\\quad x_5=0.1622314210\\ldots,\\quad x_6=0.1622315370\\ldots.\\]\n\nThe iterates settle at $0.16223153\\ldots$, giving the root to four decimal places.\n\n\\[\\boxed{\\alpha=0.1622}\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_MayJune_Q07","year":2025,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2025","qNo":7,"marks":9,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques","Applications of Differentiation"],"topics":["13_NumericalMethods","06_TrigIdentities","07_TrigEquations","10_DifferentiationTechniques","11_ApplicationsOfDifferentiation"],"topicNames":["Numerical Methods","Trig Identities & Exact Values","Trig Equations & R-Form","Differentiation Techniques","Applications of Differentiation"],"image":"ial/wma13/questions/WMA13-01_Y2025_MayJune_Q07_M09_13_NumericalMethods.png","downloadName":"WMA13-01_Y2025_MayJune_Q07_M09_13_NumericalMethods.png","finalAnswer":"(a) $x=\\frac13\\arctan\\left(\\frac3{2x}\\right)$\n(b) $x_2=0.4367$, $x_4=0.4307$\n(c) $0.430\\text{ to 3 decimal places}$","steps":[{"title":"Part (a)","body":"Apply the product and chain rules:\n\n\\[\\frac{dy}{dx}=e^{-x^2}\\bigl(3\\cos3x-2x\\sin3x\\bigr).\\]\n\nSince $e^{-x^2}\\gt 0$, a stationary point satisfies\n\n\\[3\\cos3x=2x\\sin3x.\\]\n\nNeither endpoint $x=0,\\pi/3$ is stationary. In the interior $\\sin3x\\gt 0$ and $x\\gt 0$, so $\\cos3x\\gt 0$ at a stationary point and $0\\lt 3x\\lt \\pi/2$. Therefore division and the principal inverse tangent are valid:\n\n\\[\\tan3x=\\frac3{2x}\\quad\\Longrightarrow\\quad \\boxed{x=\\frac13\\arctan\\left(\\frac3{2x}\\right)}.\\]"},{"title":"Part (b)","body":"Work in radians and retain calculator precision between iterations:\n\n\\[x_2=\\frac13\\arctan\\frac3{0.8}=0.4367313117\\ldots,\\]\n\n\\[x_3=0.4291581882\\ldots,\\qquad x_4=0.4307116849\\ldots.\\]\n\nThus (i) $\\boxed{x_2=0.4367}$ and (ii) $\\boxed{x_4=0.4307}$."},{"title":"Part (c)","body":"Let $h(x)=3\\cos3x-2x\\sin3x$, which is continuous. At the rounding boundaries,\n\n\\[h(0.4295)=0.0106861\\ldots\\gt 0,\\qquad h(0.4305)=-0.000598027\\ldots\\lt 0.\\]\n\nThe sign change places a root strictly between $0.4295$ and $0.4305$. On $0\\lt x\\lt \\pi/6$, $h'(x)=-11\\sin3x-6x\\cos3x\\lt 0$, so the stationary root is unique; for $\\pi/6\\leq x\\leq\\pi/3$, $h(x)\\lt 0$. Hence the $x$ coordinate of $P$ is $\\boxed{0.430\\text{ to 3 decimal places}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2025_Oct_Q02","year":2025,"session":"Oct","paperCode":"WMA13-01","paper":"WMA13/01 October 2025","qNo":2,"marks":7,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["01_RationalAlgebra"],"secondaryTopicNames":["Rational Algebra"],"topics":["13_NumericalMethods","01_RationalAlgebra"],"topicNames":["Numerical Methods","Rational Algebra"],"image":"ial/wma13/questions/WMA13-01_Y2025_Oct_Q02_M07_13_NumericalMethods.png","downloadName":"WMA13-01_Y2025_Oct_Q02_M07_13_NumericalMethods.png","finalAnswer":"(a) $A root lies in (1,2) by continuity and opposite endpoint signs$\n(b) Shown, as required.\n(c)(i) $1.1484$\n(c)(ii) $1.1813$","steps":[{"title":"Part (a)","body":"\\[f(1)=e^{-1}-1=-0.632120559\\ldots,\\qquad f(2)=10e^{-2}-\\frac14=1.103352832\\ldots.\\]\n\nThe function is continuous on $[1,2]$ and the endpoint values have opposite signs, so a root $\\alpha$ lies in $(1,2)$."},{"title":"Part (b)","body":"Multiplying $f(x)=0$ by $x^2e^x$, which is nonzero on the stated interval,\n\n\\[x^2(2x^2+3x-4)=e^x \\Longrightarrow 2x^4+3x^3=e^x+4x^2 \\Longrightarrow x^3(2x+3)=e^x+4x^2.\\]\n\nAs $2x+3\\gt 0$ here, divide and take the real cube root:\n\n\\[x=\\sqrt[3]{\\frac{e^x+4x^2}{2x+3}}.\\]"},{"title":"Part (c)(i)","body":"Starting with $x_1=1$ and retaining unrounded values,\n\n\\[x_2=\\left(\\frac{e+4}{5}\\right)^{1/3}=1.103475609\\ldots,\\qquad x_3=\\left(\\frac{e^{x_2}+4x_2^2}{2x_2+3}\\right)^{1/3} =1.148358496\\ldots=1.1484.\\]"},{"title":"Part (c)(ii)","body":"Repeated iteration converges to $1.181331\\ldots$, giving $\\alpha=1.1813$ to four decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_Jan_Q01","year":2026,"session":"Jan","paperCode":"WMA13-01","paper":"WMA13/01 January 2026","qNo":1,"marks":6,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["07_TrigEquations"],"secondaryTopicNames":["Trig Equations & R-Form"],"topics":["13_NumericalMethods","07_TrigEquations"],"topicNames":["Numerical Methods","Trig Equations & R-Form"],"image":"ial/wma13/questions/WMA13-01_Y2026_Jan_Q01_M06_13_NumericalMethods.png","downloadName":"WMA13-01_Y2026_Jan_Q01_M06_13_NumericalMethods.png","finalAnswer":"(a) $a root $\\alpha$ lies between $0.7$ and $0.8$$\n(b) $p=\\frac35$\n(c)(i) $0.7866$\n(c)(ii) $\\alpha=0.7589$","steps":[{"title":"Part (a)","body":"Let $g(x)=3x-5+5\\sin(x^2)$. Using radians,\n\n\\[g(0.7)=-0.546870559\\ldots,\\qquad g(0.8)=0.385977207\\ldots.\\]\n\nSince $g$ is continuous and changes sign, a root $\\alpha$ lies between $0.7$ and $0.8$."},{"title":"Part (b)","body":"\\[3x-5+5\\sin(x^2)=0 \\quad\\Longrightarrow\\quad \\sin(x^2)=1-\\frac35x.\\]\n\nOn the stated root interval, $0.49\\lt x^2\\lt 0.64\\lt \\pi/2$, so the principal inverse sine and positive square root give\n\n\\[x=\\sqrt{\\arcsin(1-\\tfrac35x)},\\qquad p=\\frac35.\\]"},{"title":"Part (c)(i)","body":"Starting with $x_1=0.7$,\n\n\\[x_2=\\sqrt{\\arcsin(1-0.6(0.7))}=0.786593091\\ldots=0.7866.\\]"},{"title":"Part (c)(ii)","body":"Continue $x_{n+1}=\\sqrt{\\arcsin(1-0.6x_n)}$ in radians, retaining the full calculator values. The iterates converge to $0.758924378\\ldots$, so\n\n\\[\\alpha=0.7589\\quad\\text{(4 decimal places)}.\\]"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"},{"id":"WMA13-01_2026_MayJune_Q01","year":2026,"session":"MayJune","paperCode":"WMA13-01","paper":"WMA13/01 May/June 2026","qNo":1,"marks":8,"topic":"13_NumericalMethods","topicName":"Numerical Methods","primaryTopic":"13_NumericalMethods","primaryTopicName":"Numerical Methods","secondaryTopics":["10_DifferentiationTechniques"],"secondaryTopicNames":["Differentiation Techniques"],"topics":["13_NumericalMethods","10_DifferentiationTechniques"],"topicNames":["Numerical Methods","Differentiation Techniques"],"image":"ial/wma13/questions/WMA13-01_Y2026_MayJune_Q01_M08_13_NumericalMethods.png","downloadName":"WMA13-01_Y2026_MayJune_Q01_M08_13_NumericalMethods.png","finalAnswer":"(a) $2x^2-6x+5-4xe^{2x}$\n(b) $\\alpha\\in(0,1)$\n(c)(i) $x_3=0.3260$\n(c)(ii) $\\alpha=0.3675$","steps":[{"title":"Part (a)","body":"Apply the product rule to the exponential term:\n\n\\[f'(x)=2x^2-6x+5+2e^{2x}(1-2x)-2e^{2x} =\\boxed{2x^2-6x+5-4xe^{2x}}.\\]"},{"title":"Part (b)","body":"The derivative is continuous on $[0,1]$, and\n\n\\[f'(0)=5\\gt 0,\\qquad f'(1)=1-4e^2\\approx-28.5562\\lt 0.\\]\n\nThe change of sign therefore places a zero of $f'$ between 0 and 1. Since the zero is unique, $\\boxed{\\alpha\\in(0,1)}$, and hence it is in $[0,1]$."},{"title":"Part (c)(i)","body":"Start at $x_1=0$, retaining unrounded values in each substitution:\n\n\\[x_2=\\frac{2(0)^2+5}{4e^0+6}=0.5,\\qquad x_3=\\frac{2(0.5)^2+5}{4e^1+6}=0.3259620992\\ldots.\\]\n\nThus $\\boxed{x_3=0.3260}$ to 4 decimal places."},{"title":"Part (c)(ii)","body":"Continuing the supplied iteration gives\n\n\\[\\begin{array}{c|rrrrrr} n&4&5&6&7&8&9\\\\\\hline x_n&0.381116669&0.363053595&0.368908652&0.367004338&0.367623025&0.367421950 \\end{array}\\]\n\n\\[x_{10}=0.3674872922,\\quad x_{11}=0.3674660574,\\quad x_{12}=0.3674729582,\\quad x_{13}=0.3674707156.\\]\n\nFurther iteration stabilises at $0.367471265\\ldots$, so $\\boxed{\\alpha=0.3675}$ to 4 decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-10-20T00:00:00"}];
